	\section{Optimal promotions on infinite complete networks}
	\label{sec:infinite}
	In section~\ref{sec:gen} we saw that it is difficult to compute the optimal promotion on general networks. Then in section~\ref{sec:finite} we showed that the optimal promotion on complete homogeneous networks with $M$~nodes is the solution of 
	$M$ coupled boundary-value problems. We now show that on infinite complete networks the optimal promotion can be reduced to a single boundary-value problem with two equations, without introducing any approximation. This will enable us not only to compute numerically the optimal strategy, but also to analyze its properties. To do this, we first recall

	\begin{theorem}[\cite{Bass-monotone-convergence-23}]
		\label{thm:complete_convergence}
		Let $f^{\rm complete}(t;p(t),q(t),M)$ denote the expected adoption level in the Bass model~\eqref{eqs:Bass-model} on the complete network~\eqref{eq:complete} with time-dependent parameters
		$p(t)$ and~$q(t)$. Then $\lim\limits_{M\to\infty}f^{\rm complete}=f^{\rm compart}$, where $f^{\rm compart}(t; p(t),q(t))$ is the solution of the compartmental Bass model with time-dependent parameters
		\begin{equation}
			\label{eq:complete_limit}
			\frac{df}{dt}=(1-f)\Big(p(t)+q(t)f\Big), \qquad f(0)=0.
		\end{equation}
	\end{theorem}
	The reduction of the system of $M$~master equations to a single ordinary differential equation enables us to express the optimal promotion as the solution of a single boundary-value problem:
	\begin{theorem}
		\label{lem:opt_complete_pq}
		Consider the Bass model~\eqref{eqs:Bass-model} on the homogeneous complete network~\eqref{eq:complete} as $M\to\infty$. Then the optimal promotion ${\bf s}^{\rm opt}:=(s_p^{\rm opt}, s_q^{\rm opt})$, see~\eqref{eq:profit}, satisfies the equation
		\begin{equation}
			\label{eq:H_inf}
			\frac{\partial H}{\partial s_p}=\frac{\partial H}{\partial s_q}=0, \qquad
			H:=\Big(\gamma \frac{df}{dt}-s_p(t)-s_q(t)\Big)e^{-\theta t}+\Psi\frac{df}{dt},
		\end{equation}
		where $f(t)$ and $\Psi(t)$ are the solutions of the boundary-value problem 
		\begin{equation}
			\label{eq:bvp_pq}
			\begin{aligned}
				\frac{df}{dt}&=(1-f)\Big(p(s_p(t))+q(s_q(t))f\Big),\qquad &f(0)=0,\\
				\frac{d\Psi}{dt}&=\left(\gamma e^{-\theta t}+\Psi\right)\Big(p(s_p(t))+q(s_q(t))(2f-1)\Big),\qquad &\Psi(T)=0.
			\end{aligned}
		\end{equation}
	\end{theorem}
	\begin{proof}
		See Appendix~\ref{app:lem:opt_complete_pq}.
	\end{proof}
	\begin{corollary}
		\label{cor:opt_complete_pq}
		Assume the conditions of Theorem~{\rm \ref{lem:opt_complete_pq}}. Let the effect of the promotion be given by~\eqref{eq:p_q_s}. Then equation~\eqref{eq:H_inf} reduces to
		\begin{equation}
			\label{eq:s_lambda_pq}
			s^{\rm opt}_p(t)=\frac{b_p^2}{4}\left((1-f)(\Psi e^{\theta t}+\gamma)\right)^2,\qquad
			s^{\rm opt}_q(t)=\frac{b_q^2}{b_p^2}f^2s^{\rm opt}_p(t).
		\end{equation}
	\end{corollary}
	\begin{proof}
		See Appendix~\ref{app:cor:opt_complete_pq}.
	\end{proof}
	As could be expected from Theorem~\ref{thm:complete_convergence}, the optimal promotion on infinite complete networks~(Figure~\ref{fig:pq_opt}A) is close to that on a complete network with $M=100$ nodes (Figure~\ref{fig:pq_opt_M}D).

