	\subsection{Initial and final stages}
	\label{sec:init}

	We can analyze the behavior of $s_p^{\rm opt}(t)$ and $s_q^{\rm opt}(t)$ at the beginning of the promotion:
	\begin{corollary}
		\label{cor:sp_prime_zero}
		Assume the conditions of Corollary~{\rm \ref{cor:opt_complete_pq}}. Assume also that $q_0>\theta$. Then 
		$$
		s_p^{\rm opt}(0)>0, \qquad \frac{d}{dt}s_p^{\rm opt}(0)<0.
		$$
	\end{corollary}
	\begin{proof}
		See Appendix~\ref{app:cor_sp_prime_zero}.
	\end{proof}
	Therefore, $s_p^{\rm opt}(t)$ initially decreases, which is consistent with the discussion in Section~\ref{sec:Emerging-picture}.

	\begin{corollary}
		\label{cor:s(0)}
		Assume the conditions of Corollary~{\rm \ref{cor:sp_prime_zero}}. Then
		\begin{equation*}
			s_q^{\rm opt}(0)=0, \qquad \frac{d}{dt}{s_q^{\rm opt}}(0)=0, \qquad \frac{d^2}{dt^2}s_q^{\rm opt}(0)=2\frac{b_q^2}{b_p^2}s^{\rm opt}_p(0)>0.
		\end{equation*}
	\end{corollary}
	\begin{proof}
		Since $f(0)=0$, this follows from~\eqref{eq:s_lambda_pq} and Corollary~\ref{cor:sp_prime_zero}.
	\end{proof}
	Thus, $s_q^{\rm opt}(t)$ starts from zero and initially increases. Indeed, there is no point in enhancing peer effects at $t=0$, since there are no adopters. Furthermore, as the number of adopters initially increases, so does $s_q^{\rm opt}(t)$. Note that Corollary~\ref{cor:s(0)} shows that if $T$ is sufficiently small, $s_q^{\rm opt}(t)$ is increasing in $0\leq t\leq T$, which is consistent with~\cite{Dockner-1988}.


	Let us consider the adoption level and the spending rate at the end of the planning horizon:
	\begin{corollary}
		\label{cor:s_infty}
		Assume the conditions of Corollary~{\rm \ref{cor:opt_complete_pq}}.
		\begin{enumerate}
			\item 
			If $T<\infty$, then $f^{\rm opt}(T)<1$, $s_p^{\rm opt}(T)>0$, and $s_q^{\rm opt}(T)>0$.
			\item 
			If $T=\infty$, then $\lim\limits_{t\to\infty}f^{\rm opt}(t)=1$ and
			$
			\lim\limits_{t\to\infty}s_p^{\rm opt}(t)=\lim\limits_{t\to\infty}s_q^{\rm opt}(t)=0.
			$
		\end{enumerate}
	\end{corollary}
	\begin{proof}
		See appendix~\ref{app:cor:s_infty}.
	\end{proof}

	Thus, when $T<\infty$, there exist nonadopters as $t\to T$ even in the presence of the optimal promotion, see Figure~\ref{fig:T20_opt}B. Therefore, the promotion continues until the last minute, see Figure~\ref{fig:T20_opt}A. In contrast, when $T$ is infinite there are no non-adopters  as $t\to\infty$, and so $s_p^{\rm opt}$ and $s_q^{\rm opt}$ vanish as $t\to T$, see Figure~\ref{fig:pq_opt}.

