	\section{Optimal promotions on infinite lines}
	\label{sec:line}

	Consider now the ``opposite'' of a complete network, where each node can only be influenced by two nodes. Specifically, we consider the infinite homogeneous discrete line $\mathbb{Z}=\{\dots,-1,0,1,\dots\},$ where each node can be influenced by its two nearest neighbors. Thus, 
	\begin{equation}
		\label{eq:circle_conditions}
		p_j(t)=p(t),\qquad q_{k\to j}(t)=\frac{q(t)}{2}\mathbbm{1}_{|k-j|=1}, \qquad k,j\in\mathbb{Z}.
	\end{equation}
	Therefore, the adoption rate of node $j$ is
	$$
	\lambda_j^{\rm 1D}(t)= p(t)+\frac{q(t) }{2}\Big(X_{j-1}(t)+X_{j+1}(t)\Big), \qquad j\in\mathbb{Z}.
	$$

	The aggregate dynamics on the infinite line can also be reduced to a single ordinary differential equation:
	\begin{theorem}[\cite{Bass-monotone-convergence-23}]
		\label{thm:circle_convergence}
		Let $f^{\rm 1D}(t;p(t),q(t))$ denote the expected adoption level in the Bass model~\eqref{eqs:Bass-model} on the infinite line with time-dependent parameters~\eqref{eq:circle_conditions}. Then $f^{\rm 1D}(t)$ is the solution of the equation
		\begin{equation}
			\label{eq:circle_limit}
			\frac{df}{dt}=\left(p(t)+q(t)\Big(1-e^{-\int_{0}^{t}p}\Big)\right)\left(1-f\right), \qquad f(0)=0.
		\end{equation}
	\end{theorem}

	This exact reduction enables us to formulate the optimal promotion as a boundary-value problem with four equations:\footnote{There are four rather than two equations due to the introduction of the state variable $y$. This variable is needed, since the optimal promotion is found by computing $\frac{\partial H}{\partial s_p}$, and without $y$, $s_p$ would appear within an integral, see~\eqref{eq:circle_limit}.}
	\begin{theorem}
		\label{lem:opt_circle_pq}
		Consider the Bass model~\eqref{eqs:Bass-model} on the homogeneous infinite line~\eqref{eq:circle_conditions}. Let $f(t)$, $y(t)$, $\Psi_1(t)$, and $\Psi_2(t)$ be the solutions of the boundary-value problem 
		\begin{equation}
			\label{eq:bvp_pq_circle}
			\begin{aligned}
				\frac{df}{dt}&=\left(p(s_p(t))+q(s_q(t))(1-e^{-y})\right)\left(1-f\right), &f(0)=0,\\
				\frac{dy}{dt}&=p(s_p(t)),   &y(0)=0,\\
				\frac{d\Psi_1}{dt}
				&=(\gamma e^{-\theta t}+\Psi_1) \left(p(s_p(t))+q(s_q(t))(1-e^{-y})\right),  &\Psi_1(T)=0,\\
				\frac{d\Psi_2}{dt}
				&=-(\gamma e^{-\theta t}+\Psi_1)(1-f)q(s_q(t))e^{-y}, &\Psi_2(T)=0.
			\end{aligned}
		\end{equation}
		Then the optimal promotion ${\bf s}^{\rm opt}:=(s_p^{\rm opt}, s_q^{\rm opt})$, see~\eqref{eq:profit}, satisfies the condition
		\begin{equation}
			\label{eq:H_line}
			\frac{\partial H}{\partial s_p}=\frac{\partial H}{\partial s_q}=0, \qquad
			H:=\Big(\gamma\frac{df}{dt}-s_p(t)-s_q(t)\Big)e^{-\theta t}+\Psi_1\frac{df}{dt}+\Psi_2p(s_p(t)).
		\end{equation}
	\end{theorem}
	\begin{corollary}
		\label{cor:opt_circle_pq}
		Assume the conditions of Theorem~{\rm \ref{lem:opt_circle_pq}}. Let the effect of the promotion be given by~\eqref{eq:p_q_s}. Then equation~\eqref{eq:H_line} reduces to
		\begin{equation}
			\label{eq:s_lambda_pq_circle}
			s^{\rm opt}_p(t)=\frac{b_p^2}{4}\Big((\gamma +\Psi_1e^{\theta t})(1-f)+\Psi_2 e^{\theta t}\Big)^2,\quad
			s^{\rm opt}_q(t)=\frac{b_q^2}{4}\Big((\gamma +\Psi_1e^{\theta t})(1-f)(1-e^{-y})\Big)^2.
		\end{equation}
	\end{corollary}
