		\section{Optimal strategies on infinite heterogeneous complete networks}
		\label{sec:heterogeneous}

		In order to allow for heterogeneity among consumers, we consider a complete heterogeneous network that consists of two equal-size groups denoted by $\mathcal{M}_1:=\{1,\dots,\frac{M}{2}\}$ and $\mathcal{M}_2:=\{\frac{M}{2}+1,\dots,M\}$, each of which is homogeneous. %This situation can arise, e.g., when we divide the population into two groups according to income level. 
		For any node in group~$\mathcal{M}_k$, the external and internal influence rates are~$p^k(t)$ and ~$q^k(t)$, i.e.,
		\begin{equation}
			\label{eq:het_conditions}
			p_{j}(t):=p^k(t),\qquad q_{m\to j}(t)=\frac{q^k(t)}{M-1}\mathbbm{1}_{m\neq j},\qquad j\in \mathcal{M}_k, \qquad m\in\mathcal{M}, \qquad k=1,2.
		\end{equation}
		%\begin{equation*}
		%	p_j=\begin{cases}
			%		p_1(t), & j=1,\dots,\frac{M}{2},\\
			%		p_2(t), & j=\frac{M}{2}+1,\dots,M,
			%	\end{cases} \qquad q_{n,j}=\begin{cases}
			%	\frac{q_1(t)}{M-1}, & j=1,\dots,\frac{M}{2},\\
			%	\frac{q_2(t)}{M-1}, & j=\frac{M}{2}+1,\dots,M.
			%	\end{cases}
		%\end{equation*}
		Hence, the adoption rate of node $j$ is
		\begin{equation*}
			\label{eq:discrete_group_model}
			\lambda_j(t)=p^{k}(t)+\frac{q^k(t)}{M-1}N(t),\qquad j\in\mathcal{M}_k, \qquad k=1,2,
		\end{equation*}
		where $N(t)=\sum_{j=1}^{M}X_j(t)$ is the number of adopters at time~$t$. We also allow the two groups to differ in their response to the promotion, so that if we apply the same promotion $(s_p,s_q)$ to both groups, then
		\begin{equation}
			\label{eq:p_q_s_het}
			p^k(s_{p}):=p_0^k+b_{p}^k\sqrt{s_p}, \qquad q^k(s_{q}):=q_0^k+b_{q}^k\sqrt{s_q}, \qquad k=1,2, \qquad s_p,s_q\geq 0.
		\end{equation}
		%\begin{equation}
		%	\label{eq:discrete_group_model}
		%	\lambda_{k}(t)=\begin{cases}
			%		p_1(t)+\frac{q_1(t)}{M-1}\sum_{i=1}^{M}X_i(t), & k=1,\dots,\frac{M}{2},\\
			%		p_2(t)+\frac{q_2(t)}{M-1}\sum_{i=1}^{M}X_i(t), & k=\frac{M}{2}+1,\dots,M.
			%	\end{cases}
		%\end{equation}

		Let us denote the expected adoption level by
		$
		f^{\rm complete-het}(t)=f_{1}^{\rm complete}(t)+f_{2}^{\rm complete}(t),
		$
		where $f_{k}^{\rm complete}(t):=\frac{1}{M}\sum_{j\in\mathcal{M}_k}\E[X_j]$ is the expected population fraction of adopters from group $\mathcal{M}_k$.
		%When $p_k$ and $q_k$ are constant, the ODE for $\lim\limits_{M\to\infty}f_k^{\rm complete}(t;p,q,M_k,M)$ is~\cite{fibich2021diffusion}
		%\begin{equation*}
		%	\frac{df_k}{dt}=(\alpha_k-f_k)\left(p_k+q_k\sum_{i=1}^Kf_i\right),\qquad f_k(0)=0,\qquad k=1,\dots,K.
		%\end{equation*}
		%In this case, substituing $p(t)$ and $q(t)$ for $p$ and $q$ yields the correct limit.
		As in the homogeneous case, as $M\to\infty$, the heterogeneous complete network model approaches the corresponding heterogeneous compartmental model:
		\begin{theorem}[\cite{Bass-monotone-convergence-23}]
			\label{thm:groups_convergence}
			Consider the Bass model~{\rm (\ref{eqs:Bass-model},~\ref{eq:het_conditions})} on a heterogeneous complete network with two homogeneous groups of equal size and with time-dependent parameters. Then $\lim\limits_{M\to\infty}f^{\rm complete-het}=f_1^{\rm compart-het}+f_2^{\rm compart-het}$, where $\big\{f_k^{\rm compart-het}\big\}_{k=1}^2$ are the solutions of the equation
			\begin{equation}
				\label{eq:groups_limit}
				\frac{df_k}{dt}=\Big(\frac{1}{2}-f_k\Big)
				\Big(p^k(t)+q^k(t)(f_1+f_2)\Big),\qquad f_k(0)=0,\qquad k=1,2.
			\end{equation}
		\end{theorem}

