			%		\frac{df_1}{dt}&=(\frac{1}{2}-f_2)\left(p_2+b_{p_2}\sqrt{s_p(t)}+\left(q_2+b_{q_2}\sqrt{s_q(t)}\right)(f_1+f_2)\right),\qquad f_2(0)=0.
