		\section{Proof of Theorem~\ref{thm:gen}}
		\label{app:thm:gen}
		The expected adoption level is 
		\begin{equation}
			\label{eq:exp_adoption}
			f(t)=1-\frac{1}{M}\sum_{j=1}^{M}[S_{j}](t),
		\end{equation}
		see~\eqref{eq:frac_adopters}.
		Therefore, \eqref{eq:5b} can be rewritten as
		\begin{equation}
			\label{eq:profit_general}
			\pi({\bf s}(t))=
			e^{-\theta t} \Big(-\frac{\gamma}{M} \sum_{j=1}^{M}\frac{d[S_j]}{dt}-\big(s_p(t)+s_q(t)\big) \Big).
		\end{equation}
		Let us recall Pontryagin's Maximum Principle from optimal control theory (see e.g.,~\cite{kamienschwartz}):

		\begin{theorem}
			\label{thm:pontryagin}
			Consider the maximization problem
			\begin{equation}
				\label{eq:prob}
				{\bf s}^{\rm opt}(t)={\rm argmax}_{{\bf s}(t)}\Pi\left[{\bf s}(t)\right], \qquad \Pi:=\int_{t=0}^{T}\pi(t, {\bf x}(t), {\bf s}(t))\, dt,
			\end{equation}
			where ${\bf x}(t):=\left(x_1(t),\dots,x_n(t)\right): [0, T]\to\mathbb{R}^n$ is the continuous and differentiable solution of
			\begin{subequations}
				\label{eqs:max_prob}
				\begin{equation}
					\label{eq:f_ode}
					\frac{d{\bf x}}{dt}={\bf g}(t, {\bf x}(t),{\bf s}(t)), \qquad {\bf x}(0)={\bf x}_0,
				\end{equation}
				and ${\bf s}(t):=\left(s_1(t),\dots,s_m(t)\right)\in {\mathcal S}^m$ is the control function.
				Let
				$
				H(t,{\bf x},{\bf s},\boldsymbol{\Psi}):=\pi(t,{\bf x},{\bf s})+\sum_{k=1}^{n}\Psi_k(t)g_k(t,{\bf x},{\bf s}),
				$
				where $\boldsymbol{\Psi}(t)=\left(\Psi_1(t),\dots,\Psi_n(t)\right): [0, T]\to\mathbb{R}^n$, and $\Psi_i(t)$ satisfies
				\begin{equation}
					\label{eq:lambda_ode}
					\frac{d\Psi_i}{dt}=-\frac{\partial H}{\partial x_i}, \qquad \Psi_i(T)=0,\qquad i=1,\dots n.
				\end{equation}
			\end{subequations}
			In order for ${\bf s}^*(t)$ to solve~\eqref{eq:prob}, it is necessary that $\{{\bf x}^*(t),{\bf s}^*(t),\boldsymbol{\Psi}^*(t)\}$ be a solution of the boundary-value problem ~\eqref{eqs:max_prob}, that also satisfies
			\begin{equation}
				\label{eq:s_condition}
				\frac{\partial H(t,{\bf x}^*(t),{\bf s}^*(t),\boldsymbol{\Psi}^*(t))}{\partial s_j}=0, \qquad j=1,\dots,m.
			\end{equation}
		\end{theorem}

		Let us also recall the master equations for the Bass model:
		\begin{theorem}[\cite{fibich2021diffusion}]
			Consider the Bass model~\eqref{eqs:Bass-model}, where $\lambda_j(t)$ is given by~\eqref{eq:pjqj}. Let $\emptyset\neq \Omega \subset \mathcal{M}$, $\Omega^c:=M\setminus\Omega$, and let $p_\Omega$, $q_{k\to\Omega}$, and $[S_{\Omega,k}]$ be given by~\eqref{eq:notations}. 
			Then the master equation for $[S_{\Omega}]$ is
			\begin{equation}
				\label{eq:master_general}
				\frac{d[S_{\Omega}]}{dt}=-\Big(p_\Omega(s_p(t)) +\sum_{k\in\Omega^c}q_{k\to\Omega}(s_q(t))\Big)[S_{\Omega}]+\sum_{k\in\Omega^c}q_{k\to\Omega}(s_q(t))[S_{\Omega,k}],
				%\\
				\quad [S_{\Omega}](0)=1.
			\end{equation}
			%	\begin{equation}
				%	\label{eq:master_general}
				%	\begin{aligned}
					%		\frac{d[S_{\Omega}]}{dt}&=-\left(p_\Omega(t) +|\Omega|b_p\sqrt{s_p(t)}+\left(\sum_{k\in\Omega^c}q_{k,\Omega}(t)+|\Omega|b_q\sqrt{s_q(t)}\right)\right)[S_{\Omega}]+\left(\sum_{k\in\Omega^c}q_{k,\Omega}(t)+|\Omega|b_q\sqrt{s_q(t)}\right)[S_{\Omega,k}],\\
					%		[S_{\Omega}(0)]&=1.
					%	\end{aligned}
				%\end{equation}
			\end{theorem}

			\begin{proof}[Proof of Theorem~{\rm \ref{thm:gen}}]
				Let us apply Theorem~\ref{thm:pontryagin} with $\pi({\bf s}(t))$ given by~\eqref{eq:profit_general}, ${\bf x}:=\{[S_{\Omega}]\}_{\emptyset\neq\Omega\subset\mathcal{M}}$, and ${\bf g}:=\{g_{\Omega}\}_{\emptyset\neq\Omega\subset\mathcal{M}}$, where $g_\Omega$ right-hand side of~\eqref{eq:master_general}, and ${\bf s}(t):=(s_p(t),s_q(t))$. Then, using~\eqref{eq:exp_adoption},
				\begin{equation*}
					H=\Big(-\frac{\gamma}{M} \sum_{j=1}^{M}\frac{d[S_j]}{dt}-\left(s_p+s_q\Big) \right)e^{-\theta t}+\sum_{\emptyset\neq \Omega \subset \mathcal{M}}\Psi_\Omega\frac{d[S_\Omega]}{dt}.
				\end{equation*}
				Substituting the expressions for $\frac{d[S_j]}{dt}$ and $\frac{d[S_\Omega]}{dt}$ from~\eqref{eq:master_general}, we have
				\begin{align*}
					H&=\bigg(-\frac{\gamma}{M} \sum_{j=1}^{M}\Big(-\Big(p_j(s_p) +\sum_{k\neq j}q_{k\to j}(s_q)\Big)[S_j]+\sum_{k\neq j}q_{k\to j}(s_q)[S_{j,k}]\Big)-(s_p+s_q) \bigg)e^{-\theta t}\\
					&\qquad\qquad+\sum_{\emptyset\neq \Omega \subset \mathcal{M}}\Psi_\Omega\bigg(-\Big(p_\Omega(s_p) +\sum_{k\in\Omega^c}q_{k\to\Omega}(s_q)\Big)[S_{\Omega}]+\sum_{k\in\Omega^c}q_{k\to\Omega}(s_q)[S_{\Omega,k}]\bigg).
				\end{align*}
				The differential equation~\eqref{eq:lambda_prime_general} for $\Psi_\Omega$ follows from
				$
				\frac{d\Psi_\Omega}{dt}=-\frac{\partial H}{\partial [S_\Omega]}.
				$
			\end{proof}

