			\begin{equation*}
				0=\frac{\gamma e^{-\theta t} b_p [S]}{1+s_p}-e^{-\theta t}-\sum_{n=1}^{M}\Psi_n\frac{b_p [S^n]}{1+s_p}, \qquad
				0=\frac{\gamma e^{-\theta t} b_q \left([S]-[S^2]\right)}{1+s_q}-e^{-\theta t}-\sum_{n=1}^{M}\Psi_n\frac{b_q \left([S^n]-[S^{n+1}]\right)}{1+s_q},
			\end{equation*}
			respectively, which lead to~\eqref{eq:s_lambda_pq_M_ln}.

