			\section{Proof of Theorem~\ref{lem:opt_complete_pq}}
			\label{app:lem:opt_complete_pq}
			By Theorem~\ref{thm:pontryagin}, any solution of~\eqref{eq:profit} must satisfy $\frac{\partial H}{\partial s_p}=\frac{\partial H}{\partial s_q}=0$, where
			\begin{subequations}
				\label{eqs:ham_pq}
				\begin{equation}
					\label{eq:ham_pq}
					H(t,f(t),s_p(t),s_q(t))=\Big(\gamma \frac{df}{dt}-s_p-s_q\Big)e^{-\theta t}+\Psi\frac{df}{dt},
				\end{equation}
				and
				\begin{equation}
					\label{eq:lambda_pq}
					\frac{d\Psi}{dt}=-\frac{\partial H}{\partial f}, \qquad \Psi(T)=0.
				\end{equation}
			\end{subequations}
			Substituting~\eqref{eq:complete_limit} in~\eqref{eqs:ham_pq} yields
			\begin{subequations}
				\label{eqs:H_lambda_pq}
				\begin{equation*}
					H=\Big(\gamma e^{-\theta t}+\Psi \Big)(1-f)\big(p(s_p)+q(s_q)f\big)-(s_p+s_q)e^{-\theta t},
				\end{equation*}
				and
				\begin{equation*}
					%\label{eq:lambda_prime_pq}
					\frac{d\Psi}{dt}
					=\Big(\gamma e^{-\theta t}+\Psi\Big)\big(p(s_p)+q(s_q)(2f-1)\big), \qquad \Psi(T)=0.
				\end{equation*}
			\end{subequations}
			The condition $\frac{\partial H}{\partial s_p}=\frac{\partial H}{\partial s_q}=0$ follows from~\eqref{eq:s_condition}.

			\section{Proof of Corollary~\ref{cor:opt_complete_pq}}
			\label{app:cor:opt_complete_pq}
			Substituting~\eqref{eq:p_q_s} and~\eqref{eq:bvp_pq} in~\eqref{eq:H_inf}, the equation $\frac{\partial H}{\partial s_p}=\frac{\partial H}{\partial s_q}=0$ yields
			\begin{equation*}
				%\label{eq:neccesary_pq}
				0=\frac{b_p\left(1-f\right)\left(\gamma e^{-\theta t}+\Psi\right)}{2\sqrt{s_p(t)}}-e^{-\theta t}, \qquad
				0=\frac{b_q\left(1-f\right)f\left(\gamma e^{-\theta t}+\Psi\right)}{2\sqrt{s_q(t)}}-e^{-\theta t},
			\end{equation*}
			which leads to~\eqref{eq:s_lambda_pq}.

