			\begin{lemma}
				\label{lem:lambda}
				Let $\tilde{t}=\left(f^{\rm opt}\right)^{-1}(\frac{1}{2})$. Then the solution of~\eqref{eq:bvp_pq} satisfies $-\gamma e^{-\theta t}\leq \Psi(t)\leq 0$ for  $\tilde{t}\leq t<T$.
			\end{lemma}
			\begin{proof}
				Since $s_p(t),s_q(t)\geq 0$, then
				\begin{equation*}
					p_0+b_p\sqrt{s_p(t)}+\Big(q_0+b_q\sqrt{s_q(t)}\Big)(2f-1)\geq p_0>0, \qquad \tilde{t}\leq t\leq T.
				\end{equation*}
				Therefore, by~\eqref{eq:bvp_pq}, the sign of $\frac{d\Psi}{dt}$ is determined by the sign of $A(t):=\gamma e^{-\theta t}+\Psi$. Let $t^*\leq t_1<T$.
				\begin{itemize}
					\item[{\bf Case 1:}]
					If $\Psi(t_1)>0$, then in order to have $\Psi(T)=0$, see~\eqref{eq:bvp_pq}, there must exist $t_2\in (t_1,T)$ such that $\Psi(t_2)>0$ and $\frac{d\Psi}{dt}(t_2)<0$. However, $\Psi(t_2)>0$ implies that $A(t_2)>0$, and hence that $\frac{d\Psi_1}{dt}(t_2)>0$. Contradiction.
					\item[{\bf Case 2:}]
					If $\Psi(t_1)<-\gamma e^{-\theta t_1}$, then $A(t_1)<0$. Since $A(T)=\gamma e^{-\theta T}>0$, there must exist $t_2\in (t_1,T)$ such that $A(t_2)=0$ and $A'(t_2)>0$. However,
					$
					A'(t)=-\gamma\theta e^{-\theta t}+\frac{d\Psi_1}{dt}.
					$
					Since $A(t_2)=0$, then $\frac{d\Psi}{dt}(t_2)=0$, see~\eqref{eq:bvp_pq}. Hence, $A'(t_2)=-\gamma\theta e^{-\theta t_2}<0$. Contradiction.
				\end{itemize}
				Therefore, the result holds
			\end{proof}

			\begin{proof}[Proof of Corollary~{\rm \ref{cor:s_infty}}:]
				Let $T<\infty$. Since $\Psi(t)$ and $f^{\rm opt}(t)$ are continuous, $s_p^{\rm opt}(t)$ and $s_q^{\rm opt}(t)$ are bounded in $[0,T]$, see~\eqref{eq:s_lambda_pq}. Therefore, by~\eqref{eq:bvp_pq},
				$
				\frac{df^{\rm opt}}{dt}\leq (1-f^{\rm opt})K,
				$
				where $K$ is a positive constant. Hence, $f^{\rm opt}(T)<1$, since $f$ cannot converge to the fixed point $f=1$ in finite time. Therefore, by~\eqref{eq:s_lambda_pq}, $s_p^{\rm opt}(T), s_q^{\rm opt}(T)>0$.

				Let $T=\infty$. Since $f$ is bounded from below by the case in which $q=b_p=b_q=0$, then $f(t)>1-e^{-pt}$. Therefore, by~\eqref{eq:s_lambda_pq},
				$
				\label{eq:s_bounds}
				s_p(t)<\frac{b_p^2}{4}\left(e^{-pt}(\Psi e^{\theta t}+\gamma)\right)^2.
				$
				By Lemma~\ref{lem:lambda}, $0\leq \Psi e^{\theta t}+\gamma=\gamma$. Hence, $\lim\limits_{t\to\infty}s_p^{\rm opt}(t)=0$, and so by~\eqref{eq:s_lambda_pq}, $\lim\limits_{t\to\infty}s_q^{\rm opt}(t)=0$.
			\end{proof}



