			\section{Proof of Theorem~\ref{lem:opt_circle_pq}}
			\label{app:lem:opt_circle_pq}

			Let $y:=\int_{0}^{t}p(s_p(\tau))\, d\tau$ be a new state variable. Then
			$\frac{dy}{dt}=p(s_p(t))$ and $y(0)=0$.
			Maximizing~\eqref{eq:profit} on the infinite line~\eqref{eq:circle_conditions} can be formulated as an optimal control problem with the two state variables ${\bf f}(t)=(f_1(t),f_2(t))=(f,y)$ and the two controls $s_p(t)$ and $s_q(t)$. Furthermore, by~\eqref{eq:circle_limit},
			\begin{align*}
				\frac{df}{dt}&=g_1:=\Big(p(s_p(t))+q(s_q(t))(1-e^{-y})\Big)\left(1-f\right),  &f(0)=0,\qquad\qquad\qquad\\
				\frac{dy}{dt}&=g_2:=p(s_p(t)),  &y(0)=0.\qquad\qquad\qquad
			\end{align*}
			Finally, $\pi=\big(\gamma\frac{df}{dt}-s_p-s_q\big)e^{-\theta t}$. Applying Theorem~\ref{thm:pontryagin} gives
			\begin{equation}
				\label{eq:ham_circle}
				H=\pi+\Psi_1g_1+\Psi_2g_2=(\gamma e^{-\theta t} +\Psi_1) (1-f) \left(p(s_p)+q(s_q)(1-e^{-y})\right)+p(s_p)\Psi_2-\left(s_p+s_q\right)e^{-\theta t},
			\end{equation}
			which gives~\eqref{eq:H_line}. Equations~\eqref{eq:bvp_pq_circle} for $\frac{d\Psi_1}{dt}$ and $\frac{d\Psi_2}{dt}$ follow from
			$
			\frac{d\Psi_1}{dt}=-\frac{\partial H}{\partial f}$ and $ \frac{d\Psi_2}{dt}=-\frac{\partial H}{\partial y}.
			$

			\section{Proof of Corollary~\ref{cor:opt_circle_pq}}
			Substituting~\eqref{eq:p_q_s}, the Hamiltonian~\eqref{eq:ham_circle} becomes
			\begin{align*}
