			\section{Proof of Corollary~\ref{cor:s_infty_circle}}
			\label{app:cor:s_infty_circle}
			We begin with an auxilliary lemma:
			\begin{lemma}
				\label{lem:lambda_1d}
				The solution of~\eqref{eq:bvp_pq_circle} satisfies for $0\leq t\leq T$
				\begin{equation}
					\label{eq:psi_2_bound}
					-\gamma e^{-\theta t}\leq \Psi_1(t)\leq 0, \qquad
					\max \Bigl\{0, \Big(\frac{2}{b_p}\sqrt{s_p(t)}-(1-f)\gamma\Big)e^{-\theta t}\Bigr\}\leq \Psi_2(t)\leq \frac{2}{b_p}\sqrt{s_p(t)}e^{-\theta t}.
				\end{equation}
			\end{lemma}
			\begin{proof}
				Since $s_p(t),s_q(t)\geq 0$, then $y(t)\geq 0$, and so
				\begin{equation*}
					p_0+b_p\sqrt{s_p(t)}+\Big(q_0+b_q\sqrt{s_q(t)}\Big)(1-e^{-y})\geq p_0>0, \qquad 0\leq t\leq T.
				\end{equation*}
				Therefore, by~\eqref{eq:bvp_pq_circle}, the sign of $\frac{d\Psi_1}{dt}$ is determined by the sign of $A(t):=\gamma e^{-\theta t}+\Psi_1$. Let $0\leq t_1<T$.
				\begin{itemize}
					\item[{\bf Case 1:}]
					If $\Psi_1(t_1)>0$, then in order to have $\Psi_1(T)=0$, see~\eqref{eq:bvp_pq_circle}, there must exist $t_2\in (t_1,T)$ such that $\Psi_1(t_2)>0$ and $\frac{d\Psi_1}{dt}(t_2)<0$. Now, $\Psi_1(t_2)>0$ impliles that $A(t_2)>0$, and hence that $\frac{d\Psi_1}{dt}(t_2)>0$. Contradiction.
					\item[{\bf Case 2:}]
					If $\Psi_1(t_1)<-\gamma e^{-\theta t_1}$, then $A(t_1)<0$. Since $A(T)=\gamma e^{-\theta T}>0$, there must exist $t_2\in (t_1,T)$ such that $A(t_2)=0$ and $A'(t_2)>0$. Now,
					$
					A'(t)=-\gamma\theta e^{-\theta t}+\frac{d\Psi_1}{dt}.
					$
					Since $A(t_2)=0$, then $\frac{d\Psi_1}{dt}(t_2)=0$, see~\eqref{eq:bvp_pq_circle}. Hence, $A'(t_2)=-\gamma\theta e^{-\theta t_2}<0$. Contradiction.
					%	If $\Psi_1(t_1)<-\gamma e^{-\theta t_1}$, then $A(t_1)<0$, and so $\Psi_1'(t_1)<0$. In order for $\Psi_1(T)=0$, there must exist $t_1<t_2<T$ such that $\Psi_1'(t_2)>0$, or equivalently $A(t_2)>0$. In particular, since $A(t)$ is continuous, there must exist $t_3\in (t_1,t_2)$ which is the first time after $t_1$ in which $A(t_3)=0$. However, $A'(t)=-\gamma\theta e^{-\theta t}+\Psi_1'(t)$, so if $\Psi_1'(t)<0$, or equivalently $A(t)<0$, then $A'(t)<0$. Since $A(t)<0$ for $t_1\leq t<t_3$, then $A'(t)<0$ for $t_1\leq t<t_3$. Therefore, $A(t_3)<A(t_1)$, which contradicts $A(t_3)=0$.
				\end{itemize}
				Therefore, we proved that
				$$
				-\gamma e^{-\theta t}\leq\Psi_1(t)\leq 0, \qquad A(t)\geq 0 \qquad 0\leq t<T.
				$$
				Since
				$
				(1-f)\left(q_0+b_q\sqrt{s_q(t)}\right)e^{-y}>0
				$
				and $A(t)\geq 0$, then by~\eqref{eq:bvp_pq_circle}, $\frac{d\Psi_2}{dt}(t)\leq 0$ for $0\leq t<T$. Hence, since $\Psi_2(T)=0$, $\Psi_2(t)\geq 0$ for $0\leq t<T$. Furthermore, by~\eqref{eq:s_lambda_pq_circle},
				\begin{equation}
					\label{eq:lambda_2_circle}
					\Psi_2(t)=\Big(\frac{2}{b_p}\sqrt{s_p(t)}-(1-f)(\gamma+\Psi_1e^{\theta t})\Big)e^{-\theta t}.
				\end{equation}
				The upper and lower bounds for $\Psi_2$ are attained by substituting  $-\gamma e^{-\theta t}\leq\Psi_1 \leq 0$ in~\eqref{eq:lambda_2_circle}.
			\end{proof}

			\begin{proof}[Proof of Corollary~\ref{cor:s_infty_circle}]
				Let $T<\infty$. Since $\Psi_1(t), \Psi_2(t)$ and $f^{\rm opt}(t)$ are continuous, $s_p^{\rm opt}(t)$ and $s_q^{\rm opt}(t)$ are bounded in $[0,T]$, see~\eqref{eq:s_lambda_pq_circle}. Therefore, by~\eqref{eq:bvp_pq_circle},
				$
				\frac{df^{\rm opt}}{dt}\leq (1-f^{\rm opt})K,
				$
				where $K$ is a positive constant. Hence, $f^{\rm opt}(T)<1$. Therefore, by~\eqref{eq:s_lambda_pq_circle}, $s_p^{\rm opt}(T), s_q^{\rm opt}(T)>0$.

				Let $T=\infty$. By Lemma~\ref{lem:lambda_1d} and~\eqref{eq:s_lambda_pq_circle},
				$$
				s_p(t)\leq \frac{b_p^2}{4}\left(\gamma(1-f)+\Psi_2e^{\theta t}\right)^2,\qquad
				s_q(t)\leq \frac{b_q^2}{4}\Big(\gamma(1-f)(1-e^{-y})\Big)^2.
				$$

				Since $\lim\limits_{t\to\infty}f(t)=1$, then $\lim\limits_{t\to\infty}s_q(t)=0$.
				To show that $\lim\limits_{t\to\infty}s_p(t)=0$, we need to show that $\lim\limits_{t\to\infty}\Psi_2 e^{\theta t}=0$. Indeed, by L'Hospital's rule, and using~$\lim\limits_{t\to\infty}s_q^{\rm opt}(t)=0$,~\eqref{eq:bvp_pq_circle} and~\eqref{eq:psi_2_bound},
				\begin{align*}
					0\leq \lim\limits_{t\to\infty}\frac{\Psi_2(t)}{e^{-\theta t}}&=\lim\limits_{t\to\infty}\frac{(\gamma e^{-\theta t}+\Psi_1)(1-f)\left(q+b_q\sqrt{s_q(t)}\right)e^{-y}}{\theta e^{-\theta t}}\\&
					\leq \lim\limits_{t\to\infty}\frac{\gamma e^{-\theta t}(1-f)\left(q+b_q\sqrt{s_q(t)}\right)e^{-y}}{\theta e^{-\theta t}}=0.
				\end{align*}
			\end{proof}

			\section{Optimal strategies on infinite heterogeneous complete networks}
			\label{app:het}

			The reduction of the aggregate dynamics to two ordinary differential equations, see~\eqref{eq:groups_limit}, enables us to formulate the optimal promotion as a boundary-value problem with four equations:
			\begin{theorem}
				\label{thm:opt_group_same}
				Consider the Bass model~{\rm (\ref{eqs:Bass-model},~\ref{eq:het_conditions})} on a heterogeneous complete network with two homogeneous groups of equal size in which the effect of promotions is given by~\eqref{eq:p_q_s_het}. Then 
				\begin{subequations}
					\label{eqs:pq_opt_groups}
					\begin{equation}
						\label{eq:s_lambda_pq_groups}
						\begin{aligned}
							s_p^{\rm opt}(t)&=\frac{1}{4}\Big(\sum_{k=1}^{2}b_{p^k}\big(\frac{1}{2}-f_k\big)\big(\gamma +\Psi_ke^{\theta t}\big)\Big)^2, \quad
							%\\
							s_q^{\rm opt}(t)=\frac{1}{4}\Big(\big(f_1+f_2\big)\sum_{k=1}^{2}b_{q^k}\big(\frac{1}{2}-f_k\big)\big(\gamma +\Psi_ke^{\theta t}\big)\Big)^2,
						\end{aligned}
					\end{equation}
					where $f_1^{\rm opt}, f_2^{\rm opt}, \Psi_1^{\rm opt},$ and $\Psi_2^{\rm opt}$ are the solutions of the boundary-value problem 
					\begin{equation}
						\label{eq:bvp_pq_groups}
						\begin{aligned}
							\frac{df_k}{dt}&=\Big(\frac{1}{2}-f_k\Big)R_k,\qquad &&f_k(0)=0, \qquad k=1,2,
							\\
							\frac{d\Psi_1}{dt}
							&=(\gamma e^{-\theta t}+\Psi_1) \Big(R_1-\Big(\frac{1}{2}-f_1\Big)\Big(q_0^1+b_{q^1}\sqrt{s_q^{\rm opt}}\Big)\Big)\\&\qquad\qquad\qquad-\left(\gamma e^{-\theta t}+\Psi_2\right)\Big(\frac{1}{2}-f_2\Big)\Big(q_0^2+b_{q^2}\sqrt{s_q^{\rm opt}}\Big), \qquad &&\Psi_1(T)=0,
							\\
							\frac{d\Psi_2}{dt}
							&=(\gamma e^{-\theta t}+\Psi_2) \Big(R_2-\Big(\frac{1}{2}-f_2\Big)\Big(q_0^2+b_{q^2}\sqrt{s_q^{\rm opt}}\Big)\Big)
							\\&\qquad\qquad\qquad-\Big(\gamma e^{-\theta t}+\Psi_1\Big)\Big(\frac{1}{2}-f_1\Big)\Big(q_0^1+b_{q^1}\sqrt{s_q^{\rm opt}}\Big),\qquad &&\Psi_2(T)=0,
						\end{aligned}
					\end{equation}
					and 
					\begin{equation}
						\label{eq:R_values}
						R_k:=p_0^k+b_{p^k}\sqrt{s_p^{\rm opt}}+\Big(q_0^k+b_{q^k}\sqrt{s_q^{\rm opt}}\Big)(f_1+f_2), \qquad k=1,2.
					\end{equation}
				\end{subequations}
			\end{theorem}
			\begin{proof}
				By Theorem~\ref{thm:pontryagin}, any solution of~\eqref{eq:profit} must satisfy $\frac{\partial H}{\partial s_p}=\frac{\partial H}{\partial s_q}=0$, where
				\begin{subequations}
					\label{eqs:ham_pq_same}
					\begin{equation}
						\label{eq:ham_pq_same}
						H(t)=\Big(\gamma \Big(\frac{df_1}{dt}+\frac{df_2}{dt}\Big)-s_p-s_q\Big)e^{-\theta t}+\Psi_1\frac{df_1}{dt}+\Psi_2\frac{df_2}{dt},
					\end{equation}
					and
					\begin{equation}
						\label{eq:lambda_pq_same}
						\frac{d\Psi_k}{dt}=-\frac{\partial H}{\partial f_k}, \qquad \Psi_k(T)=0, \qquad k=1,2.
					\end{equation}
				\end{subequations}
				Substituting~\eqref{eq:p_q_s_het}~and~\eqref{eq:groups_limit}~in~\eqref{eqs:ham_pq_same} yields
				\begin{subequations}
					\label{eqs:H_lambda_pq_same}
					\begin{equation*}
						\begin{aligned}
							H
							&=(\gamma e^{-\theta t} +\Psi_1) \Big(\frac{1}{2}-f_1\Big)\left(p_0^1+b_{p_1}\sqrt{s_p}+\left(q_0^1+b_{q_1}\sqrt{s_q}\right)(f_1+f_2)\right)\\ &\qquad+(\gamma e^{-\theta t} +\Psi_2) \Big(\frac{1}{2}-f_2\Big)\left(p_0^2+b_{p_2}\sqrt{s_p}+\left(q_0^2+b_{q_2}\sqrt{s_q}\right)(f_1+f_2)\right)-\left(s_p+s_q\right)e^{-\theta t},
						\end{aligned}		
					\end{equation*}
					and
					\begin{equation*}
						\label{eq:lambda_prime_pq_same}
						\begin{aligned}
							\frac{d\Psi_1}{dt}
							&=\left(\gamma e^{-\theta t}+\Psi_1\right)\left(p_0^1+b_{p_1}\sqrt{s_p}+\left(q_0^1+b_{q_1}\sqrt{s_q}\right)\left(2f_1+f_2-\frac{1}{2}\right)\right)\\ &\qquad\qquad-\left(\gamma e^{-\theta t}+\Psi_2\right)\left(q_0^2+b_{q_2}\sqrt{s_q}\right)\Big(\frac{1}{2}-f_2\Big), \qquad &\Psi_1(T)=0, \\
							\frac{d\Psi_2}{dt}
							&=\left(\gamma e^{-\theta t}+\Psi_2\right)\left(p_2+b_{p_2}\sqrt{s_p}+\left(q_2+b_{q_2}\sqrt{s_q}\right)\left(2f_2+f_1-\frac{1}{2}\right)\right)\\ &\qquad\qquad-\left(\gamma e^{-\theta t}+\Psi_1\right)\left(q_0^1+b_{q_1}\sqrt{s_q}\right)\Big(\frac{1}{2}-f_1\Big), \qquad &\Psi_2(T)=0.
						\end{aligned}
					\end{equation*}

				\end{subequations}
				Since $\frac{\partial H}{\partial s_p}=\frac{\partial H}{\partial s_q}=0$, we have
				\begin{align*}
					\label{eq:neccesary_pq_same}
					0&=\frac{b_{p_1}\Big(\frac{1}{2}-f_1\Big)\left(\gamma e^{-\theta t}+\Psi_1(t)\right)+b_{p_2}\Big(\frac{1}{2}-f_2\Big)\left(\gamma e^{-\theta t}+\Psi_2(t)\right)}{2\sqrt{s_p(t)}}-e^{-\theta t},\\
					0&=(f_1+f_2)\frac{b_{q_1}\Big(\frac{1}{2}-f_1\Big)\left(\gamma e^{-\theta t}+\Psi_1(t)\right)+b_{q_2}\Big(\frac{1}{2}-f_2\Big)\left(\gamma e^{-\theta t}+\Psi_2(t)\right)}{2\sqrt{s_q(t)}}-e^{-\theta t}.
				\end{align*}
				These equations lead to~\eqref{eq:s_lambda_pq_groups}.
			\end{proof}

			\begin{figure}[ht!]
				\centering
				%\scalebox{0.71}{\includegraphics{opt_groups.eps}}
				\scalebox{0.65}{\includegraphics{opt_groups_alt_mag.eps}}
				\caption{Same as Figure~\ref{fig:pq_opt_M2}, on a heterogeneous network with two homogeneous groups where $p_0^1=0.01$, $p_0^2=0.02$, $q_0^1=0.1$, $q_0^2=0.2$, $b_{p^1}=0.01$, $b_{p^2}=0.02$, $b_{q^1}=0.1$, and $b_{q^2}=0.2$. Here, $\Delta\Pi^{\rm opt}\approx 6.2\%$.}
				\label{fig:pq_opt_groups}
			\end{figure}

			In Figure~\ref{fig:pq_opt_groups} we plot the optimal promotion when the first group has the same parameters as in Figure~\ref{fig:pq_opt}, and all the parameters of the second group are doubled. As always, $s_p^{\rm opt}(t)$ decreases, whereas $s_q^{\rm opt}(t)$ increases from zero to a global maximum and then decreases. The relative sizes of $s_p^{\rm opt}(t)$ and $s_q^{\rm opt}(t)$ are similar to those in the homogeneous case, i.e., $s_p^{\rm opt}(t)$ is initially dominant, but as more individuals adopt, $s_q^{\rm opt}(t)$ becomes dominant. Hence, in this case, the heterogeneity of the network does not qualitatively affect the optimal promotion. 

			When we apply a heterogeneous promotion, see~\eqref{eq:p_q_s_diff}, we arrive at
			\begin{theorem}
				\label{thm:opt_group_diff}
				Consider the Bass model~{\rm (\ref{eqs:Bass-model},~\ref{eq:het_conditions})} on a heterogeneous complete network with two homogeneous groups of equal size in which the effect of promotions is given by~\eqref{eq:p_q_s}. Then
				\begin{subequations}
					\label{eqs:pq_opt_groups_diff}
					\begin{equation}
						\label{eq:s_lambda_pq_groups_diff}
						\begin{aligned}
							s_{p^k}^{\rm opt}(t)&=\Big(b_{p^k}\left(\frac{1}{2}-f_k\right)\Big(\gamma +\Psi_ke^{\theta t}\Big)\Big)^2, \qquad&k=1,2,
							\\
							s_{q^k}^{\rm opt}(t)&=\Big((f_1+f_2)b_{q^k}\Big(\frac{1}{2}-f_k\Big)\Big(\gamma +\Psi_k e^{\theta t}\Big)\Big)^2,\qquad &k=1,2,
						\end{aligned}
					\end{equation}
					where $f_1^{\rm opt}, f_2^{\rm opt}, \Psi_1^{\rm opt},$ and $\Psi_2^{\rm opt}$ are the solutions of the boundary-value problem 
					\begin{equation}
						\label{eq:bvp_pq_groups_diff}
						\begin{aligned}
							\frac{df_k}{dt}&=\Big(\frac{1}{2}-f_k\Big)R_k,\qquad &&f_k(0)=0,\quad k=1,2,\\
							\frac{d\Psi_1}{dt}
							&=(\gamma e^{-\theta t}+\Psi_1) \Big(R_1-\Big(\frac{1}{2}-f_1\Big)\left(q_0^1+b_{q^1}\sqrt{s_{q^1}^{\rm opt}}\right)\Big)\\&\qquad\qquad\qquad-\left(\gamma e^{-\theta t}+\Psi_2\right)\Big(\frac{1}{2}-f_2\Big)\left(q_0^2+b_{q^2}\sqrt{s_{q^2}^{\rm opt}}\right), \qquad &&\Psi_1(T)=0,
							\\
							\frac{d\Psi_2}{dt}
							&=(\gamma e^{-\theta t}+\Psi_2) \Big(R_2-\Big(\frac{1}{2}-f_2\Big)\Big(q_0^2+b_{q^2}\sqrt{s_{q^2}^{\rm opt}}\Big)\Big)\\&\qquad\qquad\qquad -\left(\gamma e^{-\theta t}+\Psi_1\right)\Big(\frac{1}{2}-f_1\Big)\Big(q_0^1+b_{q^1}\sqrt{s_{q^1}^{\rm opt}}\Big),\qquad &&\Psi_2(T)=0,
						\end{aligned}
					\end{equation}
					and 
					\begin{equation}
						\label{eq:R_values_diff}
						R_k:=p_0^k+b_{p^k}\sqrt{s_{p^k}^{\rm opt}}+\left(q_0^k+b_{q^k}\sqrt{s_{q^k}^{\rm opt}}\right)(f_1+f_2), \qquad k=1,2.
					\end{equation}
				\end{subequations}
			\end{theorem}
			\begin{proof}
				By Theorem~\ref{thm:pontryagin}, any solution of~\eqref{eq:profit} must satisfy $\frac{\partial H}{\partial s_p}=\frac{\partial H}{\partial s_q}=0$, where
				\begin{subequations}
					\label{eqs:ham_pq_diff}
					\begin{equation}
						\label{eq:ham_pq_diff}
						H=\Big(\gamma \Big(\frac{df_1}{dt}+\frac{df_2}{dt}\Big)-\frac{1}{2}(s_{p_1}+s_{p_2}+s_{q_1}+s_{q_2})\Big)e^{-\theta t}+\Psi_1\frac{df_1}{dt}+\Psi_2\frac{df_2}{dt},
					\end{equation}
					and
					\begin{equation}
						\label{eq:lambda_pq_diff}
						\frac{d\Psi_k}{dt}=-\frac{\partial H}{\partial f_k}, \qquad \Psi_k(T)=0, \qquad k=1,2.
					\end{equation}
				\end{subequations}
				Substituting~\eqref{eq:groups_limit} with~\eqref{eq:p_q_s_diff} in~\eqref{eqs:ham_pq_same} yields
				\begin{subequations}
					\label{eqs:H_lambda_pq_diff}
					\begin{equation*}
						\begin{aligned}
							H(t)
							&=(\gamma e^{-\theta t} +\Psi_1) (\frac{1}{2}-f_1)\Big(p_0^1+b_{p_1}\sqrt{s_{p_1}(t)}+\Big(q_0^1+b_{q_1}\sqrt{s_{q_1}(t)}\Big)(f_1+f_2)\Big)\\ &\qquad+(\gamma e^{-\theta t} +\Psi_2) (\frac{1}{2}-f_2)\Big(p_0^2+b_{p_2}\sqrt{s_{p_2}(t)}+\Big(q_0^2+b_{q_2}\sqrt{s_{q_2}(t)}\Big)(f_1+f_2)\Big)\\ &\qquad-\frac{1}{2}\left(s_{p_1}(t)+s_{p_2}(t)+s_{q_1}(t)+s_{q_2}(t)\right)e^{-\theta t},
						\end{aligned}		
					\end{equation*}
					and
					\begin{equation*}
						\label{eq:lambda_prime_pq_diff}
						\begin{aligned}
							\frac{d\Psi_1}{dt}
							&=\Big(\gamma e^{-\theta t}+\Psi_1(t)\Big)\Big(p_0^1+b_{p_1}\sqrt{s_{p_1}(t)}+\Big(q_0^1+b_{q_1}\sqrt{s_{q_1}(t)}\Big)\Big(2f_1+f_2-\frac{1}{2}\Big)\Big)\\ &\qquad\qquad-\Big(\gamma e^{-\theta t}+\Psi_2(t)\Big)\Big(q_0^2+b_{q_2}\sqrt{s_{q_2}(t)}\Big)\Big(\frac{1}{2}-f_2\Big), \qquad &\Psi_1(T)=0, \\
							\frac{d\Psi_2}{dt}
							&=\Big(\gamma e^{-\theta t}+\Psi_2(t)\Big)\Big(p_0^2+b_{p_2}\sqrt{s_{p_2}(t)}+\Big(q_0^2+b_{q_2}\sqrt{s_{q_2}(t)}\Big)\Big(2f_2+f_1-\frac{1}{2}\Big)\Big)\\ &\qquad\qquad-\left(\gamma e^{-\theta t}+\Psi_1(t)\right)\Big(q_0^1+b_{q_1}\sqrt{s_{q_1}(t)}\Big)\Big(\frac{1}{2}-f_1\Big), \qquad &\Psi_2(T)=0.
						\end{aligned}
					\end{equation*}

				\end{subequations}
				Since $\frac{\partial H}{\partial s_{p_1}}=\frac{\partial H}{\partial s_{p_2}}=\frac{\partial H}{\partial s_{q_1}}=\frac{\partial H}{\partial s_{q_2}}=0$, we have for $k=1,2$,
				\begin{equation*}
					\label{eq:neccesary_pq_diff}
					0=\frac{b_{p_1}\left(\frac{1}{2}-f_k\right)\left(\gamma e^{-\theta t}+\Psi_k(t)\right)}{2\sqrt{s_{p_k}(t)}}-\frac{1}{2}e^{-\theta t},\qquad
					0=(f_1+f_2)\frac{b_{q_k}\left(\frac{1}{2}-f_k\right)\left(\gamma e^{-\theta t}+\Psi_k(t)\right)}{2\sqrt{s_{q_k}(t)}}-\frac{1}{2}e^{-\theta t}.
				\end{equation*}
				These equations lead to~\eqref{eq:s_lambda_pq_groups}.
			\end{proof}

