			\section{Proof of Theorem~\ref{thm:non_uniform}}
			\label{app:thm:non_uniform}
			Consider the case where $p_1=p_2$, $q_1=q_2$, $b_{p_1}=b_{p_2}$, and $b_{q_1}=b_{q_2}$. Applying Theorem~\ref{thm:opt_group_diff} yields that $s_{p_1}^{\rm opt}(t)=s_{p_2}^{\rm opt}(t)=s_p^{\rm opt}(t)$ and $s_{q_1}^{\rm opt}(t)=s_{q_2}^{\rm opt}(t)=s_q^{\rm opt}(t)$ where $s_p^{\rm opt}(t)$ and $s_q^{\rm opt}(t)$ are the solutions to~\eqref{eq:s_lambda_pq}. Hence, on a homogeneous network, it is optimal to apply a uniform campaign.

			\section{Numerical Methods}
			\label{app:numerical}
			In this paper, we solve boundary-value problems of the form
			\begin{subequations}
				\label{eqs:bvp_gen}
				\begin{align}
					\label{eq:f_gen}
					\frac{d{\bf f}}{dt}&={\bf g}\Big(t,{\bf f}(t),{\bf s}\big(t,{\bf f}(t),\boldsymbol{\Psi}(t)\big)\Big), &&{\bf f}(0)={\bf f}_0,\\
					\label{eq:lambda_gen}
					\frac{d\boldsymbol{\Psi}}{dt}&={\bf h}\Big(t,{\bf f}(t),{\bf s}\big(t,{\bf f}(t),\boldsymbol{\Psi}(t)\big),\boldsymbol{\Psi}(t)\Big), &&\boldsymbol{\Psi}(T)=0,
				\end{align}
			\end{subequations}
			%\begin{subequations}
			%	\label{eqs:bvp_gen}
			%	\begin{align}
				%		\label{eq:f_gen}
				%		\frac{d{\bf f}}{dt}&={\bf g}(t,{\bf f}(t),{\bf s}(t)), \qquad {\bf f}(0)={\bf f}_0,\\
				%		\label{eq:lambda_gen}
				%		\frac{d\boldsymbol{\Psi}}{dt}&={\bf h}(t,{\bf f}(t),{\bf s}(t),\boldsymbol{\Psi}(t)), \qquad \boldsymbol{\Psi}(T)=0,\\
				%		\label{eq:s_gen}
				%		{\bf s}(t)&= \Phi(t,{\bf f}(t),\boldsymbol{\Psi}(t)),
				%	\end{align}
			%\end{subequations}
			where ${\bf f}, \boldsymbol{\Psi}\in \mathbb{R}\to\mathbb{R}^d$. This is a system of $2d$ nonlinear ODEs with $d$ boundary conditions for ${\bf f}$ at $t=0$ and $d$ boundary conditions for $\boldsymbol{\Psi}$ at $t=T$. We use two numerical methods to solve~\eqref{eqs:bvp_gen}.

			%\subsection*{Forward-backward sweeps}
			In the {\bf forward-backward sweeps method}, we freeze the value of $\boldsymbol{\Psi}(t)$ while solving~\eqref{eq:f_gen} from left to right, i.e., for increasing values of $t$, and then freeze the value of ${\bf f}(t)$ while solving~\eqref{eq:lambda_gen} from right to left. The algorithm proceeds as follows:
			\begin{enumerate}
				\item 
				Set $\boldsymbol{\Psi}^{(0)}(t)\equiv 0$.
				\item 
				Solve the initial-value problem~\eqref{eq:f_gen} in $0\leq t\leq T$ for ${\bf f}^{(n)}(t)$ using $\boldsymbol{\Psi}(t)=\boldsymbol{\Psi}^{(n-1)}(t)$.
				\item 
				Solve the intial-value problem~\eqref{eq:lambda_gen} in $T\geq t\geq 0$ for $\boldsymbol{\Psi}^{(n)}(t)$ using ${\bf f}(t)={\bf f}^{(n)}(t)$ .
				\item 
				Repeat steps 2-3 until $\|{\bf f}^{(n)}-{\bf f}^{(n-1)}\|_{\infty}<\text{TOL}$
			\end{enumerate}


			\noindent In the {\bf shooting method}, we proceed as follows:
			\begin{enumerate}
				\item 
				Guess an initial value $\boldsymbol{\Psi}_0$.
				\item 
				Solve~\eqref{eqs:bvp_gen} for $0\leq t\leq T$ as an initial value problem with $\boldsymbol{\Psi}(0)=\boldsymbol{\Psi}_0$.
				\item 
				Use a root-finding method to search for $\boldsymbol{\Psi}_0$ for which $\boldsymbol{\Psi}(T)=0$.
			\end{enumerate}

			In most cases, see e.g.,~\eqref{eq:bvp_pq}, the ODE for $\Psi_i(t)$ is of the form
			\begin{equation}
				\label{eq:lambda_some}
				\frac{d\Psi_i}{dt}=\Big(\gamma e^{-\theta t}+\Psi_i\Big)\big(A+B(t)\big),
			\end{equation}
			where $A>0$ and $B(t)\to 0$ as $t\to\infty$. If $T=\infty$, the numerical solution for $\Psi(t)$ will grow exponentially as $t\to\infty$, while the analytical solution should decay to $0$. To see this, we first prove
			\begin{lemma}
				\label{lem:lambda_asymptotic}
				Let $\Psi_i$ be the solution of~\eqref{eq:lambda_some}. Then 
				$
				\Psi_i(t)\sim c_2 e^{-\theta t}$ as $ t\to\infty$, where $c_2:= -\frac{\gamma A}{\theta+A}$.
			\end{lemma}
			\begin{proof}
				Since $\lim\limits_{t\to\infty}B=0$, then
				\begin{equation}
					\label{eq:lam_sol1}
					\frac{d\Psi_i}{dt}\sim \Big(\gamma e^{-\theta t}+\Psi_i\Big)A, \qquad t\to\infty.
				\end{equation}
				Solving this ODE gives
				\begin{equation}
					\label{eq:lam_sol}
					\frac{d\Psi_i}{dt}\sim c_1 e^{A t}+c_2 e^{-\theta t}.
				\end{equation}
				Since $\lim\limits_{t\to\infty}\Psi_i=0$, then $c_1=0$, and so $\Psi_i\sim c_2 e^{-\theta t}$.
				Substituting this back into~\eqref{eq:lam_sol1} gives~$c_2$.
			\end{proof}

			Equation~\eqref{eq:lam_sol} explains the spurious exponential growth of the numerical solution. Analytically, $c_1=0$, but numerically we only have that $c_1 \approx 0$, and so $c_1 e^{A_i t}$ grows exponentially for $t\gg 1$. To avoid this, we modify the shooting method as follows:
			\begin{enumerate}
				\item 
				Find the first time $t^*$ at which $1-f^0(t):=f(t;{\bf s}(t)\equiv 0)$ is smaller than a certain tolerance. If no such time exists, let $t^*=T$.
				\item 
				Solve the boundary-value problem for  $0\leq t\leq t^*$ using the shooting method, with the terminal boundary condition being
				$\Psi_i(t^*)=c_2 e^{-\theta t^*}$.
				\item
				Solve the boundary-value problem for $t^*\leq t<\infty$ while replacing $\Psi_i(t)$ with $c_2 e^{-\theta t}$. 
				\item
				Use the numerical solution of the boundary-value problem to compute ${\bf s}(t)$.
			\end{enumerate}

			Although the previous analysis was for $T=\infty$, the spurious exponential growth of the numerical solution also occurs for $T\gg 1$, so we use the same method.

