\begin{algorithm}[h]
\caption{Sequential DDQN}
\label{alg:sddqn}

Initialize Q-network $Q_\phi$

Initialize target network $Q_{\phi'} \gets Q_\phi$

Initialize replay buffer $\mathcal{D}$

\For{\( \text{episode} = 1 \) \KwTo \( N \)}{
    Reset environment and observe the initial state $s_0$

    \For{$t = 1$ \KwTo \text{total number of SFC requests}}{
            \textbf{// Sequential Action Selection}

            $a_t \gets \{\}$

            $a_{\text{prev}} \gets \text{None}$

            \For{each VNF $v$ in the SFC}{
                $s_v \gets [s_v; a_{\text{prev}}]$

                $a_v \gets \arg\max_{a} Q_{\phi}(s_v, a)$ with $\epsilon$-greedy

                $a_t \gets a_t \cup \{a_v\}$

                $a_{\text{prev}} \gets a_v$
                }
            \textbf{// Environment Interaction}

            Run action $a_t$, get reward $r_t$ and next state $s_{t+1}$

            \textbf{// Transition Storing}

                \For{each VNF $v$ in $s_t$}{
                    Store transition $(s_v, a_v, r_t, s_{t+1})$ in $\mathcal{D}$
                }
            % Store transition $(s_t, a_t, r_t, s_{t+1})$ in replay buffer $\mathcal{D}$
            \textbf{// Q-network Update}

            Sample $M$ mini-batch transitions $(s, a, r, s')$

            from $\mathcal{D}$ and compute target Q-value:

            $q \gets \{\}$\\
            $a_{\text{prev}} \gets \text{None}$\\
                \For{each VNF $v$ in $s'$}{
                    $s_v \gets [s_v; a_{\text{prev}}]$\\
                    $a_v \gets \arg\max_{a} Q_{\phi}(s_v, a)$\\
                    $q_v \gets Q_{\phi'}(s_v, a_v)$\\
                    $q \gets q \cup \{q_v\}$\\
                    $a_{\text{prev}} \gets a_v$
                }
            % $y = r + \gamma Q_{\phi'}(s', \arg\max Q_{\phi'}(s', a'))$
            \[y \gets r + \gamma \cdot \text{mean}(q)\]\\
            Update critic by minimizing the loss:
            \[\mathcal{L}_{\text{critic}} = \frac{1}{M} \sum (Q_\phi(s, a) - y)^2\]\\
            \textbf{// Target Network Update}\\
            Update target networks:
            \[\phi' \gets \tau \phi + (1 - \tau) \phi'\]
    }
}
\Return \( Q_{\phi} \)
\end{algorithm}


\begin{algorithm}[h]
\caption{Parallel DDQN}
\label{alg:pddqn}

Initialize Q-network $Q_\phi$\\
Initialize target network $Q_{\phi'} \gets Q_\phi$\\
Initialize replay buffer $\mathcal{D}$

\For{\( \text{episode} = 1 \) \KwTo \( N \)}{
    Reset environment and observe the initial state $s_0$\\
    \For{$t = 1$ \KwTo \text{total number of SFC requests}}{
            \textbf{// Parallel Action Selection}\\
            $a_t \gets \arg\max_{a} Q_{\phi}(s_t, a)$ with $\epsilon$-greedy\\
            \textbf{// Environment Interaction}\\
            Run action $a_t$, get reward $r_t$ and next state $s_{t+1}$\\
            \textbf{// Transition Storing}\\
                \For{each VNF $v$ in $s_t$}{
                    Store transition $(s_v, a_v, r_t, s_{t+1})$ in $\mathcal{D}$
                }
            % Store transition $(s_t, a_t, r_t, s_{t+1})$ in replay buffer $\mathcal{D}$
            \textbf{// Q-network Update}\\
            Sample $M$ mini-batch transitions $(s, a, r, s')$\\ from $\mathcal{D}$
            and compute target Q-value:\\
            $q \gets \{\}$\\
                \For{each VNF $v$ in $s'$}{
                    $a_v \gets \arg\max_{a} Q_{\phi}(s_v, a)$\\
                    $q_v \gets Q_{\phi'}(s_v, a_v)$\\
                    $q \gets q \cup \{q_v\}$
                }
            % $y = r + \gamma Q_{\phi'}(s', \arg\max Q_{\phi'}(s', a'))$
            \[y \gets r + \gamma \cdot \text{mean}(q)\]

            Update critic by minimizing the loss:
            \[\mathcal{L}_{\text{critic}} = \frac{1}{M} \sum (Q_\phi(s, a) - y)^2\]

            \textbf{// Target Network Update}

            Update target networks:
            \[\phi' \gets \tau \phi + (1 - \tau) \phi'\]
    }
}
\Return \( Q_{\phi} \)
\end{algorithm}

