\paragraph{The $\eps$--Path Metric}
For any $Y\subset\mathbb{R}^d$, the notion of an $\eps$--path was formally introduced in \cite{Majhi2023} as a family of piecewise paths in $\mathbb{R}^d$. 
The family gives rise to an alternative metric on $Y$---different from the Euclidean metric restricted to $Y$.

A (non-empty) subset $Y\subset\R^d$ comes equipped with the standard Euclidean metric, given by the Euclidean norm $\norm{\ \cdot\ }$. 
We define another metric, denoted $d^\eps_Y$, using the pairwise Euclidean distances of points in $Y$. 
For a positive number $\eps$, we first introduce the notion of an $\eps$--path.
\begin{definition}[$\eps$--Path]\label{def:eps-path}
Let $Y\subset\R^d$ be non-empty and $\eps>0$ a number. 
For $a,b\in Y$, an \emph{$\eps$--path} of $Y$ from $a$ to $b$ is a finite sequence $P=\{y_i\}_{i=0}^{k+1}\subseteq Y$ such that $y_0=a$, $y_{k+1}=b$, and $\norm{y_i-y_{i+1}}\le\eps$ for all $i=0,1,\ldots,k$. 
\end{definition}
We now define the length of the path by
\begin{equation*}\label{eq:length_of_path}
L(P)\coloneqq\sum_{i=0}^k\norm{y_i-y_{i+1}}.    
\end{equation*}
We denote the set of all $\eps$--paths of $Y$ by $\mathscr{P}_Y^\eps$.
%\note{WT: The following proposition uses $d_x^{(2+\xi)\eps}$ before defining the $d^\eps$ metric on the following page..? Consider moving definition up before proposition -- otherwise explain what $d_x^{(2+\xi)\eps}$ is?}
We finally introduce the $\eps$--path metric on $Y$.
\begin{definition}[$d^\eps_Y$--Metric]\label{def:d-eps} Let $Y\subset\R^d$ be non-empty and $\eps>0$ a number. The $\eps$--path metric on $Y$, denoted $d^\eps_Y$, between any $a,b\in Y$ is defined by
\begin{equation*}\label{eq:d^eps}
d^\eps_Y(a,b)\coloneqq\inf\left\{L(P)\mid P\in \mathscr{P}^\eps_Y\text{ is an $\eps$--path of $Y$ joining $a,b$}\right\}.
\end{equation*}
\end{definition}

\begin{theorem}[Topological Reconstruction]\label{thm:topo-recon}
Let $G\subset\R^d$ be a connected, compact embedded graph.
Let $S\subset\R^d$ be a compact subset such that $d_H(S,G)<\eps$. 
Let $r \in \mathcal{R}_\eps(S)$, $\alpha  > 0$, and $\mathcal{I}$ be a finite covering of the segment $[0, Diam(\mathcal{R}_\eps(S))]$ by open intervals of length at most $\alpha$ such that the $\alpha$-Reeb graph $G_{\alpha}$ associated to $\mathcal{I}$ and the function $d = d_S (r, .) :\mathcal{R}_\eps(S))\to \mathbb{R}$ is a finite graph. Then, the Reeb graph is homotopy equivalent to $G$.
\end{theorem}

