\subsection{Usage Scenarios and Templates}
\label{sec:artifacts:scenarios}

\newcommand{\mytask}[1]{\textsf{#1}}


\begin{wrapfigure}[12]{r}{0.3\linewidth}%
%\begin{figure}[b]
