 We next translate the norm difference bound into a statement about the overlap (fraction of correctly identified labels). This connection allows us to interpret the effects of the privacy mechanism directly in terms of the clustering accuracy.



\begin{lemma}[Overlap Rate for Graph Perturbation Mechanism]
\label{lem:lower_bound_overlap}
Consider the graph perturbation mechanism, which satisfies $\epsilon$-edge DP. 
Define the overlap rate between the ground truth labels $\bm{\sigma}^{*}$ and the estimated labels $\hat{\bm{\sigma}}(G)$ obtained via the private spectral method as
\begin{align*} %\label{eqn:overlap_rate}
\operatorname{overlap\ rate}\bigl(\hat{\bm{\sigma}}(G), \bm{\sigma}^{*}\bigr)
\;\triangleq\;
1 \;-\;
\operatorname{err\ rate}\bigl(\hat{\bm{\sigma}}(G), \bm{\sigma}^{*}\bigr).
\end{align*}
Under the conditions of Theorem~\ref{theorem:distance_bound}, we have
\begin{align*}
\operatorname{overlap\ rate}\bigl(\hat{\bm{\sigma}}(G), \bm{\sigma}^{*}\bigr)
\;\ge\;
1 \;-\; \frac{C_{\ref{theorem:distance_bound}}(\epsilon, \eta)}{8}
\end{align*}
with probability at least \(1 - 3 \eta\), where \(C_{\ref{theorem:distance_bound}}(\epsilon, \eta)\) is determined by the right hand side of the inequality of Theorem~\ref{theorem:distance_bound}.
\end{lemma}


 \subsection{Subsampling Stability-Based Mechanism}

 The key idea in this algorithm is to create $m$ \textit{correlated} subgraphs $\{G_{1},G_{2},\ldots,G_{m}\}$ of the original graph ${G}$ where each subgraph $G_{\ell}$ is generated by randomly subsampling with replacement of the edges in ${G}$ with probability $q_{s}$. We then apply our \textit{non-private} spectral method $\hat{\bm{\sigma}}(G_{\ell})$  on each subgraph $G_{\ell}$. 
 The labeling vectors $\hat{\bm{\sigma}}(G_{\ell})$ are then represented on a histogram. {{Now, define $\text{count}{(\bm{\sigma})} \triangleq | \{ k \in[m]: \hat{\bm{\sigma}}(G_{k}) =  \bm{\sigma}\} | $.}} As shown in \cite{dwork2014algorithmic}, the stability of the histogram is proportional to the difference between the most frequent bin (i.e., the mode) and the second most frequent bin.  In other words, the most frequent outcome of the histogram agrees with the outcome of the original graph with high probability under an appropriate choice of the SBM parameters $(p,q)$, the privacy budget $(\epsilon, \delta)$, the edge sampling probability $q_{s}$, and the number of subsampled weighted graphs $m$. For further details on the mechanism and stability of community detection algorithms over SBMs, please refer to our previous work in \cite{seif2024differentially}. We summarize the mechanism in Algorithm \ref{algo:vanilla_subsampling_stability}.


\begin{algorithm}[t]
  \caption{Subsampling Stability Mechanism}
  \label{algo:vanilla_subsampling_stability}
  \begin{algorithmic}[1]
     \STATE \textbf{Input:} Graph \( G = (\mathcal{V}, E) \), privacy budget \( \epsilon, \delta \), graph structure properties.
     \STATE \textbf{Output:} Private labelling vector \( \hat{\bm{\sigma}} \).
     \STATE Compute the base sampling probability \( q_s \leftarrow \min (1, \epsilon / (32 \log(n)) )\).
     \STATE Compute \( m \leftarrow \lceil \log(n/\delta) / q_s^2 \rceil \).
     \STATE Subsample \( m \) subgraphs \( \{G_1, G_2, \ldots, G_m\} \) using \( q_s \).
     \STATE Compute the label vectors \( \bar{\bm{\sigma}} = (\hat{\bm{\sigma}}(G_1), \ldots, \hat{\bm{\sigma}}(G_m)) \).
     \STATE Aggregate the label vectors via majority voting and compute the stability score:
     \[
     \hat{d} \leftarrow \frac{\text{count}_{(1)} - \text{count}_{(2)}}{4m q_s} - 1.
     \]
     \STATE Add Laplace noise to ensure privacy:
     \[
     \tilde{d} \leftarrow \hat{d} + \operatorname{Lap}(0, 1/\epsilon).
     \]
     \IF{\( \tilde{d} > \log(1/\delta)/\epsilon \)}
     \STATE Output \( \hat{\bm{\sigma}}_{\text{final}} = \text{mode}(\bar{\bm{\sigma}}) \).
     \ELSE
     \STATE Output \( \perp \) (a random label vector).
     \ENDIF
  \end{algorithmic}
\end{algorithm}



\subsubsection{Auxiliary Result for the Subsampling Stability Mechanism}

The proof of the main theorem for the Subsampling Stability Mechanism is based on the same perturbation analysis as the analysis of the graph perturbation mechanism presented in the previous subsection. For this analysis, we will need the following concentration bound for the Laplacian matrix released by the subsampling stability mechanism.

\begin{lemma}[Concentration of Subsampled Laplacian Matrices]
Consider an undirected graph with \( n \) nodes and edge set \( E \), represented by the Laplacian matrix \( \mathbf{L} \). Let \( \hat{\mathbf{L}} \) be the Laplacian matrix of a subsampled graph, obtained by independently including each edge \( (i, j) \in E \) with probability 
\[
q_{s,ij} = q_s \cdot (1 - r(i,j)),
\]
where \( q_s \) is a base sampling probability, \( r(i,j) \in [0, 1] \) is a removal probability determined by the edge-specific subsampling mechanism. The following concentration bound holds for a universal constant \( C_{\ref{lemma:concentration_subsampling_laplacian_matrices_subsampling}} \):
\[
\|\hat{\mathbf{L}} - \mathbf{L}\| 
\;\leq\; 
C_{\ref{lemma:concentration_subsampling_laplacian_matrices_subsampling}} 
\sqrt{( \sum_{i < j} q_{s,ij} (1 - q_{s,ij}) ) \cdot \log(n / \eta)},
\]
with probability at least \( 1 - \eta \).
\label{lemma:concentration_subsampling_laplacian_matrices_subsampling}
\end{lemma}


\subsubsection{Main Result for the Subsampling Stability Mechanism}


 \begin{theorem}[Distance to Ground Truth Labels]
 \label{theorem:distance_bound_stability}
 Let $\mathbf{u}_{2}$ and $\hat{\mathbf{u}}_{2}$ be the second eigenvectors of the unperturbed Laplacian matrix $\mathbf{L}$ and the Laplacian matrix $\hat{\mathbf{L}}$ of the subsampled graph $G_{\ell}$ obtained via the subsampling mechanism, respectively. Then, with probability at least $1 - 3 \eta$, we have
\begin{equation}
\begin{aligned}
& \min_{s \in \{\pm 1\}} \| \hat{\mathbf{u}}_2 - s \mathbf{u}_2 \|_2 \nonumber \\ 
&\leq 
  \frac{4 \sqrt{2}}{n(p-q)} \cdot \bigg( \|\mathbf{d}\|_2 + \sqrt{2 \sigma^2 \log \left({2}/{\eta}\right)} \\ 
& \quad \quad \quad \quad \quad \quad \quad \quad \quad + \frac{L}{3} \log \left({2}/{\eta}\right) \bigg)
\triangleq  C_{\ref{theorem:distance_bound_stability}}(\epsilon, \eta),
\end{aligned}
\end{equation}
where, \( \mathbf{d} \) is a deterministic part of the perturbation, derived from the adjusted edge sampling mechanism where \( \|\mathbf{d}\|_2 = \frac{2q_s}{\sqrt{n}} \sqrt{\frac{q}{p+q} \cdot |E|} \), \( |E| \) represents the total number of edges in the graph, and \( \sigma^2 = \frac{16}{n} \cdot q_s (1 - q_s) |E_{\text{inter}}| \), where \( |E_{\text{inter}}| \) denotes the number of inter-community edges. This is the variance of the edge sampling noise, with \( q_{s} \) which can be further upper bounded as \( \sigma^2 \leq \frac{4}{n} \cdot \frac{q}{p+q} \cdot |E| \), and \( L = \max_{(i,j) \in E} \|\mathbf{x}_{ij}\|_2 \leq {4}/{\sqrt{n}} \) is the upper bound on the norm of the noise components.
\begin{proof}
The proof is based on the same perturbation analysis as the analysis of the graph perturbation mechanism given in the proof of Thm.~\ref{theorem:distance_bound}, with the bound of Lemma~\ref{lemma:concentration_subsampling_laplacian_matrices_subsampling} used instead for the high-probability bound for the term $\|\hat{\mathbf{L}} - \mathbf{L}\|$.
\end{proof}
\end{theorem}


The above result holds under the following separation condition between $p$ and $q$. Specifically, for a universal constant $C = 4 \cdot \max\left(2 C_{\ref{lemma:concentration_laplacian_matrices}}, \, C_{\ref{lemma:concentration_subsampling_laplacian_matrices_subsampling}} \right)$, with $C_{\ref{lemma:concentration_laplacian_matrices}}$ and $C_{\ref{lemma:concentration_subsampling_laplacian_matrices_subsampling}}$ given in Lemmas~\ref{lemma:concentration_laplacian_matrices} and~\ref{lemma:concentration_subsampling_laplacian_matrices_subsampling}, respectively, it is required that
\begin{align*}
& n (p - q)  \;\geq\; C  \Bigl[\mathcal{T}
\;+\; \frac{n}{\sqrt{2}} \sqrt{q_{s} (1-q_{s}) } \sqrt{\log(n/\eta)}\Bigr],
\end{align*}
where $\mathcal{T} \triangleq \sqrt{n p \,\log(n/\eta)} \;+\; \log \left({n}/{\eta}\right)$.


\begin{remark}[Impact of \( q_s \) on the Distance Bound]
The  edge sampling probability \( q_s \) plays a crucial role in the trade-off between privacy and spectral accuracy. As \( q_s \) decreases:
\begin{itemize}
    \item The deterministic perturbation \( \|\mathbf{d}\|_2 \) and the variance \( \sigma^2 \) decrease, reflecting reduced magnitudes of the subsampling-induced noise.
    \item However, the spectral gap \( \hat{\lambda}_3 - \lambda_2 \) (refer to Eqn. \eqref{eqn:spectral_grap}) also decreases significantly due to the increased instability of the subsampled graph, particularly when critical edges are removed.
\end{itemize}
Here, \( \hat{\lambda}_3 \) is the third smallest eigenvalue of the subsampled graph \( G_\ell \). This reduction in the spectral gap dominates the bound, leading to an overall increase in the upper bound on the distance \( \| \hat{\mathbf{u}}_2 - s \mathbf{u}_2 \|_2 \). 
\end{remark}






\begin{lemma}[Overlap Rate for  Subsampling Stability Mechanism]
\label{lem:lower_bound_overlap_subsampling_stability}
Consider the  subsampling stability-based mechanism, which satisfies $(2 \epsilon, \delta)$-edge DP. The overlap rate between the ground truth labels \( \bm{\sigma}^{*} \) and the final estimated labels \( \hat{\bm{\sigma}}_{\text{final}} \) obtained via majority voting on \( m \) correlated subgraphs \( \{G_1, \ldots, G_m\} \) satisfies:
\[
\operatorname{overlap\,rate} (\hat{\bm{\sigma}}_{\text{final}}, \bm{\sigma}^{*}) 
\geq 1 - \frac{C_{\ref{theorem:distance_bound_stability}}(\epsilon, \eta)}{4} - O\left(\frac{1}{\sqrt{m}}\right),
\]
with probability at least \( 1 - 3 m \eta \), where \( C_{\ref{theorem:distance_bound_stability}}(\epsilon, \eta) \) is the error contribution from the non-private spectral method for individual subsampled Graph \( G_{\ell} \).
\end{lemma}



\textit{Proof Sketch.} For a single subsampled graph \( G_\ell \), the labeling \( \hat{\bm{\sigma}}(G_\ell) \) satisfies: \( \operatorname{overlap\,rate} (\hat{\bm{\sigma}}(G_\ell), \bm{\sigma}^{*}) \geq 1 - C_{\ref{theorem:distance_bound_stability}} \), implying that at most \( C_{\ref{theorem:distance_bound_stability}} n \) nodes are mislabeled in each subgraph. Let \( S_\ell \subseteq [n] \) denote the set of mislabeled nodes for subgraph \( G_\ell \), so \( |S_\ell| \leq C_{\ref{theorem:distance_bound_stability}} n \). The final labeling \( \hat{\bm{\sigma}}_{\text{final}} \) is obtained by taking a majority vote over the \( m \) subgraphs. A node \( i \) is mislabeled in \( \hat{\bm{\sigma}}_{\text{final}} \) if it is mislabeled in more than \( m/2 \) subgraphs.

Let \( X_i \) denote the number of subgraphs in which node \( i \) is mislabeled. Since \( \mathbb{E}[X_i] = m C_{\ref{theorem:distance_bound_stability}
} \), the probability that \( X_i \geq m/2 \) can be bounded using Hoeffding's inequality:
\[
\operatorname{Pr}(X_i \geq {m}/{2}) \leq \exp\left( {-2 \left(\frac{m}{2} - m C_{\ref{theorem:distance_bound_stability}}\right)^2}/{m}\right).
\]

Aggregating the probability of mislabeling across all nodes, the fraction of mislabeled nodes (denoted as $\mathcal{M}$) in the final labeling satisfies that  $\frac{|\mathcal{M}|}{n} \leq 2C_{\ref{theorem:distance_bound_stability}} + O\left({1}/{\sqrt{m}}\right)$,
where \( 2C_{\ref{theorem:distance_bound_stability}} \) accounts for the worst-case overlap between mislabeled nodes across subgraphs.




