  \centering
  \caption{Weights for Probabilities}
    \begin{tabular}{ccccc}
    \multicolumn{1}{l}{weight} & \multicolumn{1}{l}{probability} & \multicolumn{1}{l}{3 voters} & \multicolumn{1}{l}{5 voters} & \multicolumn{1}{l}{7 voters} \\
