% {\footnotesize
% \begin{align}
% \boldsymbol{\alpha}_{t,\mathcal{H}} &= 
% \left[1, \ldots, e^{-j \frac{2\pi \Delta_x^{\mathrm{RIS}}}{\lambda} (N_x - 1) \sin(\phi_{t,\mathcal{H}})\cos(\vartheta_{t,\mathcal{H}})} \right]^T \nonumber \\
% &\otimes \left[1, \ldots, e^{-j \frac{2\pi \Delta_y^{\mathrm{RIS}}}{\lambda} (N_y - 1) \sin(\phi_{t,\mathcal{H}})\sin(\vartheta_{t,\mathcal{H}})} \right]^T.
% \end{align}}
% ********************************
\subsection{Channel Model}
% ********************************
We adopt an air-to-ground (ATG) channel model for the BS–RIS link \cite{alhourani-2014-optimal,yu-2023-aerial}, and a Rician fading model for the RIS–$U_k$ link \cite{peng-2023}. The BS-to-RIS channel matrix \( \mathbf{G} \in \mathbb{C}^{N \times M} \) comprises both LoS and non-line-of-sight (NLoS) components, modeled as

% ********************************
\vspace{-0.05in}
{\footnotesize
\begin{align}
\mathbf{G} = \sqrt{\beta_\mathcal{G}} \left( 
\sqrt{P_{\mathrm{LoS}}} \mathbf{H}_{\mathcal{G}}^{\mathrm{LoS}}  
+ \sqrt{1 - P_{\mathrm{LoS}}} \mathbf{H}_{\mathcal{G}}^{\mathrm{NLoS}} \right),
\label{eq_G}
\end{align}}where \( \beta_\mathcal{G} = \beta_0 / d_\mathcal{G}^2 \) denotes large-scale path loss, with \( \beta_0 \) as the reference path loss and \( d_\mathcal{G} = \| \mathbf{q}_{\mathrm{RIS}} - \mathbf{q}_{\mathrm{BS}} \| \). The deterministic LoS component is given by \( \mathbf{H}_{\mathcal{G}}^{\mathrm{LoS}} = e^{-j \frac{2\pi d_\mathcal{G}}{\lambda}} \boldsymbol{\alpha}_{r,\mathcal{G}} \boldsymbol{\alpha}_{t,\mathcal{G}}^H \), where the exponential term accounts for the propagation delay. The NLoS term \( \mathbf{H}_{\mathcal{G}}^{\mathrm{NLoS}} \in \mathbb{C}^{N \times M} \) follows i.i.d. Rayleigh fading with entries \( \mathcal{CN}(0,1) \) \cite{al2014modeling}.

Based on the ATG model in \cite{alhourani-2014-optimal}, the LoS probability is given by

% ********************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
P_{\mathrm{LoS}} = \frac{1}{1 + a \exp\left(-b(\phi_{t,\mathcal{G}} - a)\right)},
\end{equation}}where the elevation angle $\phi_{t,\mathcal{G}} = \frac{180}{\pi} \sin^{-1} \left( \frac{H_{\mathrm{RIS}} - H_{\mathrm{BS}}}{d_\mathcal{G}} \right)$, while \( a \) and \( b \) are environment-dependent empirical constants \cite{wang-2024-age}.

For the RIS-to-$U_k$ link, the large-scale path loss is \( \beta_{\mathcal{H},k} = \beta_0 / d_{\mathcal{H},k} \), with \( d_{\mathcal{H},k} = \| \mathbf{q}_{\mathrm{RIS}} - \mathbf{q}_{\mathrm{U}_k} \| \). Thus, the small-scale fading is modeled as

% ********************************
\vspace{-0.05in}
{\footnotesize
\begin{align}
\mathbf{g}_{\mathcal{H},k} = \sqrt{\beta_{\mathcal{H},k}} \left( 
\sqrt{\frac{K_\mathcal{H}}{1 + K_\mathcal{H}}} \mathbf{h}_{\mathcal{H},k}^{\mathrm{LoS}} + 
\sqrt{\frac{1}{1 + K_\mathcal{H}}} \mathbf{h}_{\mathcal{H},k}^{\mathrm{NLoS}} 
\right),
\label{eq_g}
\end{align}
}where \( K_\mathcal{H} \) is the Rician factor. The LoS component is \( \mathbf{h}_{\mathcal{H},k}^{\mathrm{LoS}} = e^{-j \frac{2\pi d_{\mathcal{H},k}}{\lambda}} \boldsymbol{\alpha}_{t,\mathcal{H}} \in \mathbb{C}^{N \times 1} \), and the NLoS component \( \mathbf{h}_{\mathcal{H},k}^{\mathrm{NLoS}} \in \mathbb{C}^{N \times 1} \) is Rayleigh fading with i.i.d. \( \mathcal{CN}(0,1) \) entries.
% *****************************************
\subsection{Time-Switching Energy Harvesting Model}
% *****************************************
We adopt a TS protocol to manage the trade-off between EH and information reflection in the UAV-mounted RIS system. Each time slot \( t \) is divided into two non-overlapping phases: an EH phase of duration \( \tau(t) \) and a transmission phase of duration \( 1 - \tau(t) \), where \( \tau(t) \in [0,1] \) is the TS factor. The BS transmits a composite signal \( \mathbf{S}(t) = \sum_{k \in \mathcal{K}} \mathbf{V}_k \mathcal{C}_k \), where \( \mathbf{V}_k \in \mathbb{C}^{M \times 1} \) is the beamforming vector for user \( k \), and \( \mathcal{C}_k \sim \mathcal{CN}(0,1) \) is the data symbol. The total BS transmit power satisfies \( \mathbb{E}[\mathbf{S}^H \mathbf{S}] = \sum_{k \in \mathcal{K}} \|\mathbf{V}_k\|^2 \).

During the EH phase, all RIS elements harvest power from the BS-transmitted signal. The ideal received RF power at the RIS is given by

% *********************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
P^{\text{RF}}(t) = \tau(t) \sum_{i=1}^{N_x} \sum_{j=1}^{N_y} \left\| \mathbf{g}_{i,j}^H \mathbf{S}(t) \right\|^2,
\end{equation}
}where \( \mathbf{g}_{i,j} \in \mathbb{C}^{M \times 1} \) is the channel vector from the BS to RIS element \( (i, j) \), extracted from the BS-to-RIS channel matrix \( \mathbf{G} \in \mathbb{C}^{N \times M} \). To account for circuit nonlinearity, the actual harvested power follows a nonlinear model \cite{sharma-2022,Semiha2023}

% ******************************
{\footnotesize
% \vspace{-0.05in}
\begin{equation}
\varepsilon^{\text{RF-NL}}(t) = \frac{\Omega(t) - P_{\text{sat}} \Delta}{1 - \Delta},
\label{eq:EH_model}
\end{equation}
}where {\footnotesize \( \Omega(t) = P_{\text{sat}} / (1 + \exp(-c(P^{\text{RF}}(t) - d))) \)} and {\footnotesize \( \Delta = 1 / (1 + \exp(cd)) \)}. Here, \( P_{\text{sat}} \) denotes the saturation power, and \( c \), \( d \) are nonlinearity parameters subject to harvester hardware design \cite{salim-2024}.

% ******************************
\subsection{Transmission and Received Signal Model}
% ******************************
In the transmission phase, RIS elements reflect the incoming signal, where the received signal at user \( k \) is

% ******************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
y_k = \mathbf{g}_{\mathcal{H},k}^H \boldsymbol{\Theta} \mathbf{G} \mathbf{S}(t) + n_k,
\end{equation}
}where \( \boldsymbol{\Theta} = \operatorname{diag}(e^{j\theta_1}, \dots, e^{j\theta_N}) \) is the RIS phase-shift matrix, and \( n_k \sim \mathcal{CN}(0, \sigma_k^2) \) is the additive white Gaussian noise. Assuming ideal interference cancellation \cite{peng-2023}, the SNR at user \( k \) is

% ******************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
\Gamma_k(t) = \frac{\left| \mathbf{g}_{\mathcal{H},k}^H \boldsymbol{\Theta} \mathbf{G} \mathbf{V}_k \right|^2}{\sum\limits_{\substack{u \in \mathcal{K} \\ u \neq k}} \left| \mathbf{g}_{\mathcal{H},k}^H \boldsymbol{\Theta} \mathbf{G} \mathbf{V}_u \right|^2 + \sigma_k^2},
\end{equation}
}
% *****************************

Therefore, the achievable rate (bps/Hz) for user \( k \) in slot \( t \) is

% ************************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
R_k(t) = (1 - \tau(t)) B \log_2 \left(1 + \Gamma_k(t) \right), \quad k \in \mathcal{K},\ t \in \mathcal{T}.
\end{equation}
}
% ************************************

Hence, the overall EH efficiency at the UAV-mounted RIS is defined as

% ************************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
\varepsilon\varepsilon(t) = \frac{\varepsilon^{\text{RF-NL}}(t)}{\varepsilon^{\text{r}}_{\text{UAV-RIS}}(t)},
\end{equation}
}where {\footnotesize \( \varepsilon^{\text{r}}_{\text{UAV-RIS}}(t) = \sum\limits_{i=1}^{N_x} \sum\limits_{j=1}^{N_y} \left\| \mathbf{g}_{i,j}^H \mathbf{S}(t) \right\|^2 \)} denotes the total received RF power at the RIS. This formulation captures the conversion efficiency under practical nonlinear EH dynamics.

% ************************************
\subsection{UAV-mounted RIS Jitter Modeling}
% ************************************
In practical deployments, the UAV-mounted RIS may undergo random angular jitter due to wind, vibrations, or mechanical instabilities, causing orientation deviations \cite{wang-2024-aerial}. These misalignments alter the signal incidence angles at the RIS, degrading EH efficiency and beamforming performance. Hence, accurately modeling jitter is essential to optimize the EH–reflection trade-off. We assume the RIS lies on the horizontal \( xy \)-plane. Under jitter, the RIS plane rotates to a new orientation \( \tilde{x} \tilde{y} \). While the BS remains static, the AoAs and AoDs at the RIS vary with the UAV’s angular displacement. Jitter is modeled as small-angle deviations \( \delta_x, \delta_y, \delta_z \sim \mathcal{N}(0, \sigma_j^2) \) around the roll, pitch, and yaw axes \cite{yu-2023-aerial}. These induce a composite 3D rotation matrix {\footnotesize $\mathbf{R}_j = \mathbf{R}_{\text{yaw}}(\delta_z)\, \mathbf{R}_{\text{pitch}}(\delta_y)\, \mathbf{R}_{\text{roll}}(\delta_x)$}, where

% ********************************
% ************************************
\vspace{-0.05in}
{\footnotesize
\begin{align}
\mathbf{R}_{\text{yaw}}(\delta_z) &= 
\begin{bmatrix}
\cos\delta_z & -\sin\delta_z & 0 \\
\sin\delta_z & \cos\delta_z  & 0 \\
0            & 0             & 1
\end{bmatrix}, \\
\mathbf{R}_{\text{pitch}}(\delta_y) &= 
\begin{bmatrix}
\cos\delta_y  & 0 & \sin\delta_y \\
0             & 1 & 0 \\
-\sin\delta_y & 0 & \cos\delta_y
\end{bmatrix}, \\
\mathbf{R}_{\text{roll}}(\delta_x) &= 
\begin{bmatrix}
1 & 0           & 0 \\
0 & \cos\delta_x & -\sin\delta_x \\
0 & \sin\delta_x & \cos\delta_x
\end{bmatrix}.
\end{align}
}
% ********************************

Accordingly, the effective geometric vectors from the BS to the RIS and from the RIS to user \( k \), under jitter, become

% ************************************
\vspace{-0.05in}
{\footnotesize
\begin{align}
\widetilde{\mathbf{v}}_{\mathcal{G}} &= \mathbf{R}_j (\mathbf{q}_{\mathrm{RIS}} - \mathbf{q}_{\mathrm{BS}}), \\
\widetilde{\mathbf{v}}_{\mathcal{H},k} &= \mathbf{R}_j (\mathbf{q}_{\mathrm{U},k} - \mathbf{q}_{\mathrm{RIS}}).
\end{align}
}

The resulting AoAs and AoDs at RIS are recalculated as
% ***********************

% ************************************
\vspace{-0.05in}
{\footnotesize
\begin{align}
\widetilde{\vartheta}_{r,\mathcal{G}} &= \arccos \left( \frac{ \langle \widetilde{\mathbf{v}}_{\mathcal{G}}, \mathbf{e}_z \rangle }{ \| \widetilde{\mathbf{v}}_{\mathcal{G}} \| \, \| \mathbf{e}_z \| } \right), \\
\widetilde{\varphi}_{r,\mathcal{G}} &= \arccos \left( \frac{ \langle \mathcal{P}_{xy}(\widetilde{\mathbf{v}}_{\mathcal{G}}), \mathbf{e}_x \rangle }{ \| \mathcal{P}_{xy}(\widetilde{\mathbf{v}}_{\mathcal{G}}) \| \, \| \mathbf{e}_x \| } \right), \\
\widetilde{\vartheta}_{t,\mathcal{H}} &= \arccos \left( \frac{ \langle \widetilde{\mathbf{v}}_{\mathcal{H},k}, -\mathbf{e}_z \rangle }{ \| \widetilde{\mathbf{v}}_{\mathcal{H},k} \| \, \| \mathbf{e}_z \| } \right), \\
\widetilde{\varphi}_{t,\mathcal{H}} &= \arccos \left( \frac{ \langle \mathcal{P}_{xy}(\widetilde{\mathbf{v}}_{\mathcal{H},k}), \mathbf{e}_x \rangle }{ \| \mathcal{P}_{xy}(\widetilde{\mathbf{v}}_{\mathcal{H},k}) \| \, \| \mathbf{e}_x \| } \right),
\end{align}
}where \( \mathbf{e}_x \) and \( \mathbf{e}_z \) are unit vectors along the \( x \)- and \( z \)-axes, \( \mathcal{P}_{xy}(\cdot) \) denotes the orthogonal projection onto the \( xy \)-plane, and \( \langle \cdot, \cdot \rangle \) is the Euclidean inner product. These perturbed angles are then used to update the channel components in \eqref{eq_G} and \eqref{eq_g}, thereby incorporating the impact of UAV jitter.


\section{Problem Formulation} \label{Sec_PF}

Based on the system model in Section~\ref{Sec_SM}, we aim to maximize the EH efficiency of the UAV-mounted RIS system over a finite horizon of \( T \) time slots as \( \mathbb{T} = \{1, 2, \dots, T\} \), while ensuring minimum QoS for all users. This is achieved by jointly optimizing the BS power allocation, the RIS phase shifts, and the TS factor at each slot \( t \). The resulting optimization problem is formulated as

\vspace{-0.05in}
{\footnotesize
\begin{IEEEeqnarray}{cl}
\IEEEyesnumber\label{eq:MOF_TS} \IEEEyessubnumber*
\max_{\tau(t), \mathbf{P}_U, \bm{\Theta}} & \sum_{t=1}^{T} \varepsilon\varepsilon(t) \\
\text{s.t.} \quad & R_k(t) \geq R_{\min},\quad \forall k \in \mathbb{K},\ t \in \mathbb{T}, \label{eq:MOF_TS_rate}\\
& 0 \leq \tau(t) \leq 1,\quad \forall t \in \mathbb{T}, \\
& 0 \leq P_{BS}(t) \leq P_{BS}^{\max},\quad \forall t \in \mathbb{T}, \\
& 0 \leq p_k(t) \leq P_U^{\max},\quad \forall k \in \mathbb{K},\ t \in \mathbb{T}, \\
& \theta_n(t) \in [0, 2\pi],\quad \forall n \in [1, N],\ t \in \mathbb{T}, \\
& |e^{j\theta_n(t)}| = 1,\quad \forall n \in [1, N],\ t \in \mathbb{T}\label{eq:MOF_TS_Unit},
\end{IEEEeqnarray}
}where $\tau(t)$ is the TS factor, \( \mathbf{P}_U = [p_1(t), \dots, p_K(t)] \) and \( \bm{\Theta} = [\theta_1(t), \dots, \theta_N(t)] \) represent the user-specific BS power allocations and RIS phase shifts, respectively. Constraints \eqref{eq:MOF_TS_rate}–\eqref{eq:MOF_TS_Unit} guarantee user QoS, feasible TS allocation, BS and user power limits, valid phase shift bounds for RIS elements, and the unit-modulus property required for passive reflection, respectively.


\section{Proposed SSD3-Based Optimization Framework} \label{Sec_Proposed_Algorithm}

The optimization problem in \eqref{eq:MOF_TS} is non-convex and time-coupled, involving continuous control variables under nonlinear constraints. In particular, the TS ratio, RIS phase shifts, and user-specific BS power allocations are interdependent and evolve over channels affected by UAV jitter and nonlinear EH dynamics. Conventional methods, such as convex relaxation or alternating optimization, are not well suited for real-time adaptation. To address this, we develop a DRL framework based on the DDPG algorithm.
% **********************************
\subsection{MDP Formulation}
% **********************************
We model the system as a MDP defined by the tuple \( \langle \mathcal{S}, \mathcal{A}, P_t, R, \gamma \rangle \), where \( \mathcal{S} \) and \( \mathcal{A} \) denote the state and action spaces, \( P_t \) is the transition probability, \( R \) is the reward function, and \( \gamma \in [0,1) \) is the discount factor. The state at time slot \( t \) is

% **********************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
s^t = \big[ \Re\{\mathbf{G}\}, \Im\{\mathbf{G}\}, \Re\{\mathbf{g}_{\mathcal{H},k}\}, \Im\{\mathbf{g}_{\mathcal{H},k}\}, \mathcal{P}^{\mathrm{RIS}}_{i,j} , \mathcal{P}_k, a^{t-1} \big],
\end{equation}}where \( \mathcal{P}^{\mathrm{RIS}}_{i,j} \) denotes the coordinates of the \( (i,j) \)-th RIS element, \( \mathcal{P}_k \) is the user location, and \( a^{t-1} \) is the previous action. The action vector is \( a^t = [\tau(t), p_k(t), \theta_n(t)] \), consisting of the TS ratio, BS power allocation, and RIS phase shifts. The reward \( r^t \) is set to the EH efficiency \( \varepsilon\varepsilon(t) \) if users' QoS constraints are satisfied; otherwise, it is zero.

In DDPG, an actor network maps states to actions, and a critic evaluates Q-values. The actor is trained using the deterministic policy gradient

% **********************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
    \nabla_{\vartheta^{\mu}} J \approx \frac{1}{N_b} \sum_i \nabla_a Q(s, a | \vartheta^Q) |_{a=\mu(s_i)} \nabla_{\vartheta^{\mu}} \mu(s_i),
\end{equation}
}where \( N_b \) is the mini-batch size, and $\vartheta^{\mu}$ and $\vartheta^{Q}$ are the parameters of the actor and critic networks, respectively. The critic minimizes the loss

% **********************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
L(\vartheta^Q) = \frac{1}{N_b} \sum_i (y_i - Q(s_i, a_i | \vartheta^Q))^2,
\end{equation}
}with target value \( y_i = r_i + \gamma Q'(s_{i+1}, \mu'(s_{i+1})) \). Here, \( Q' \) and \( \mu' \) denote the target critic and actor networks, respectively. Soft target updates are applied as 

% **********************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
\vartheta^{\mu'} \leftarrow \rho \vartheta^{\mu} + (1 - \rho) \vartheta^{\mu'}, \quad
\vartheta^{Q'} \leftarrow \rho \vartheta^Q + (1 - \rho) \vartheta^{Q'}.
\end{equation}
}
% **********************************

Exploration during training is encouraged by adding Gaussian noise to the actor’s output as \( a = \mu(s) + \xi \), with \( \xi \sim \mathcal{N}(0, \sigma^2) \).
% **********************************
\subsection{Smoothed Softmax Dual DDPG (SSD3) Algorithm}
% **********************************
While DDPG is effective for continuous control, it tends to overestimate Q-values due to a single critic. TD3 mitigates this by using two critics and computing the target value as

% **********************************
\vspace{-0.05in}
{\footnotesize
\begin{equation}
    y_i = r_i + \gamma \min\{ Q'_1(s_{i+1}, \mu'(s_{i+1})), Q'_2(s_{i+1}, \mu'(s_{i+1})) \},
\end{equation}
}with delayed actor updates. However, this conservative approach can lead to underestimation and slower convergence.

To address this, we propose the SSD3 algorithm detailed in Algorithm \ref{alg:SSD3}, which extends TD3 by employing two independent actors and using a softmax-weighted critic fusion instead of the conservative minimum. SSD3 further introduces entropy regularization in the actor update to enhance exploration and stability under the nonconvex and stochastic dynamics of UAV-RIS systems. Specifically, SSD3 maintains two actor–critic pairs \((\mu_1, Q_1)\) and \((\mu_2, Q_2)\). For target estimation, clipped Gaussian noise \( \epsilon \sim \mathcal{N}(0, \sigma^2) \) is added to the target action, forming \( a'^i = \mu'(s') + \text{clip}(\epsilon, -c, c) \). The softmax-weighted target is computed as:

\vspace{-0.05in}
{\footnotesize
\begin{equation}
T_{\mathrm{SSD3}}(s') = \frac{\sum_i \exp(\beta Q_{\min}^i) Q_{\min}^i}{\sum_i \exp(\beta Q_{\min}^i)},
\end{equation}
}where \( Q_{\min}^i = \min\{ Q_1'(s', a'^i), Q_2'(s', a'^i) \} \), and \( \beta \) controls the softmax temperature. To reduce bias, SSD3 dynamically selects the actor corresponding to the higher Q-value at each training step

\vspace{-0.05in}
{\footnotesize
\begin{equation}
\mu_{\text{chosen}} = 
\begin{cases}
\mu_1, & \text{if } Q_1(s, \mu_1(s)) \geq Q_2(s, \mu_2(s)), \\
\mu_2, & \text{otherwise},
\end{cases}
\end{equation}
}
and updates it using an entropy-regularized loss function

\vspace{-0.05in}
{\footnotesize
\begin{equation}
\mathcal{L}_{\mu_{\text{chosen}}} = -\mathbb{E}_{s \sim \mathcal{D}} \left[ Q_{\max}(s, \mu_{\text{chosen}}(s)) \right] 
+ \lambda_{\mathrm{ent}} \cdot \mathbb{E}_{s} \left[ \|\mu_{\text{chosen}}(s)\|_2^2 \right],
\end{equation}
}where \( Q_{\max}(s, a) = \max\{ Q_1(s, a), Q_2(s, a) \} \), and \( \lambda_{\mathrm{ent}} \) controls the strength of entropy-based regularization.
