% T_{\mathrm{SSD3}}(s') = \frac{\sum_i \exp(\beta Q_{\min}^i) Q_{\min}^i}{\sum_i \exp(\beta Q_{\min}^i)},
% \end{equation}
% }where \( Q_{\min}^i = \min\{ Q_1'(s', a'^i), Q_2'(s', a'^i) \} \), and the smoothed target action is given by \( a'^i = \mu'(s') + \text{clip}(\epsilon, -c, c) \), with \( \epsilon \sim \mathcal{N}(0, \sigma^2) \).

% To avoid bias and premature convergence, SSD3 selects the actor associated with the higher critic value:

% \vspace{-0.05in}
% {\footnotesize
% \begin{equation}
% \mu_{\text{chosen}} = 
% \begin{cases}
% \mu_1, & \text{if } Q_1(s, \mu_1(s)) \geq Q_2(s, \mu_2(s)), \\
% \mu_2, & \text{otherwise}.
% \end{cases}
% \end{equation}
% }

% The selected actor is trained using an **entropy-regularized deterministic loss**:

% \vspace{-0.05in}
% {\footnotesize
% \begin{equation}
% \mathcal{L}_{\mu_{\text{chosen}}} = -\mathbb{E}_{s \sim \mathcal{D}} \left[ Q_{\max}(s, \mu_{\text{chosen}}(s)) \right] 
% + \lambda_{\mathrm{ent}} \cdot \mathbb{E}_{s} \left[ \|\mu_{\text{chosen}}(s)\|_2^2 \right],
% \end{equation}
% }where \( Q_{\max} \) is the maximum of the two critics and \( \lambda_{\mathrm{ent}} \) controls the regularization strength.

% These enhancements collectively improve sample efficiency, learning stability, and adaptability in complex wireless environments with UAV jitter and non-linear energy harvesting behavior.

% **********************************
\begin{algorithm}[!t]
\caption{SSD3-Based UAV-RIS Optimization Algorithm}
\label{alg:SSD3}
\begin{algorithmic}[1]
\scriptsize
\STATE \textbf{Initialize:} dual actor-critic networks and their target networks
\FOR{each episode}
    \STATE Reset environment and observe initial state $s^0$
    \FOR{each step $t$}
        \STATE Select actor based on critic scores; take action $a^t$
        \STATE Apply control: TS ratio, BS power, RIS phase shifts
        \STATE Observe reward $r^t$, next state $s^{t+1}$; store transition
        \IF{policy update time}
            \STATE Update critics using softmax-weighted Q-target
            \STATE Update selected actor with entropy-regularized loss
            \STATE Soft update target networks
        \ENDIF
    \ENDFOR
\ENDFOR
\STATE \textbf{Output:} Optimal policy $\mu^*(s)$ for $\{\tau^*, \mathbf{P}_U^*, \bm{\Theta}^*\}$
\end{algorithmic}
\end{algorithm}
% % ***********************************************************

In terms of computational complexity, we focus on the online deployment phase, assuming that training is performed offline. During deployment, the proposed SSD3 agent selects actions through a forward pass of the chosen actor network. For an actor network with \( L \) hidden layers, each containing \( n \) neurons, and input and output dimensions \( I \) and \( O \), respectively, the worst-case per-step complexity is \( \mathcal{O}(\max(In, n^2, nO)) \). The use of entropy-regularized actor updates and softmax-weighted Q-targets improves training robustness but does not affect inference-time complexity. Compared to iterative optimization methods, SSD3 enables real-time decision-making with significantly lower computational overhead at deployment.



% ***********************************************************
\section{Simulation Results} \label{Sec_Simu}
% ***********************************************************
This section evaluates the performance of the proposed SSD3 algorithm for a UAV-mounted RIS system with \( K = 3 \) users. We examine its convergence under varying UAV jitter levels and compare its EH efficiency against TD3, DDPG, and exhaustive search. The results demonstrate the robustness and near-optimality of SSD3. Table~\ref{tab:Simu} lists the simulation parameters used unless stated otherwise.

\begin{table}[!t]
\caption{Simulation Parameters}
\label{tab:Simu}
\centering
\scalebox{0.8}{
\begin{tabular}{| c | c | c |}
\hline
\textbf{Symbol} & \textbf{Description} & \textbf{Value} \\
\hline
$A_{\text{sim}}$ & Simulation area & $20$ m $\times$ $20$ m \\
\hline
$N$ & Number of RIS elements & $16$ \\
\hline
$a$, $b$ & LoS environment constants & $9.61$, $0.16$ \\
\hline
$\beta_0$ & Reference path loss at $d_{\text{ref}} = 1$ m & $-30$ dB \\
\hline
$\sigma_k^2$ & Noise power at user $k$ & $-102$ dBm \\
\hline
$P_{BS}^{\max}$ & BS maximum transmit power & $500$ W \\
% \hline
% $\alpha$ & Path loss exponent (BS-RIS) & $3$ \\
% \hline
% $\nu$ & Path loss exponent (RIS-user) & $2.5$ \\
\hline
$R_{\text{min}}$ & Minimum user rate requirement & $70$ Mbps \\
\hline
$c$, $d$ & Non-linear harvested parameters& $6400$, $0.003$ \\
\hline
\end{tabular}}
\end{table}

% ***********************************************************
\begin{figure}[!t]
\centering
\includegraphics[width=0.7\columnwidth]{figs/Fig_Rewards.pdf}
\caption{Cumulative reward per training episode under varying UAV angular jitter levels.}
\label{Fig_Rewards}
\end{figure}
% ***********************************************************
% ***********************************************************
\begin{figure}[!t]
\centering
\includegraphics[width=0.7\columnwidth]{figs/Fig_EH.pdf}
\caption{Comparison of EH efficiency per time step across different learning-based and baseline algorithms with $\sigma_j=0.1$.}
\label{Fig_EH}
\end{figure}
% ***********************************************************
Fig. \ref{Fig_Rewards} illustrates the convergence of the proposed SSD3 algorithm under varying levels of UAV angular jitter. As expected, performance degrades with increasing jitter variance, but the cumulative reward consistently converges across all cases, demonstrating the robustness of SSD3 to orientation instability. Notably, the gap between the no-jitter case and higher-jitter scenarios (e.g., $\sigma_j=$ 0.2) remains bounded, confirming the algorithm's resilience in realistic UAV conditions.

Fig. 3 compares the EH efficiency of SSD3 with DDPG, TD3, and exhaustive search under a jitter level of $\sigma_j=$ 0.1. While SSD3 achieves slightly lower EH efficiency than the exhaustive search, it provides a significantly lower-complexity and more intelligent and adaptive solution suited for real-time UAV-RIS system operation. Compared to DDPG and TD3, SSD3 consistently delivers higher performance across all time steps, benefiting from entropy regularization and softmax-weighted Q-value estimation that enhance stability and exploration.

% *****************************************
\begin{table}[!t]
\centering
\caption{Average EH Efficiency for $\sigma_j = 0.1$}
\scalebox{0.8}{
\begin{tabular}{|c|c|}
\hline
\textbf{Algorithm} & \textbf{Average EH Efficiency (\%)} \\
\hline
Exhaustive Search & 53.09 \\ \hline
SSD3 (Proposed)   & 45.07 \\ \hline
TD3               & 38.48 \\ \hline
DDPG              & 23.28 \\ 
\hline
\end{tabular}}
\label{tab:avg_eh_efficiency}
\end{table}
% *****************************************

Table~\ref{tab:avg_eh_efficiency} summarizes the average EH efficiency across different optimization schemes for \( \sigma_j = 0.1 \). The proposed SSD3 algorithm achieves an average EH efficiency of 45.07\%, closely approaching that of the exhaustive search method, which yields the highest efficiency at 53.09\% but incurs an extensive computational cost. Compared to SSD3, the TD3 baseline achieves 38.48\%, while DDPG records the lowest performance at 23.28\% due to its known overestimation bias and reduced stability. 

% 


% ****************************
\section{Conclusion}
% ****************************
In this letter, we proposed a DRL-based joint optimization framework to maximize the EH efficiency in a UAV-mounted RIS system under nonlinear RF EH dynamics and UAV jitter. The original nonconvex and time-coupled optimization problem involving BS power allocation, RIS phase shifts, and TS control was reformulated as an MDP. To solve it, we developed the SSD3 algorithm, which integrates dual actor-critic networks, entropy regularization, and softmax-weighted Q-value estimation for improved learning stability and exploration. Simulation results demonstrated that SSD3 achieves superior EH efficiency and faster convergence compared to DDPG and TD3 baselines, and remains robust under varying levels of UAV angular jitter. These results confirm that SSD3 offers a practical and effective solution for energy-constrained UAV-mounted RIS systems, achieving near-optimal performance with lower complexity than exhaustive search and greater robustness than conventional DRL methods.




