%       Recall the abductive causal theory $\mathcal{T} := (\Delta, \mathfrak{A})$ in Example \ref{example - abductive causal theory} where 
%     \begin{align*}
%         & \mathfrak{A}:= && \{ spontaneously\_smokes(X), \neg spontaneously\_smokes(X), \neg smokes (X) \}_{ X \in \{ kilian, jakob \} }  \\
%         & \Delta:= &&  \{ spontaneously\_smokes( jakob ) \Rightarrow  smokes( jakob ), \\
%         &&&   spontaneously\_smokes( kilian ) \Rightarrow  smokes( kilian ), \\
%         &&&  smokes( kilian ) \Rightarrow  smokes( jakob ),\\
%         &&&  smokes( jakob ) \Rightarrow  smokes( kilian )\}.
%     \end{align*}
%     Further, let
%     $$
%     {\omega := \{spontaneously\_smokes(kilian),smokes(kilian) \}}
%     $$
%     be the world where Kilian (spontaneously) smokes, while Jakob is not smoking (spontaneously). The explanatory content $\mathcal{T} \vert_{\omega}$ is obtained by removing the rule~${smokes(kilian) \Rightarrow smokes (jakob)}$ from $\Delta$. The logical content, denoted as $\Logic (\mathcal{T})$, is obtained by replacing the ``$\Rightarrow$'' symbol in $\Delta$ with the implication ``$\rightarrow$''.
%     \label{example - explainable content}
% \end{example}

The constraint and explanatory content of a causal system $\textbf{CS}$ allows for the definition of the following events.

\begin{definition}[Explainability]  
    Let $\textbf{CS} := (\Delta, \mathcal{E}, \mathcal{O})$ be a causal system, and let $\omega$ be a world. A formula $\phi$ is \textbf{explainable} in $\omega$, written ${\omega \models \explains (\phi)}$, if 
    $$
    \phi \in \mathcal{C}\vert_{\omega} (\omega \cap \mathcal{E}) \quad \text{or} \quad \neg \phi \in \mathcal{C}\vert_{\omega} (\omega \cap \mathcal{E}).
    $$
    A world $\omega$ satisfies \textbf{(natural) necessity} with respect to $\textbf{CS}$ if $\omega \models \constraint(\textbf{CS})$. A world $\omega$ is \textbf{explainable} with respect to $\textbf{CS}$ if all formulas $\phi \in \omega$ are explainable, i.e., ${\omega \models \explains (\phi)}$ for all formulas $\phi$, or equivalently, ${\omega \models \explains (l)}$ for all literals $l$. The event $\necessary (\textbf{CS})$ that $\textbf{CS}$ satisfies \textbf{(natural) necessity} is the set 
    $$
    \necessary (\textbf{CS}) := \{ \omega \text{ world: } \omega \models \constraint (\textbf{CS}) \}.
    $$
    The event that $\textbf{CS}$ is \textbf{(causally) sufficient} is the set of all explainable worlds, 
    $$
    \sufficient (\textbf{CS}) := \{ \omega \text{ world: } \omega \models \explains (l) \text{ for all literals } l \}.
    $$
    \label{definition - causal decidability}
\end{definition}


We start with the following observation about causal rules, which can also be found in Chapter 3 of \cite{Bochman}.

\begin{lemma}
    Stating a causal rule $\phi \Rightarrow \psi$ in a causal theory $\Delta$ is equivalent to stating the \textbf{constraint} $\phi \land \neg \psi \Rightarrow \bot$ and the \textbf{explanatory rule} $ \phi \land \psi \Rightarrow \psi$. 
    \label{lemma - splitting a causal rule into a constraint and an explanatory component}
\end{lemma}

\begin{proof}
    Assume $\phi \Rightarrow \psi \in \Delta$. We show that $\phi \land \neg \psi \Rightarrow \bot$ and  $ \phi \land \psi \Rightarrow \psi$ can be obtained by using the axioms of a causal production inference relation:

    Applying (Falsity) and (Stengthening) in Definition \ref{definition - production inference relation} we obtain 
    $$
    \phi \land \psi \land \neg \psi \Rightarrow \perp.
    $$ 
    Next, apply (Cut) of Definition \ref{definition - regular production infernece relation} to obtain the desired constraint 
    $$
    \phi \land \neg \psi \Rightarrow \bot
    .$$ 
    Note that the explanatory rule $\phi \land \psi \Rightarrow \psi$ follows from (Strengthening) in Definition \ref{definition - production inference relation}.

    Next , assume the $\phi \land \neg \psi \Rightarrow \bot \in \Delta$ and $\phi \land \psi \Rightarrow \psi \in \Delta$. We show now that the rule $\phi \Rightarrow \psi$ follows as before:

    Applying (Weakening) in Definition \ref{definition - production inference relation}, we find 
    $$
    \phi \land \neg \psi \Rightarrow \psi.
    $$ 
    Hence, (Or) in Definition \ref{definition - basic prodoction inference relation} and (Strengthening) in Definition \ref{definition - production inference relation} yield 
    $$
    \phi \Rightarrow \psi
    .$$.
\end{proof}

We are now able to give the desired reformulation of the semantics of causal systems.

\begin{proposition}
    Let $\textbf{CS} := (\Delta, \mathcal{E}, \mathcal{O})$ be a causal system.  
    A world $\omega$ is a causal world of $\textbf{CS}$ if and only if 
    \[
    \omega \in \necessary (\textbf{CS}) \cap \sufficient (\textbf{CS}) \cap \mathcal{O},
    \]
    where we identify the observations $\mathcal{O}$ with the set of all worlds $\omega \models \mathcal{O}$.
    \label{proposition - splitting in logical and explanatory content under causal sufficiency}
\end{proposition}


\begin{proof}
Assume that $\omega$ is a causal world of $\textbf{CS}$. According to Definition \ref{definition - semantics of causal systems}, it follows that $\omega = \mathcal{C} (\omega \cap \mathcal{E})$ and $\omega \models \mathcal{O}$, i.e., $\omega \in \mathcal{O}$. 

Suppose there is a causal rule ${R := (\phi \Rightarrow \psi) \in \Delta}$ such that $\omega \not \models \constraint (R)$, i.e., $\omega \models \phi \land \neg \psi$. According to Lemma \ref{lemma - splitting a causal rule into a constraint and an explanatory component}, we may, without loss of generality, assume that $\phi \land \neg \psi \Rightarrow \bot \in \Delta$. 

Since ${\omega = \mathcal{C} (\omega \cap \mathcal{E})}$, it follows that ${(\omega \cap \mathcal{E}) \Rrightarrow_{\Delta} \phi \land \neg \psi}$. Next, applying~(Cut) in Definition \ref{definition - regular production infernece relation} yields ${(\mathcal{E} \cap \omega) \Rrightarrow_{\Delta} \bot}$ and ${\bot \in \mathcal{C} (\omega \cap \mathcal{E})}$, which contradicts the fact~${\omega = \mathcal{C} (\omega \cap \mathcal{E})}$. Hence, ${\omega \models \constraint(\textbf{CS})}$ and~${\omega \in \necessary(\textbf{CS})}$. 

Since ${\Delta = \Delta \vert_{\omega}}$ and~${\mathcal{C} = \mathcal{C} \vert_{\omega}}$, $\omega$ is explainable with $\textbf{CS}$, i.e.,~${\omega \in \sufficient (\textbf{CS})}$.

Conversely, assume that ${\omega \in \necessary (\textbf{CS}) \cap \sufficient (\textbf{CS}) \cap \mathcal{O}}$. It follows that ${\omega \models \constraint (\textbf{CS})}$, $\omega \models \mathcal{O}$, and ${\mathcal{C}\vert_{\omega} (\omega \cap \mathcal{E}) = \omega}$. Thus, $\Delta \vert_{\omega} = \Delta$ and~${\mathcal{C} = \mathcal{C}\vert_{\omega}}$, concluding that $\omega$ is a causal world.
\end{proof}


Let $\textbf{CS} := (\Delta, \mathcal{E}, \mathcal{O})$ be a causal system. Recall that the axioms of a causal production inference relation in Definitions \ref{definition - production inference relation}, \ref{definition - regular production infernece relation}, and \ref{definition - basic prodoction inference relation} capture all properties of implication except reflexivity, i.e., $\phi \rightarrow \phi$. Hence, we argue for the following result:

\begin{formalization}[Natural Necessity]
    Within a world $\omega$, explainability, as represented by a causal system ${\textbf{CS} := (\Delta, \mathcal{E}, \mathcal{O})}$, satisfies \emph{natural necessity} as stated in Principle~\ref{principle - Aquinas} if and only if ${\omega \models \constraint (\textbf{CS})}$. 

    Thus, the set $\necessary (\textbf{CS})$ consists of all worlds in which \emph{natural necessity}, as defined in Principle~\ref{principle - Aquinas}, holds.
    \label{formalization - natural necessity}
\end{formalization}


If we abandon \textit{natural necessity} in Principle \ref{principle - Aquinas}, then \textit{sufficient causation} in Assumption~\ref{principle - Leibniz} ensures that every world is explainable. We argue for the following result:

\begin{formalization}[Sufficient Causation]
    Within a world $\omega$, explainability, as represented by a causal system ${\textbf{CS} := (\Delta, \mathcal{E}, \mathcal{O})}$, satisfies \emph{sufficient causation} as stated in Assumption~\ref{principle - Leibniz} if and only if ${\omega \models \explains (l)}$ for all literals $l$. 

    Thus, the set ${\sufficient (\textbf{CS})}$ consists of all worlds in which \emph{sufficient causation}, as defined in Assumption~\ref{principle - Leibniz}, holds.
    \label{formalization - sufficient causation}   
\end{formalization}





\section{Knowledge-\textit{why} under Uncertainty}
\label{sec: Knowledge under Uncertainty}

Since knowledge about the real world typically involves uncertainty, the next goal is to extend Aristotle's areas of science, as represented by causal systems in Section~\ref{sec: Knowledge in Deterministic Systems}, by incorporating degrees of belief, specifically probabilities.


\subsection{Preliminaries}

As in Section~\ref{sec: Knowledge in Deterministic Systems}, we begin by gathering the prerequisites for our endeavor: Section~\ref{subsubsec: Probability Theory} introduces the basics of probability theory, and Section~\ref{subsubsec: The Principle of Maximum Entropy: Deduction under Uncertainty} reviews the principle of maximum entropy. Sections~\ref{subsubsec: Causal Bayesian Networks and the Principle of Causal Irrelevance} and~\ref{subsubsec: Probabilistic Functional Causal Models} introduce Bayesian networks and probabilistic causal models -- formalisms for representing probabilistic causal knowledge -- along with the notions of external intervention from \cite{Causality}.


