    \includegraphics[page=2]{figures/1+eps-approx-triangle.pdf}
    \caption{Visualization of Case 2 in the proof of \cref{theo:approx-triangle-queries}. The third point $x$ of $\Delta^*(p,q)$ lies in the cell centred at $c$. Since $\Delta_{pq{x_{c'}}}$ is returned, it holds  $|\Delta_{pq{x_{c'}}}|\leq |\Delta_{pq{x_c}}|$, where $x_{c'}$ and $x_c$ are $(1+\varepsilon_2)$-approximated nearest neighbours of $c'$ and $c$.}
    \label{fig:1+eps-approx-triangle-case2}
\end{figure}

The query algorithm performs two deletions, two insertions, and $1 + (3 \alpha / \varepsilon_3)^d = \bigo(1)$ approximate nearest neighbour queries in the data structure of \cref{theo:nearest-neighbour-query}~\cite{AryaMountDS1998}. Each such operation takes $\bigo(\log n)$ time. Therefore, the entire query algorithm takes $\bigo(\log n)$ time.
\end{proof}


\subsection{NP-Hardness}

Our $(2+\varepsilon)$-spanner construction involves computing undirected $(1+\varepsilon)$-approximations of minimum-perimeter triangles, which are subsequently oriented. A similar approach is used in~\cite{ESA23} where they prove, for convex point sets, orienting a greedy triangulation yields a plane oriented $O(1)$-spanner.
Both results could be improved by optimally orienting the underlying undirected graph. 
The authors in~\cite{ESA23} pose, as an open question, whether it is possible to compute, in polynomial time, an orientation of any given undirected geometric graph, that minimises the oriented dilation. 
We answer this question by showing NP-hardness.%, which makes it unlikely to improve our approach by orienting the computed undirected graph optimally.

%The authors in~\cite{ESA23} proved NP-hardness of computing a sparse oriented minimum dilation spanner for point sets in $\mathbb{R}^d$ with $d>1$. 
%For convex point sets, the authors in~\cite{ESA23}  constructed a plane oriented $\bigo(1)$-spanner. Their result based on computing a suitable orientation of the greedy triangulation. Unlikely, orienting a given undirected spanner optimal is NP-hard.

\begin{theorem}\label{theo:np-hard-decision-orient}
Let $P$ be a finite set of points in a metric space and let $G$ be an undirected graph with vertex~$P$.
Given a real number $t'$, it is NP-hard to decide if there exists an orientation $\oriented{G}$ of $G$ with oriented dilation $\odil(\oriented{G})\leq t'$. 
This is even true for point sets in the Euclidean plane. 
%Given an undirected geometric graph $G$ and a parameter $t'$, it is NP-%hard to decide if there is an orientation $\oriented{G}$ of $G$ with 
%oriented dilation $\odil(\oriented{G})\leq t'$. 
\end{theorem}
\begin{proof}
   We reduce from the NP-complete problem planar $3$-SAT~\cite{Lichtenstein82}. We start with a planar Boolean formula $\varphi$ in conjunctive normal form with an incidence graph $G_\varphi$ as illustrated in \cref{fig:example-planar-3SAT}.
   This graph can be embedded on a polynomial-size grid whose cells have side length one~\cite{Godau1999,Lichtenstein82}. 
     We give a construction for a graph $G$ based on $G_\varphi$ such that there is an orientation $\overrightarrow{G}$ of $G$ with dilation $\odil(\overrightarrow{G})\leq t'$ with $t' := 1.043$ if and only if $\varphi$ is satisfiable. 

