    Let $\oriented{G}=(P',\oriented{E})$ be an oriented graph with 
    %\begin{equation*}
     $\oriented{E}=\{(p,u),(v,p)\mid p\in P\} \cup \{(u,v)\}.$
    %\end{equation*}

We prove that the weight $w(C)$ of the minimum triangle can be computed by computing $\odil(\oriented{G})$. In particular, we show that $w(C)=\frac{180M}{\odil(\oriented{G})}-45M$.

    We proceed by computing the oriented dilation of $\oriented{G}$. 
    We first note that all edges of $\oriented{G}$ have weight $30M$. 

    For every tuple of $u$ or $v$ and a point $p\in P$, the shortest closed walk is a triangle of length  
   $|C_{\oriented{G}}(u,p)|=|C_{\oriented{G}}(v,p)|=|C_{\oriented{G}}(u,v)|=3\cdot 30M=90M$. 
   Their minimum triangle contains two edges of length $30M$.  %(and one edge which is at least $22M$ long).
    Therefore, their dilation is
    \begin{equation*}
      \odil(u,p)= \frac{|C_{\oriented{G}}(u,p)|}{|\Delta^*(u,p)|}\leq \frac{90M}{2 \cdot 30M}=1.5.
    \end{equation*}
    Analogously, it holds that $\odil(v,p)\leq 1.5$ for $p\in P$.

    For $u$ and $v$, it holds that $\odil(u,v)=1$, because every triangle in $P'$ containing $u$ and $v$ is an oriented closed walk in $\oriented{G}$.

For two distinct points $p,q\in P$, the shortest closed walk containing $p$ and $q$ visits $u$ and $v$ and has length $|C_{\oriented{G}}(p,q)|=6\cdot 30M=180M$. For their minimum triangle holds 
  %  \begin{equation*}
       $ |\Delta^*(p,q)|\leq 3\cdot29M=87M$. 
   % \end{equation*}    
    Since their dilation is larger than $2$,
    % \begin{equation*}
    %     \odil(p,q)= \frac{|C_{\oriented{G}}(p,q)|}{|\Delta^*(p,q)|}\geq \frac{180M}{87M}>2,
    % \end{equation*}
    a worst-case pair of $\oriented{G}$ must be a pair in~$P$. 
    Therefore, the oriented dilation of the constructed graph $\oriented{G}$ is
    \begin{equation*}
        \odil(\oriented{G})=\underset{p,q\in P}{\max} \frac{|C_{\oriented{G}}(p,q)|}{|\Delta^*(p,q)|} 
        =\frac{180M}{\underset{p,q,p^*\in P}{\min} w'(p,q)+w'(q,p^*)+w'(p,p^*)}  >2.
    \end{equation*}
     Since $C$ is a triangle and $w(C)\leq 27M$, it holds that
    \begin{equation*}
        \underset{p,q,p^*\in P}{\min}|pq|+|qp^*|+|p,p^*| = \underset{p,q,p^*\in P}{\min} w(p,q)+w(q,p^*)+w(p,p^*)+3\cdot 15M= w(C)+45M.
    \end{equation*}
    Therefore, the oriented dilation of $\oriented{G}$ is achieved by the minimum-length triangle $C$.
    Consequently, given the oriented dilation of $\oriented{G}$, the length of $C$ is
  %  \begin{equation*}
       $w(C)=\frac{180M}{\odil(\oriented{G})}-45M$.
  %  \end{equation*}

The most expensive operation in our reduction is defining the metric on $\bigo(n^2)$ points with distances in $\left[22M,30M\right]$. Following the definitions in~\cite{WilliamsW18}, all instances have size $\bigo(n^2\operatorname{polylog}(M))$ and all operations take subcubic time.

    Thus, computing the oriented dilation of an oriented metric graph is at least as hard as  finding a minimum weight triangle in an undirected graph.
    \end{proof}

To compute the oriented dilation, testing all $\binom{n}{2}$ point tuples seems to be unavoidable. However, to approximate the oriented dilation,  we show that, %as for undirected dilation (see \cite{gudmundsson2018.dilation,Narasimhan.2007} for a survey), 
a linear set of tuples suffices.

\begin{theorem}\label{theo:approx-odil}
Let $P$ be a set of $n$ points in $\mathbb{R}^d$, let $\oriented{G}$ be an oriented graph on $P$, and let $\varepsilon>0$ be a real number.
Assume that, in $T(n)$ time, we can construct a data structure such that,
for any two query points $p$ and $q$ in $P$, we can return, in $f(n)$ time, a $k$-approximation to the length of a shortest path in $G$ between $p$ and $q$. Then we can compute a value $\overline{\odil}$ in $\bigo(T(n) + n(\log n +f(n)))$ time, such that
\begin{equation*}
    (1-\varepsilon)\cdot \odil(\oriented{G}) \leq  \overline{\odil}  \leq k\cdot \odil(\oriented{G}).
\end{equation*}
%$\bigo(\frac{1}{\varepsilon^d} n(d\log n +f(n)))$ time
\end{theorem}
\begin{proof}
Let the constants in \cref{alg:approx-odil} be equal to $\varepsilon_1= {\varepsilon}/{2}$ and $s= {28}/{\varepsilon}$.
Let $t^*$ be the dilation of a given oriented graph $\oriented{G}$ on $P$.
We prove that 
 \[ (1-\varepsilon)t^* \leq  \overline{\odil} \leq kt^*,\]
where $\overline{\odil}$ is the dilation approximated by \cref{alg:approx-odil}. 

Throughout this proof, let $p,q\in P$ be a worst-case pair in $\oriented{G}$, i.e., $\odil(p,q)=t^*$.

\subparagraph{Upper bound.}
    For each well-separated pair $\{A,B\}$, \cref{alg:approx-odil} picks two points $a\in A$ and $b\in B$, approximates the length of a shortest closed walk $C_{\oriented{G}}(a,b)$ containing $a$ and $b$ and their minimum triangle $\Delta^*(a,b)$. 
    It holds that
    \begin{equation*}
        \overline{\odil}%=\underset{\substack{a\in A,\\b\in B}}{\max}\bigg\{ \frac{\overline{d}_G(a,b)+\overline{d}_G(b,a)}{|\Delta_{abc}|}\bigg\}
        \leq \underset{a\in A, b\in B}{\max} \frac{k\cdot |C_{\oriented{G}}(a,b)|}{|\Delta^*(a,b)|} = k\cdot \underset{a\in A, b\in B}{\max} \odil(a,b) \leq k \cdot\odil(\oriented{G}) = k \cdot t^*.
    \end{equation*}

  \subparagraph{Lower bound.} 
   Let $\{A,B\}$ be the well-separated pair with $p\in A$ and $q\in B$. We distinguish cases based on whether $p$ and/or $q$ are picked by \cref{alg:approx-odil} while processing the pair $\{A,B\}$ or not.

\subparagraph{Case 1:} neither $p$ nor $q$ is picked by \cref{alg:approx-odil}.

   Let $a\in A$ and $b\in B$ be the points picked by \cref{alg:approx-odil}. 

First, we bound the length of a shortest closed walk containing $p$ and $q$ by
\begin{equation*}
    |C_{\oriented{G}}(p,q)|\leq |C_{\oriented{G}}(p,a)|+|C_{\oriented{G}}(a,b)|+|C_{\oriented{G}}(b,q)|\leq t^*|\Delta^*(p,a)|+|C_{\oriented{G}}(a,b)|+t^*|\Delta^*(b,q)|.
\end{equation*}

Since $p$ and $q$ are both not picked, this implies $|A|\geq 3$ and $|B|\geq 3$. Analogously to \cref{eq:bound-Delta-same-set-pair}, we bound $|\Delta^*(p,a)|$ and $|\Delta^*(b,q)|$ both by $3/s |\Delta^*(p,q)|$. It follows that
    \begin{equation*}
        |C_{\oriented{G}}(p,q)|\leq 2\cdot  3/s\cdot t^* \cdot|\Delta^*(p,q)|+|C_{\oriented{G}}(a,b)| = 6/s \cdot |C_{\oriented{G}}(p,q)|+|C_{\oriented{G}}(a,b)|  .
    \end{equation*}

  Due to \cref{theo:delta-ab-WSPD}, we use $|\Delta^*(a,b)|\leq (1+8/s) |\Delta^*(p,q)|$ to bound
\begin{equation*}
 |C_{\oriented{G}}(p,q)|\leq \frac{s}{s-6}  |C_{\oriented{G}}(a,b)|= \frac{s}{s-6}  \odil(a,b) |\Delta^*(a,b)| \leq  \frac{s+8}{s-6}  \odil(a,b) |\Delta^*(p,q)|.
\end{equation*}

Since $t^*=\frac{|C_{\oriented{G}}(p,q)|}{|\Delta^*(p,q)|}$, this leads us to a lower bound of the dilation of $a$ and $b$, which is
\begin{equation*}
     \odil(a,b) \geq  \frac{s-6}{s+8} \cdot t^* \geq \left(1- 14/s\right) t^* .
\end{equation*}

For the picked points $a$ and $b$, \cref{alg:approx-odil} computes an approximation of $C_{\oriented{G}}(a,b)$ and a $(1+\varepsilon_1)$-approximation of $\Delta^*(p,b)$. It holds that
 \begin{equation*}
        \overline{\odil} \geq \frac{|C_{\oriented{G}}(a,b)|}{(1+\varepsilon_1)|\Delta^*(a,b)|} \geq (1-\varepsilon_1) \odil(a,b) \geq (1-\varepsilon_1)\left(1- 14/s\right) t^*.
    \end{equation*}

   Since  $\varepsilon_1=\varepsilon/2$ and $s=28/\varepsilon$, we conclude that 
 \begin{equation*}
        \overline{\odil} \geq %\left(1-\frac{\varepsilon}{2}\right)\cdot\left(1- \frac{14\varepsilon}{28}\right) t^*=
        \left(1-\varepsilon/2\right)^2\cdot t^*
       \geq (1-\varepsilon)\cdot t^*.
    \end{equation*}

  \subparagraph{Case 2:} either $p$ or $q$ is picked by \cref{alg:approx-odil}.

Without loss of generality, let $p$ be picked for $A$ and a distinct point $b$ be picked for $B$.

Analogously to Case 1, we can show 
\begin{equation*}
    |C_{\oriented{G}}(p,q)|\leq |C_{\oriented{G}}(p,b)|+|C_{\oriented{G}}(b,q)|\leq  \frac{s+8}{s-6}  \odil(a,b) |\Delta^*(p,q)|, 
\end{equation*}
which leads us to 
 \begin{equation*}
        \overline{\odil} \geq (1-\varepsilon_1) \odil(a,b) \geq (1-\varepsilon) t^*.
    \end{equation*}

 \subparagraph{Case 3:} both $p$ and $q$ are picked by \cref{alg:approx-odil}.

Since \cref{alg:approx-odil} computes an approximation of $C_{\oriented{G}}(p,q)$ and $(1+\varepsilon_1)$-approximation of $\Delta^*(p,q)$, it holds that
 \begin{equation*}
        \overline{\odil} \geq \frac{|C_{\oriented{G}}(p,q)|}{(1+\varepsilon_1)|\Delta^*(p,q)|}\geq (1-\varepsilon_1)  \odil(p,q)  \geq (1-\varepsilon)t^*,
    \end{equation*}
where the last inequality  follows from  $\varepsilon_1=\varepsilon/2$.\bigskip


   The preprocessing is dominated by computing the data structure for answering approximate shortest pair and    
   a well-separated pair decomposition in $\bigo(T(n) + n \log n)$ time (\cref{theo:wspd-construction}).
     For each of the $\bigo(n)$ pairs, we pick two points $a$ and $b$ and approximate their smallest triangle in $\bigo(\log n)$ time (compare to~\cref{theo:approx-triangle-queries}). The runtime to approximate the length of a shortest closed walk containing $a$ and $b$ depends on the runtime $f(n)$ of the used approximation algorithm. Therefore, the oriented dilation of a given graph can be approximated in $\bigo(T(n) + n(\log n +f(n)))$ time.
\end{proof}

Our approximation algorithm (\cref{alg:approx-odil}) uses the WSPD to achieve a suitable selection of $\bigo(n)$ point tuple that needs to be considered. 
The algorithm and its analysis work similar to our $(2+\varepsilon)$-spanner construction (compare to \cref{alg:wspd-oriented}). 
 For each selected tuple, the algorithm approximates their oriented dilation by approximating their minimum triangle and shortest closed walk.
% Note that a shortest closed walk containing $p$ and $q$ is simply the union of a shortest path from $p$ to $q$ and a shortest path from $q$ to $p$. 

The precision and runtime of this approximation depend on approximating the length of a shortest path between two query points. 
The point-to-point shortest path problem in directed graphs is an extensively studied problem (see \cite{goldberg05.P2P} for a survey). 
Alternatively, shortest path queries can be preprocessed via approximate APSP (see~\cite{DoryFKNWV24.APSP,SahaY24.APSP,Zwick02.APSP}).
For planar directed graphs, the authors in~\cite{ArikatiCCDSZ96} present a data structure build in $\bigo(n^2 / r)$ time, such that the exact length of a shortest path between two query points can be returned in $\bigo(\sqrt{r})$ time. 
Setting $r=n$ minimizes the runtime of our \cref{alg:approx-odil} to $\bigo(n \sqrt{n})$. 
It should be noted that even with an exact shortest path queries ($k=1$) the oriented dilation remains an approximation due to the minimum-perimeter triangle approximation.

