\subsection{Scott Domains}    

\begin{defin}
Let $K\subseteq\hat{K}$ be a c.h.p.o.
	\begin{enumerate}
		\item $x\in K$ is compact if for every directed $X\subseteq K$ one has
		$$x\precsim\bigcurlyvee X~~\Longrightarrow~~x\precsim x_0~\text{for some $x_0\in X$}.$$ 
		\item $K$ is an algebraic c.h.p.o if for all $x\in K$ the h.p.o $x\downarrow= \langle y\precsim x\,|\,y~\text{compact}\rangle$ is directed and $x\simeq\bigcurlyvee (x\downarrow).$
        \item $K$ is bounded complete if for every h.p.o $X\subseteq K$ with an upper bound has supremum. 
	\end{enumerate}
\end{defin}

\begin{defin}
    A Homotopy Scott Domain is a bounded complete algebraic c.h.p.o.
\end{defin}

\begin{prop}[\cite{Tese}]\label{continuity by compacts}
	Let $K$ be algebraic and $f:K\rightarrow K$. Then $f$ is continuous iff $f(x)\simeq\bigcurlyvee\langle f(e)\,|\,e\precsim x~\text{and}~e~\text{compact}\rangle$.
\end{prop}
\begin{proof}[Proof]
	$(\Rightarrow)$ Let $f$ be continuous. Then 
	\begin{align*}
		f(x)&=f(\bigcurlyvee\langle e\precsim x\,|\,e~\text{compact}\rangle) \\
		&\simeq\bigcurlyvee\langle f(e)\,|\,e\precsim x~\text{and}~e~\text{compact}\rangle. 
	\end{align*}
	$(\Leftarrow)$ First we check that $f$ is monotonic. If $x\precsim y$, then
	$$\langle e\precsim x\,|\,e~\text{compact}\rangle\subseteq\langle e\precsim y\,|\,e~\text{compact}\rangle,$$
	hence
	\begin{align*}
		f(x)&\simeq\bigcurlyvee\langle f(e)\,|\,e\precsim x~\text{and}~e~\text{compact}\rangle \\
		&\precsim \bigcurlyvee\langle f(e)\,|\,e\precsim y~\text{and}~e~\text{compact}\rangle \\
		&\simeq f(y).
	\end{align*}
	Now let $X\subseteq K$ directed. Then
	\begin{align*}
		f(\bigcurlyvee X)&\simeq\bigcurlyvee\langle f(e)\,|\,e\precsim \bigcurlyvee X~\text{and}~e~\text{compact}\rangle \\
		&\precsim\bigcurlyvee\langle f(x)\,|\,x\in X\rangle;\hspace{0.5cm}\text{by compactness and monotonicity of $f$} \\
		&\precsim f(\bigcurlyvee X);\hspace{0.5cm}\text{by monotonicity and definition of supremum}.
	\end{align*}
	Thus, $f(\bigcurlyvee X)\simeq\bigcurlyvee f(X)$.
\end{proof}
\begin{prop}[\cite{Tese}]
	Let $K,K'$ be c.h.p.o's.
	\begin{enumerate}
		\item $(x,y)\in K\times K'$ is compact iff $x$ and $y$ are compact.
		\item $K$ and $K'$ are algebraic, then $K\times K'$ is algebraic.
        \item $K$ and $K'$ are bounded completes, then $K\times K'$ is bounded complete.
	\end{enumerate}
\end{prop}
\begin{proof}[Proof]
	1. $(\Rightarrow)$ Let $X\subseteq K$ and $Y\subseteq K'$ be directed such that $x\precsim\bigcurlyvee X$ and $y\precsim\bigcurlyvee Y$. Hence $$(x,y)\precsim(\bigcurlyvee X,\bigcurlyvee Y)=\bigcurlyvee (X\times Y).$$
	By hypothesis, $(x,y)\precsim (x_0,y_0)$ for some $(x_0,y_0)\in X\times Y$. Thus, $x$ and $y$ are compact.

	\bigskip $(\Leftarrow)$ Let $X\subseteq K\times K'$ be directed such that $$(x,y)\precsim\bigcurlyvee X= (\bigcurlyvee X_0, \bigcurlyvee X_1)=\bigcurlyvee (X_0\times X_1).$$  
	By hypothesis, there are $x_0\in X_0$ and $y_0\in X_1$  such that $x\precsim x_0$ and $y\precsim y_0$. Since $(x_0,y_0)\precsim \bigcurlyvee (X_0\times X_1)=\bigcurlyvee X$, there exists $(x_1,y_1)\in X$ such that $(x,y)\precsim (x_0,y_0)\precsim (x_1,y_1)$. Hence $(x,y)$ is compact.

	\bigskip 2. Let $(x,y)\in K\times K'$. Then
	\begin{align*}
		\bigcurlyvee((x,y)\downarrow)&=\bigcurlyvee\langle(e,d)\precsim (x,y)\,|\,(e,d)~\text{compact}\rangle \\
		&=\bigcurlyvee\langle(e,d)\precsim (x,y)\,|\,\text{$e$ and $d$ are compact}\rangle;\hspace{0.5cm}\text{by 1.}\\
		&\simeq (	\bigcurlyvee (x\downarrow),	\bigcurlyvee (y\downarrow)) \\
		&\simeq (x,y);\hspace{0.5cm}\text{by hypothesis.}
	\end{align*}

    \bigskip 3. Let $K$ and $K'$ be bounded complete c.h.p.o's and the h.p.o $X\subseteq K\times K'$ with $(x_0,x_1)$ be an upper bound. By hypothesis we have
    $$\bigcurlyvee X= (\bigcurlyvee X_0, \bigcurlyvee X_1)\precsim (x_0,x_1)$$ 
\end{proof}

\begin{defin}[$Alg$ \cite{Tese}]
	Define the full subcategory $Alg\subseteq CHPO$, whose objects are the c.h.p.o's algebraic and the morphisms are continuous functors. 	
\end{defin}

Note that $Acc$, the $\infty$-category of accessible $\infty$-categories, is the generalisation of $Alg$, since all directed is filtered, every supremum is a filtered colimit, and for each $X\in Alg$, $X$ has all suprema and the full subcategory $X_c\subseteq X$ of compacts objects generates $X$ under supremum.

\begin{defin}
    	Define the full subcategory $HD\subseteq CHPO$, whose objects are Homotopy Scott Domains and the morphisms are continuous functors.
\end{defin}

\begin{prop}\label{K_n is Scott Domain}
    If $K_0$ is a Homotopy Scott Domain, then $K_{n+1}=[K_n\rightarrow K_n]$ is a Homotopy Domain Scott for each $n\geq 0$. 
    \end{prop}
    \begin{proof}
We suppose that $K_n$ is algebraic (IH) and will see that by induction $K_{n+1}=[K_n\rightarrow K_n]$ it is also. The compact elements of $K_{n+1}$ are functor of the form $\bigcurlyvee_{i=1} ^k(a_i\rightarrow b_i)$, where $a_i,b_i\in K_n$ are compacts, and $(a\Rightarrow b):K\rightarrow K$ denote the step functor induced by the map
 \[ (a\Rightarrow b)(x):= \begin{cases}
  b & \mbox{ if $ x\succsim a $}\\
  0 & \mbox{o.c}
  \end{cases}
  \]

  by degenerate higher simplexes; for example for the case of an equivalence $x\xrightarrow{\sim} y$ at $K$, we have the map induced
   \[ (a\Rightarrow b)(x\xrightarrow{\sim} y):= \begin{cases}
    1_b & \mbox{ if $ x \succsim a $}\\
    1_0 & \mbox{o.c.}
  \end{cases}
  \]

  In the same way, the other maps are induced for degenerated images of higher simplexes $\sigma:\Delta^n\rightarrow K$. These functors are compact because they depend only on a finite number of values of $K_n$. We will see how to approximate functors by compacts: Let $f\in K_{n+1}$. For each $x\in K_n$, since $K_n$ is algebraic (by IH), we have $x\simeq\bigcurlyvee(x\downarrow)=\bigcurlyvee \langle a\,|\,a\precsim x~\text{and}~a~\text{compact}\rangle$. By the continuity of $f$ and Proposition \ref{continuity by compacts}, $f(x)\simeq\bigcurlyvee\langle f(a)\,|\,a\precsim x~\text{and}~a~\text{compact}\rangle$. Since $f(a)\in K_n$, and $K_n$ is algebraic, $f$ is the supremum of compacts: $f(a)\simeq \bigcurlyvee\langle b\,|\,b\precsim f(a)~\text{and}~b~\text{compact}\rangle$. Thus, the hpo of compact functors below of $f$ is given by: 
  $$(f\downarrow)=\langle \bigcurlyvee_{i=1}^k (a_i\Rightarrow b_i):b_i\precsim f(a_i)~\text{and}~  a_i,b_i\in K_n \,\text{compacts}\rangle.$$
  Since $(f\downarrow)$ is directed (admits finite colimits) and $f(x)$ is approximated by values $b\precsim f(a)$ for $a\precsim x$, we have $f(x)\simeq \bigcurlyvee \langle g(x):g\in (f\downarrow)\rangle$.

\medskip We suppose that $K_n$ is a bounded complete (IH) and will see that by induction $K_{n+1}=[K_n\rightarrow K_n]$ it is also. Let hpo $F\subseteq [K_n\rightarrow K_n]$ with an upper bound $h\in [K_n\rightarrow K_n]$. For each $x\in K_n$, we define $(\bigcurlyvee F)(x):=\bigcurlyvee \langle f(x):f\in F\rangle$; It is well defined, since $h$ is an upper bound of $F$, $f(x)\precsim h(x)$ for each $f\in F$, given that $K_n$ is bound complete, by IH, there exists the supremum $\bigcurlyvee \langle f(x):f\in F\rangle$. The proof that $\bigcurlyvee F$ is continuous is similar to the proof of Proposition \ref{Proposition-Continuous-Funtor-chpo} and Lemma \ref{lemma-complete}. 
\end{proof}


\section{Construction of $K_\infty$ by h-projection pairs}\label{Section: Contruction of K_infty}


\begin{defin}[\cite{Martinez21}]
	Let $X$ be a Kan complex. Define $\pi_0(X):=\pi_0(|X|)$ and $\pi_n(X,x):=\pi_n(|X|,x)$ for $n>0$, with $|\,\,\,|:Kan\rightarrow Top$ being the functor of geometric realisation from the category of Kan complexes to the category of the topological spaces.
\end{defin}

The fact that a Kan complex $X$ is not contractible does not imply that every vertex $x\in X$ contains relevant information, that is, the higher fundamental groups $\pi_n(|X|,x)$ are non-trivial, nor that it contains holes in all the higher dimensions. To guarantee the existence of non-trivial Kan complexes as higher $\lambda$-models, we present the following definition.

\begin{defin}[Non-trivial Kan complex \cite{Martinez21}]
	A small Kan complex $X$ is non-trivial if
	\begin{enumerate}
		\item  $\pi_0(X)$ is infinite. 
		\item for each $n\geq 1$, there is a vertex $x\in X$ such that $\pi_n(X,x)\ncong\ast$.
		\item for each vertex $x$ of some non-degenerated horn in $X$, there is $n\geq 1$ such $\pi_n(X,x)\ncong\ast$.
	\end{enumerate}

\end{defin}

\begin{ejem}\label{Example1}
	For each $n\geq 0$, let $S^n$ the sphere of Remark \ref{Remark}. Define the non-trivial Kan complex $N$ as the disjoint union:
	$$N=\coprod_{n<\omega}S^n.$$
\end{ejem}

 Furthermore, $\pi_{n}(S^n)\ncong\ast$ for all $n\geq 1$, and there is $k > n$ such that $\pi_{k}(S^n)\ncong\ast$ for each $n\geq 2$ \cite{DBLP:books/mk/Hatcher01}. 

\begin{defin}[The c.h.p.o $N^+$]
    Define the c.h.p.o $N^+:=\langle N\cup \{\bot_0\}\rangle$, where $\bot_0$ is the unique initial object of $N^+$.
\end{defin} 




\begin{defin}[Non-Trivial Homotopy $\lambda$-Model \cite{Martinez21}]
	Let $\mathcal{K}$ be a Cartesian closed $\infty$-category, whose objects are Kan complexes. An object $K\in\mathcal{K}$ is a non-trivial homotopy $\lambda$-model, if $K$ is a non-trivial Kan complex and it is reflexive. 
\end{defin}

\begin{defin}[Sequence $K_0$, $K_1\ldots$]
    For each natural $n\geq 0$ define $K_n$ by recursion
 \begin{align*}
&K_0 := N^+, 
\\
&K_{n+1}:= F(K_n)=[K_n\rightarrow K_n].
\end{align*}
Where $F:(CHPO)^{HPrj}\rightarrow(CHPO)^{HPrj}$ is the functor defined in the Remark \ref{Example on CHPO} and $[K_n\rightarrow K_n]$ be the c.h.p.o of the $\omega$-continuous functors or continuous. Note by $\bot_n$ the unique initial objet of $K_n$.
\end{defin}

\begin{rem}\label{Remark K_n is Scott Domain}
    Notice that $K_0=N^+$ is a Scott Domain. By Proposition \ref{K_n is Scott Domain},  $K_{n+1}=[K_n\rightarrow K_n]$ is also a Scott Domain for each $n\geq 0$.
\end{rem}

\begin{defin}[Initial h-projection par]\label{Definition h-projection initial}
   Define the initial h-projection par $(f^+_0,f^-_0)$, from $K_0$ to $K_1$ in the following way:
   \begin{enumerate}
       \item[(a)] the h-embedding $f_0^+$  from $K_0$ into $K_1$ defined as $f_0^+(x) := \lambda y\in K.x'$,  for some edge $x\rightarrow x'$ at $K_0$.
       \item[(b)] and $f_0^-$ is the unique (under homotopy) h-projection associated to the h-embedding $f_0^+$  such that $f_0^-(g):= g(\bot_0)$.
       \end{enumerate}
\end{defin}

\begin{defin}[h-projection par from $K_n$ to $K_{n+1}$]
 From the definition of the functor $F(f^+,f^-)=(\lambda h.(f^+. h. f^-), \,\lambda h.(f^-. h. f^+))$  of Remark \ref{Example on CHPO}, we define the h-projection par $(f^+_n, f^-_n)$. If $n=0$ define $(f^+_0, f^-_0)$ as in Definition \ref{Definition h-projection initial} by recursion. If $n\geq 1$ define the h-projection par $(f^+_n, f^-_n)$ from $K_n$ to $K_{n+1}$ as
 $$(f_n^+,f_n^-):=F^n(f^+_0,f^-_0)=(\lambda h.(f_{n-1}^+. h. f_{n-1}^-), \,\lambda h.(f_{n-1}^-. h. f_{n-1}^+))$$ 
\end{defin}

\begin{rem}[The $K_\infty$ homotopy $\lambda$-model]
   Let $(K_n,f^-_n)$ be an inverse system of h-projections such that $\underleftarrow{lim}(K_n,f^-_n)=(K_\infty,(f_{\infty,n})_n)$. By the Theorem \ref{colimit-HPrj-category}, we have
    $(K_\infty ,(f_{n,\infty}, f_{\infty, n})_n)$ 
    as a colimit to the diagram $(F^n(K_0), F^n(f_0^+,f_0^-))=(K_n, (f_n^+,f_n^-))$ at the $\infty$-category $(CHPO)^{HPrj}$, where $K_\infty$ corresponds to c.h.p.o defined in \ref{Definition of K-infinity} and the h-embedding $f_{n,\infty}(x):=(f_{n,m}(x))_m$ (from $K_n$ to $K_\infty$) with $f_{n,m}$ equivalent to the composable h-embenddings if $n<m$, or to the composable h-projections if $n>m$, or to the identity if $n=m$, and the h-projection  $f_{\infty, n}(x):=x_n$ (from $K_\infty$ to $K_n$).

    \medskip Note that by Remark \ref{Example on CHPO}, the c.h.p.o $K_\infty$ is a fixed point of the functor $F: (CHPO)^{HPrj}\rightarrow (CHPO)^{HPrj}$, that is, $K_\infty\simeq [K_\infty\rightarrow K_\infty]$. Therefore, $K_\infty$ is a homotopy $\lambda$-model.
\end{rem}

\begin{prop}
    The $K_\infty$ chpo is a Homotopy Scott Domain. 
\end{prop}
    \begin{proof}
         First we will find that $K_\infty$ is algebraic. The compact elements of $K_\infty$ are of the form $(x_1,\ldots,x_n,\ldots,f^{+}_{n,m}(x_n),\ldots)$ for some $n\in\omega$ and for all $m>n$. For any $x\in K_\infty$, we define its finite approximations as compact elements $x^{(n)}:=(x_1,\ldots,x_n,\ldots,f^{+}_{n,m}(x_n),\ldots)$. The chain $\langle x^{(n)}\rangle_{n\in\omega}$ is directed and $\bigcurlyvee_nx^{(n)}\simeq x$, thus $K_\infty$ is an algebraic chpo. Now we will see that $K_\infty$ is bounded complete. Let $X\subseteq K_\infty$ with an upper bound $u$, then for each $n\in\omega$, the hpo $\langle x_n: x\in K_\infty \rangle\subseteq\hat{K}_n$ is an upper bound by $u_n\in K_n$. Since $K_n$ is bounded complete ($K_n$ is a Scott Dolmain by Remark \ref{Remark K_n is Scott Domain}), there exists the supremum $s_n=\bigcurlyvee\langle x_n: x\in K_\infty \rangle$. By the continuity of $f^{-}_{n-1}$, the sequence $(s_n)_n\in K_\infty$ and is the supremun of $X$, therefore $K_\infty$ is a Homotopy Scott Domain.      
    \end{proof}



\begin{prop}\label{Proposition supremum at K_infty}
    If $x\in K_\infty$, then $x \simeq \bigcurlyvee_n f_{n,\infty}(x_{n})$.
\end{prop}
\begin{proof}
We wish to show that for every $k\in\omega$, $(\bigcurlyvee_n f_{n,\infty}(x_{n}))_k\simeq x_k$. By definition and continuity of $f_{\infty,k}$, we have:
\begin{align*}
(\bigcurlyvee_n f_{n,\infty}(x_{n}))_k &= f_{\infty,k}(\bigcurlyvee_n f_{n,\infty}(x_{n}))\\
    &\simeq \bigcurlyvee_n f_{\infty,k}(f_{n,\infty}(x_{n})) \\
    &\simeq \bigcurlyvee_{n\geq k}f_{n,k}(x_{n}) \\
    &\simeq \bigcurlyvee_{n\geq k} x_{k}  \\
    &\simeq x_k
\end{align*} 
\end{proof}

\begin{prop}\label{Proposition equivalences h, k}
    If $h: [K_\infty\rightarrow K_\infty]\rightarrow K_\infty$ and $k: K_\infty\rightarrow [K_\infty\rightarrow K_\infty]$ are the equivalences resulting from applying the Theorem \ref{point-fixed-theorem} to the functor $F: (CHPO)^{HPrj}\rightarrow (CHPO)^{HPrj}$ of the Remark \ref{Example on CHPO}, then
    $$h(f)\simeq \bigcurlyvee_n f_{n+1,\infty}(f_{\infty, n}.f.f_{n, \infty}),\hspace{0.5cm} k(x)(y)\simeq\bigcurlyvee_n f_{n,\infty}(x_{n+1}(y_{n})).$$
\end{prop}
\begin{proof}
    We prove $(\lambda f.\bigcurlyvee_k f_{k+1,\infty}(f_{\infty, k}.f.f_{k, \infty})).F(f_{n,\infty})\simeq f_{n+1,\infty}$. We have that $F(f_{n,\infty})=\lambda g.(f_{n,\infty}.g.f_{\infty, n}):K_{n+1}\rightarrow F(K_\infty)$, hence
     \begin{align*}
&(\lambda f.\bigcurlyvee_k f_{k+1,\infty}(f_{\infty, k}.f.f_{k, \infty}))(F(f_{n,\infty})(g)) 
\\
&\simeq\bigcurlyvee_k f_{k+1,\infty}(f_{\infty, k}.F(f_{n,\infty})(g).f_{k, \infty})
\\
&\simeq \bigcurlyvee_{k>n} f_{k+1,\infty}(f_{\infty, k}.f_{n,\infty}.g.f_{\infty, n}.f_{k, \infty}) 
\\
&\simeq \bigcurlyvee_{k>n} f_{k+1,\infty}(f_{n,k}.g.f_{k, n}) 
\\
&\simeq \bigcurlyvee_{k>n} f_{k+1,\infty}(f_{n+1,k+1}(g))
\\
&\simeq \bigcurlyvee_{k>n} f_{n+1,\infty}(g)
\\
&\simeq f_{n+1,\infty}(g)
\end{align*}
 Since  $(K_\infty ,(f_{n,\infty}, f_{\infty, n})_n)$ is a colimit  to the $\omega$-diagram $(K_n,(f_n^+,f_n^-))$, there exists a unique  (under homotopy; the space of choices is contractible) $h: [K_\infty\rightarrow K_\infty]\rightarrow K_\infty$ such that $h.F(f_{n,\infty})\simeq f_{n+1,\infty}$, therefore $h(f)\simeq \bigcurlyvee_n f_{n+1,\infty}(f_{\infty, n}.f.f_{n, \infty})$.

 \bigskip On the other hand, by the same colimit, there exists an unique (under homotopy) $k:K_\infty\rightarrow [K_\infty\rightarrow K_\infty]$ such that $k.f_{n+1,\infty}\simeq F(f_{n,\infty})$, applying $f_{\infty, n+1}$ on both sides
\begin{align*}
 k.f_{n+1,\infty}.f_{\infty, n+1}&\simeq F(f_{n,\infty}).f_{\infty, n+1}
\\
& \simeq (\lambda g.(f_{n,\infty}.g.f_{\infty,n})).f_{\infty, n+1}; \,\, \text{by definition of} \,\, F(f_{n,\infty})
\\
 k(f_{n+1,\infty}(f_{\infty, n+1}(x))&\simeq(\lambda g.(f_{n,\infty}.g.f_{\infty,n}))(f_{\infty, n+1}(x))
\\
&\simeq f_{n,\infty}.f_{\infty, n+1}(x).f_{\infty,n}
\\
k(f_{n+1,\infty}(x_{n+1}))(y)&\simeq (f_{n,\infty}.x_{n+1}.f_{\infty,n})(y);\,\, \text{by definition of} \,\, f_{\infty, n+1}(x)
\\
&\simeq f_{n,\infty}(x_{n+1}(f_{\infty,n}(y)))
\\
&\simeq f_{n,\infty}(x_{n+1}(y_n));\,\, \text{by definition of} \,\, f_{\infty, n+1}(y)
\end{align*}
\begin{align*}
\bigcurlyvee_n k(f_{n+1,\infty}(x_{n+1}))(y)&\simeq \bigcurlyvee_n f_{n,\infty}(x_{n+1}(y_n))
\\
k(\bigcurlyvee_n f_{n+1,\infty}(x_{n+1}))(y)&\simeq \bigcurlyvee_n f_{n,\infty}(x_{n+1}(y_n))
\\
k(x)(y)&\simeq \bigcurlyvee_n f_{n,\infty}(x_{n+1}(y_n)); \,\, \text{since} \,\,  x \simeq \bigcurlyvee_n f_{n+1,\infty} (x_{n+1}) \,\ \text{by} \,\, \ref{Proposition supremum at K_infty}.
\end{align*}
\end{proof}

\begin{rem}[Application in $K_\infty$]
    For $x,y \in K_\infty$, by definition $x\bullet y = k(x)(y)$, by Proposition \ref{Proposition equivalences h, k} one has $$x\bullet y \simeq \bigcurlyvee_n f_{n,\infty}(x_{n+1}(y_n)).$$
\end{rem}

\begin{prop}
    The Kan complex $K_\infty$ is a non-trivial homotopy $\lambda$-model.
\end{prop}
\begin{proof}
    \begin{enumerate}
        \item  Since $\pi_0(K_0)$ is infinite and $f_{0,\infty}$ is an h-embedding, the map of connected components  $\pi_0(f_{0,\infty}):\pi_0(K_0)\rightarrow\pi_0(K_\infty)$ is injective, and hence $\pi_0(K_\infty)$ is infinite.
        \item Given $n\geq 1$, one has $\pi_n(K_0,x_0)=\pi_n (S^n,x_0)\ncong\ast$. By the h-embedding $f_{0,\infty}$, we have that the group homomorphism $\pi_n(f_{0,\infty}):\pi_n
        (K_0,x_0)\rightarrow\pi_n(K_\infty,f_{0,\infty}(x_0))$ is injective, thus $\pi_n (K_\infty,f_{0,\infty}(x_0))\ncong\ast$. 
        \item We find that $K_0=N^+$ is a non-trivial Kan complex. Let $x=(x_i)_i$ be a vertex of some non-degenerated horn in $K_\infty$. To prove that there exists an \( n>0 \) such that $\pi_n(K_\infty, x)\ncong\ast$, it is enough to prove that there is an \( i\geq 0\) such that $\pi_n(K_i, x_i)\ncong\ast$ for some $n>0$. Since $x_0$ is a vertex of a non-degenerated horn in $K_0$, there exists $n>0$ such that $x_0\in S^n$, hence $\pi_n(K_0,x_0)=\pi_n (S^n,x_0)\ncong\ast$.
    \end{enumerate}
\end{proof}

\begin{ejem}[Interpretation of $\beta\eta$-contractions in $K_\infty$]\label{Example beta eta contractions in K_infty}
    Given $a,b\in K_\infty$ such that $a=f_{0,\infty}(0)$ and $b=f_{0,\infty}(1)$. Let  $f=f_{0,\infty}(\langle 1,0\rangle')\in K_\infty(b,a)$ and  $g=f_{0,\infty}(\langle 0,1\rangle)\in K_\infty(a,b)$, where $\langle 1,0\rangle'$ and $ \langle 0,1\rangle$ are not inverses, and $0,1$ are vertices of the degenerated sphere $S^1\subseteq K_0$:
   \[\xymatrix{
		& 1\ar[d]_{\langle1,0\rangle'}\ar[dr]^{i}  \\
		&0 \ar[r]_{\langle 0,1\rangle} & 1 
	}\]
    If we define: $f_{0,1}(0):=f_{0,1}(1):=\lambda x. 1$ (note that $f_{0,n+1}(0)=f_{0,n+1}(1)=1_{n+1}:=\lambda x\in K_n.1_n$, with $1_0:=1$, and $f_{n+1,0}(1_{n+1})=1$), $h(f):=\bigcurlyvee_n f_{n+1,\infty}(f_{\infty, n}.f.f_{n, \infty})$ and $k(x)(y):=\bigcurlyvee_n f_{n,\infty}(x_{n+1}(y_{n}))$, we have
    \begin{align*}
            h(k(a))=&h(k(f_{0,\infty}(0))) \\
            = &\bigcurlyvee_n f_{n+1,\infty}(f_{\infty,n}.f_{n,\infty}.f_{0,n+1}(0).f_{\infty,n}.f_{n,\infty}) \\
            = &\bigcurlyvee_n f_{n+1,\infty}(f_{\infty,n}.f_{n,\infty}.f_{0,n+1}(0));\\
            &(\text{since: }f_{0,n+1} (0).f_{\infty,n}.f_{n,\infty}=1_{n+1}.f_{\infty,n}.f_{n,\infty}=1_{n+1})\\ = &\bigcurlyvee_n f_{n+1,\infty}(f_{\infty,n}.f_{n,\infty}.1_{n+1})\\
            =&\bigcurlyvee_n f_{n+1,\infty}(1_{n+1});\hspace{0.3cm} f_{m,n}(1_m)=1_n,\hspace{0.3cm}\text{for every $m,n\in \omega$} \\
            =&\bigcurlyvee_n f_{n+1,\infty}(f_{0,n+1}(1)) \\
            =&\bigcurlyvee_n f_{0,\infty}(1) \\
            =&f_{0,\infty}(1)=(1,1_1,1_2,\ldots,1_n,\ldots)=b \\
            \xleftarrow[\eta_a]{\neq} &f_{0,\infty}(0)=(0,1_1,1_2,\ldots,1_n,\ldots)=a.
     \end{align*}



    The $\lambda$-term $(\lambda z.xz)y$ has the $\beta\eta$-contractions 
	\[\xymatrix{
		& {(\lambda z.xz)y}\ar@/^2mm/[r]^{\,\,\,1\beta} \ar@/_2mm/[r]_{\,\,\,1\eta} & xy
	}\]

	Let $\rho(x)=a$ and $\rho(y)=b$ be vertices of $K_\infty$. The interpretation of a $\lambda$-term is given by: $\llbracket(\lambda z.xz)y \rrbracket_\rho=\llbracket\lambda z.xz \rrbracket_\rho\bullet b=h(\boldsymbol{\lambda} c.k(a)(c))\bullet b=h(k(a))\bullet b=k(h(k(a)))(b)$. Since $h(k(a))=b$, so the interpretation of the $\beta$-contraction in $K_\infty$ is given by
    $$b\bullet b=k(b)(b)=k(h(k(a)))(b)=(kh)(k(a))(b)\xrightarrow[]{\langle k(b)(b),k(a)(b)\rangle'} k(a)(b)=a\bullet b.$$
Thus,  $\varepsilon_{k(a)}:=\langle k(b),k(a)\rangle' = k(\langle b,a\rangle')=k(f_{0,\infty}\langle 1,0\rangle')$. On the other hand, the (reverse) $\eta$-contraction is modelled by 
$$a\bullet b=k(a)(b)\xrightarrow{\langle k(a)(b),k(b)(b)\rangle} k((hk)(a))(b)=k(h(k(a)))(b)=k(b)(b)=b\bullet b$$
Let  $k(\eta_{a}):=\langle k(a),k(b)\rangle = k(\langle a,b\rangle)=k(f_{0,\infty}\langle 0,1\rangle)$. Then, the degenerated sphere $k(f_{0,\infty}(S^1))(b)\subseteq K_\infty$ is given by
    \[\xymatrix{
		& (kh)(k(a))(b)\ar[d]_{(\varepsilon_{k(a)})_b}\ar[dr]^{i}  \\
		&k(a)(b)\ar[r]_{(k(\eta_a))_b} & k((hk)(a))(b) 
	}\]
Therefore,  $\llbracket 1\beta \rrbracket_\rho \ncong \llbracket 1\eta \rrbracket_\rho$ (no-equivalents) in $K_\infty$.  
\end{ejem} 

The Example \ref{Example beta eta contractions in K_infty},  indicates that there is no $2\beta\eta$-conversion from $1\beta$ to $1\eta$ in the Homotopy Type-Free Theory (HoTFT) defined in \cite{Martinez2HoDTvsHoTT21}. This shows that the higher $\beta\eta$-conversions system of HoTFT is not trivial.



\section{Conclusions and further work}


We generalise Dana Scott's $\lambda$-model  $D_\infty$ to a non-trivial homotopy $\lambda$-model $K_\infty$, corresponding to a complete weakly ordered Kan complex or complete homotopy partial order (chpo), with holes in higher dimensions to guarantee non-equivalence between interpretations of some higher conversions. For future work, we are developing an alternative type theory interpreted by chpo's (or Scott domains), whose induced types by the chpo's will be non-trivial unlike Martin-Löf's (or HoTT) types, where there is no difference between proofs of propositional equality \cite{Queiroz2016}.


