\section{Asynchronous QAB}
\label{sec:apx:async qab}

In this section, we provide a pseudocode for an asynchronous QAB algorithm. 

\begin{algorithm}[H]
\caption{Asynchronous QAB  Stage 1}
\begin{algorithmic}[1]
    \State \textbf{Roles:} Quorum Nodes, Relayers, Parties
    \State \begin{tabular}[t]{@{}ll}
          \textbf{Uses:} & Communication Graph Links $cgl$, \\
                        & For committee of relayer $r$: Aggregation Signatures $as_r$, \\
        \end{tabular}
    \State \textbf{Implements:} Asynchronous QAB

    \Statex

    \Upon{event}{qab.Initiate}{\vin} \Comment{On quorum node}
        \ForAll{$r \in $ relayers}
            \State $cgl.Send(\vin, r)$
        \EndFor
    \EndUpon

    \Upon{event}{cgl.Receive}{\vin, q} \Comment{On relayer}
        \If{$\mathrm{verify}(\vin)$}
            \State $decidedValue \gets \vin$
        \EndIf
    \EndUpon

    \UponTrue{$decidedValue \neq \bot$} \Comment{On relayer $r$}
        \ForAll{$p \in$ parties linked to $r$}
            \State $cgl.Send(\vin, p)$
        \EndFor
    \EndUpon


    \algstore{partial}
\end{algorithmic}
\end{algorithm}
\addtocounter{algorithm}{-1}

\begin{algorithm}[H]
\caption{Asynchronous QAB Stage 2}
\begin{algorithmic}[1]
\algrestore{partial}


\Upon{once per $r$}{cgl.Receive}{\vin, r} \Comment{On party $p$}
    \If{$\mathrm{verify}(\vin)$}
        \State $decidedValue \gets \vin$
        \State $\sigma_p \gets as_r.tsign_p(\vin)$
        \State $cgl.Send(\sigma_p, r)$
    \EndIf
\EndUpon

\UponTrue{received valid $\sigma_p$ from every party in its committee} \Comment{On relayer $r$}
    \State $committee_r \gets$ committee of $r$
    \State $Signatures \gets \bigcup\limits_{p \in committee_r}\sigma_p$
    \State $\Sigma_r \gets as_r.tcombine(\vin, Signatures)$
    \ForAll{$q \in$ quorum nodes}
        \State $cgl.Send(\Sigma_r, q)$
    \EndFor
\EndUpon



\algstore{stage2}
\end{algorithmic}
\end{algorithm}
\addtocounter{algorithm}{-1}

\begin{algorithm}[H]
\caption{Asynchronous QAB Stage 3}
\begin{algorithmic}[1]
\algrestore{stage2}

\Statex

\Upon{event}{$cgl.Receive$}{ \Sigma_r, r} \Comment{On quorum node}
    \State $committee_r \gets$ committee of $r$
    \If{$as_r.tverify(\vin, \Sigma_r)$}
        \State $AcknowledgedParties \gets AcknowledgedParties \cup committee_r$
    \EndIf
\EndUpon

\UponTrue{$|AcknowledgedParties| \geq n - 2t$} \Comment{On quorum node}
    \State $\Pi \gets$ set of all nodes
    \ForAll{$p \in \Pi \setminus AcknowledgedParties$}
        \State $cgl.Send(\vin, p)$
    \EndFor
\EndUpon

\Upon{event}{cgl.Receive}{\vin, q} \Comment{On party}
    \If{$\mathrm{verify}(\vin)$}
        \State $decidedValue \gets \vin$
    \EndIf
\EndUpon

\UponTrue{$decidedValue \neq \bot$} \Comment{On party}
    \State $qab.Decide(decidedValue)$
\EndUpon
\end{algorithmic}
\end{algorithm}

\section{Partially Synchronous Byzantine Agreement}
In this section, we give a pseudocode as well as formal proofs for out partially synchronous agreement algorithm.

\subsection{Pseudodcode}
\label{sec:apx:alg gst pseudocode}
This section provides a pseudocode for our partially synchronous byzantine agreement protocol.

In the protocol, for every message sent, we implicitly bundle along it the view number when it was sent. If a message is received by a party with a view number different than the current one, it is ignored. This prevents the adversary from using messages from previous views in case a party becomes leader multiple times. The only exception is the \textsc{SendCommit} message which is always accepted if the commit is valid.

\begin{algorithm}
\caption{Protocol run for the leader}

\begin{algorithmic}
    \Function{ViewLeaderProtocol}{}
        \Statex{$\triangleright$  Choose which value to propose}
        \State Broadcast \textsc{RequestSuggestion}
        \State Wait for valid \textsc{Suggest}(m) from $n-t$ parties
        \If{one of the value is a commit $C$ with value $v$:}
            \State $\textbf{value} \gets v$
            \State $\textbf{commit} \gets C$
            \State Jump to broadcasting the commit value
        \ElsIf{One of the value is a key value:}
            \State Let $key$ be the key the highest view number and $v$ its value
            \State $\textbf{value} \gets v$
            \State $\textbf{prop} = (KEY, key)$
        \Else
            \State Let $v$ be the most common proposed value among $0$ and $1$
            \State $\textbf{value} \gets v$
            \State Let $(\rho_p)$ be a set of $t+1$ partial signatures among parties which
             proposed $v$.
            \State $\textbf{prop} = (COMBINE, tcombine(\textbf{value}, (\rho_p)), view)$
        \EndIf

        \Statex{$\triangleright$  Approve the proposed value and get a key}
        \State Send \textsc{ProposeKey}($\textbf{value}, \textbf{prop}$) to every party.
        \State Wait for valid \textsc{CheckedKey}($\rho_p$) from $n-t$ parties
        \State $\textbf{key\_proof} \gets tcombine((KEY, \textbf{value}), (\rho_p))$

        \Statex{$\triangleright$ Approve the key and get a lock}
        \State Send \textsc{ProposeLock}($\textbf{value}, \textbf{key\_proof}$) to every party.
        \State Wait for valid \textsc{CheckedLock}($\rho_p$) from $n-t$ parties
        \State $\textbf{lock\_proof} \gets tcombine((LOCK, \textbf{value}), (\rho_p))$

        \Statex{$\triangleright$ Approve the lock and get a commit}
        \State Send \textsc{ProposeCommit}($\textbf{value}, \textbf{lock\_proof}$) to every party.
        \State Wait for valid \textsc{CheckedCommit}($\rho_p$) from $n-t$ parties
        \State $\textbf{commit\_proof} \gets tcombine((COMMIT, \textbf{value}), (\rho_p))$

        \Statex{$\triangleright$ Broadcast the commit value}
        \State Send \textsc{SendCommit}($\textbf{value}, \textbf{commit\_proof}$) to every party.
    \EndFunction
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{Protocol run for each party}

\begin{algorithmic}
    \Function{ViewPartyProtocol}{input value $v_{IN}$, view number $view$, \textbf{key}, \textbf{lock}, \textbf{commit}}
        \Statex{$\triangleright$  Early termination if we receive the commit value}
        \UponTrue{Receiving valid SendCommit($\textbf{value}, \textbf{commit}$)}
            \If{$\textbf{commit} = \bot$}
                \State $\textbf{commit} \gets (\textbf{value}, \textbf{leader\_commit})$
                \State Decide \textbf{value}
            \EndIf
        \EndUpon

        \Statex{$\triangleright$  Choose which value to propose}
        \State Wait for a message \textsc{RequestSuggestion} from the leader
        \If{$\textbf{commit} \neq \bot$}
            \If{This party never sent the commit value to the leader}
                \State Send \textsc{Suggest}($(COMMIT, \textbf{commit})$) to the leader
            \EndIf
            \State Wait for the rest of the view
        \ElsIf{$\textbf{key} \neq \bot$}
             \State Send \textsc{Suggest}($(KEY, \textbf{key})$) to the leader
        \Else
            \State $\rho \gets tsign(v_{IN})$
            \State Send \textsc{Suggest}($(INPUT, v_{in}, \rho)$) to the leader
        \EndIf


        \Statex{$\triangleright$  Check and sign the key}
        \State Wait for a valid \textsc{ProposeKey}($v$, ($type, proof$)) from the leader
        \If{$\textbf{lock} \ne \bot$}
            \If{$type = COMBINE$ or $type = KEY$ with a view number strictly less than the $\textbf{lock}$ view number}
                \State Wait for the rest of the view
            \EndIf
        \EndIf
        \State Send \textsc{CheckedKey}($tsign((KEY, v))$) to the leader

        \Statex{$\triangleright$  Check and sign the lock value}
        \State Wait for a valid \textsc{ProposeLock}($v$, $proof$) from the leader
        \State $\textbf{key} \gets (v, view, proof)$
        \State Send \textsc{CheckedLock}($tsign((LOCK, v))$) to the leader

        \Statex{$\triangleright$  Check and sign the commit value}
        \State Wait for a valid \textsc{ProposeCommit}($v$, $proof$) from the leader
        \State $\textbf{lock} \gets (v, view, proof)$
        \State Send \textsc{CheckedCommit}($tsign((COMMIT, v))$) to the leader
    \EndFunction
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{Protocol for Byzantine Agreement in partial synchrony}
\begin{algorithmic}
\Function{ByzantineAgreementGST}{input value $\vin$} % i have a \vin macro
\State $\textbf{key} \gets \bot$
\State $\textbf{lock} \gets \bot$
\State $\textbf{commit} \gets \bot$
\For{view number $view \gets 0,1, \ldots$}

    \If{This party is the current leader}
        \If{$\textbf{commit} = \bot$}
            \State Run ViewLeaderProtocol() in parallel for duration $9\Delta$
        \EndIf
    \EndIf
    \State Run ViewPartyProtocol($\vin$, $view$, \textbf{key}, \textbf{lock}, \textbf{commit}) for duration $9\Delta$
\EndFor
\EndFunction

\end{algorithmic}
\end{algorithm}

\subsection{Proofs}
\label{sec:apx:gst alg proofs}

We will prove the correctness and time complexity of the protocol with a series of lemmas:
\begin{lemma}
    During a view, only a single value can get key, lock or commit proofs.
\end{lemma}

\begin{proof}
    A key, lock or commit is a threshold signature signed by $n-t$ parties. Therefore, if two values $v_1$ and $v_2$ get a key, lock or commit proof, this means that $n-t$ parties signed each one, so at least $n-2t$ parties signed both of them. Because $t < n/3$, it implies that at least $t+1$ parties signed $v_1$ and $v_2$, so at least one honest party did, which implies that $v_1 = v_2$ because an honest party will only sign a single proof in a view.
\end{proof}

\begin{lemma}\label{lemma:gst-agreement}
    During an entire execution, at most one value will get commit proofs.
\end{lemma}


\begin{proof}
    If a value $v_1$ gets a commit proof during view $view_1$, this means that at least $n-t$ parties got a lock proof during this view. So a set $Q$ of $n-2t \geq t+1$ honest parties got a lock proof during this view. We will show that all subsequent key proofs generated will be for $v_1$, which implies that only lock proofs and then commit proofs can be generated for $v_1$ thereafter, as it requires a key proof for it. Assume by contradiction that a key proof for a different key $v_2 \ne v_1$ is generated and consider the first view $view_2 \geq view_1$  generating such a proof. We have $view_2 > view_1$ because of the previous lemma. If we got a key proof for $v_2$, it means $n-t$ parties signed it. Because $|Q| \geq t+1$, it means a party $p \in Q$ signed the key proof. By the minimality of $view_2$, $p$ still had the lock proof for $v_1$ at that point. Therefore, for $p$ to accept $v_2$, given that $v_2 \ne v_1$, this value must come with a key proof with view number $view_3 \geq view_1$. Therefore there is a key proof for $v_2$ at time $view_3$ with $view_1 \leq view_3 < view_2$. This contradicts the minimality of $view_2$, hence the result.
\end{proof}

Because we only decide on a value which gets a commit proof, this implies agreement. We now prove the validity of this protocol:
\begin{lemma}\label{lemma:gst-validity}
    If a value gets decided, then it satisfies strong unanimity.
\end{lemma}

\begin{proof}
    If a value $v$ gets decided, it means there is a commit proof for it, which in turn means there is a key proof for it. For a key proof to be valid, it must come either from:
    \begin{itemize}
        \item A previous lock proof, which comes from a previous key proof, we recursively look at this key proof until it does not come anymore from a lock proof and get to the second case.
        \item A ($t+1$)-threshold signature for the value $v$, this means that at least one honest party signed $v$ which according to the protocol indicates that its input value is $v$. Therefore it is valid to decide $v$ according to strong unanimity.
    \end{itemize}
\end{proof}

Finally, we can look at termination:
\begin{lemma} \label{lemma:gst-honest-commit}
    After GST, if a view start with a leader who is honest and does not have a commit proof, then at the end of the view, every honest party gets a commit proof.
\end{lemma}

\begin{proof}
    After GST, messages are received withing $\Delta$ times. This means that $n-t$ honest parties can always sign the value as long as it is valid, which will be the case if the leader is honest, and the condition for the key proof is passed. Because a view lasts $9 \Delta$ rounds, this is enough to make sure all messages get sent and received by honest parties before the view ends.

    If the leader receives at some point a valid \textsc{Suggest} message with a commit proof, then it will broadcast it to all parties which ends the proof in this case. Thus we can now assume the leader did not receive a \textsc{Suggest} message with a commit proof.

    Therefore, the only part left to prove is that all honest parties will sign the suggested value for the leader to get a key proof. Assume by contradiction that an honest party $p$ does not sign a suggested value. It means it has a lock proof and the suggested value has a $COMBINE$ type or comes from a lock proof with a strictly smaller view number. However, if a party has a lock proof for a value $v$ and a given view number $view$, this means that at least $n-t$ parties got a key proof for $v$ with view number $view$. So at least $n-2t \geq t+1$ honest parties had at some point a key proof for $v$ with view number $view$. Because the leader waits for $n-t$ parties, at least one of them $q$ sent his suggestion. Because a party's key proof can only be replaced by one with a higher view number, this means that the leader got a suggestion from $q$ with a view number at least $view$. Therefore, because the leader is honest, according to the protocol, it will suggest a value with a key proof at least $view$, so $p$ would have accepted it, hence the contradiction.
\end{proof}

\begin{corollary}
    For any $k \leq n-f$, at least $k$ honest parties are guaranteed to have decided within $k+f$ views after GST.
\end{corollary}

\begin{proof}
    %We consider an honest party $p$, During one of the $n$ views after GST, he will be a leader. Either it has already a commit proof and decided or according to the previous lemma it will send a commit proof and decide during this view, which concludes the proof.
    We consider the first $k + f$ views after $GST$, at least $k$ of them have a different honest leader. In each of this view, either the leader has already decided or using the previous lemma, every honest party will get a commit proof and decide, including the leader. Therefore all honest leaders within these $k+f$ views are guaranteed to decide by the end of them.
\end{proof}

\begin{corollary} \label{coro:gst-n-views}
    After at most $n$ views after GST, all honest parties have decided.
\end{corollary}

So this is a valid protocol for byzantine agreement. We now cover its message complexity.

\begin{lemma}\label{lemma:gst-complexity}
    This protocol has message complexity $\mathcal{O}(n + n\cdot f)$ after GST.
\end{lemma}

\begin{proof}
    We first remark that during a view, at most $\mathcal{O}(n)$ messages are sent by honest parties. Indeed, \textsc{ViewPartyProtocol} only sends at most $4$ messages to the leader for each party, and \textsc{ViewLeaderProtocol} only sends at most $5n$ messages to other parties. Therefore a view has message complexity $\mathcal{O}(n)$.

    We consider the total number of messages sent after GST. Because of the previous remark, at most $\mathcal{O}(n)$ messages are sent during the view in which GST occurs. We consider then the $n$ views following GST:
    \begin{itemize}
        \item At most $f$ of them have a byzantine leader, which leads to a $\mathcal{O}(n\cdot f)$ message complexity.
        \item At most one of them will have an honest leader with no commit proof. Indeed, if we have such a view, using lemma \ref{lemma:gst-honest-commit}, all honest parties will get a commit proof and therefore there won't be any honest party without a commit proof for the following view. This view has $\mathcal{O}(n)$ message complexity.
        \item The remaining views will have an honest leader with a commit proof. So it will not execute \textsc{ViewLeaderProtocol} and send no message has a leader. We remark that if a party receives no message from the leader, then it sends no message. As a consequence, no message will be sent by honest parties during these rounds.
    \end{itemize}
    Finally, we consider messages sent by honest parties after these $n$ rounds. Using corollary \ref{coro:gst-n-views}, all honest parties will have a commit proof, so no honest party will run \textsc{ViewLeaderProtocol}. So only byzantine parties will send messages as the leader. We remark in \textsc{ViewPartyProtocol}, that if an honest party has a commit proof and receives a \textsc{RequestSuggestion}, then it will only send the commit proof back, at most once for each party asking in the whole execution and do nothing else. Because only byzantine parties can be sending \textsc{RequestSuggestion} by then, in the worse case, this has total message complexity $f \cdot (n - f) = \mathcal{O}(n\cdot f)$.

    By summing all these messages, we get the expected upper bound of $\mathcal{O}(n + n\cdot f)$ for message complexity after GST.
\end{proof}

We can now prove the main theorem:
\GSTAlgoProp*

\begin{proof}
    This is a direct consequence of lemmas \ref{lemma:gst-agreement} (agreement), \ref{lemma:gst-validity} (validity), \ref{lemma:gst-honest-commit} (termination) and \ref{lemma:gst-complexity} (message complexity).
\end{proof}
