\begin{algorithm}
  \caption{First Come First Serve (FCFS) Scheduling}
  \label{algo:fcfs}
  \begin{algorithmic}[1]
    \State \textbf{Input:} JobQueue Q, MAX\_Node, MAX\_MEM
    \State \textbf{Output:} Schedule S
    \State Sort the Q based on arrival time
    \While{Q is not empty}
    \State job = Q.dequeue()
    \If{job.Node\_req $\le$ avail Node \textbf{and} job.mem\_req $\le$ avail\_mem}
    \State Schedule job for execution
    \State Update available resources: avail Node -= job.Node\_req, avail mem -= job.mem\_req
    \State Add job to S
    \Else
    \State Reject job
    \EndIf
    \EndWhile
    \Return S
  \end{algorithmic}
\end{algorithm}
\fi




