\begin{lemma}\label{lemma:leftmost-cbrt-n-moon}
    Let $n \in \RR_+$, ${\bf p} \in \RR^2$ and let $\Gamma$ be a vertical shear lattice.
    Then, the leftmost $\floor{\sqrt[3]n}$ vertical lines of ${\bf p}+\Gamma$ each contain a vertex
    of $\conv{H_{n,{\bf p}+\Gamma}}$.
\end{lemma}

\begin{proof}
    Let ${\bf q} = ({\bf q}_x, {\bf q}_y) \in {\bf p}+\Gamma$ be the bottommost lattice point above the hyperbola along a lattice vertical line. In particular,  $ {\bf q}_y <\frac{n}{{\bf q}_x} + 1$.
    We have that
    \[
        {\bf q}_x \le n^{1/3} \Rightarrow {\bf q}_x({\bf q}_x^2 - 1) < n \Rightarrow (n + {\bf q}_x)({\bf q}_x^2 - 1) < n {\bf q}_x^2.
    \]
    If ${\bf q}_x \le 1$ then it is clear that ${\bf q}$ is a vertex (there is no other lattice vertical line with $0<x<{\bf q}_x$), and otherwise the above equation gives
    \begin{equation*}
        {\bf q}_y < \frac{n}{{\bf q}_x} + 1 < \frac{n {\bf q}_x}{{\bf q}_x^2 - 1},
    \end{equation*}
    so Lemma~\ref{lemma:point_in_unit_moon_vertex} implies that ${\bf q}$ is a vertex.
\end{proof}



\begin{proof}[Proof of Proposition~\ref{prop:leftmost-vertical-lines-contain-vertex}]
    Without loss of generality, assume that $(1, 0)$ and $(0, 1)$ are primitive in $\Lambda$.
    Consider the linear transformation $f$ which dilates the $x$ axis by a
    factor of $\tfrac1{\det \Lambda}$, 
    which maps $\Lambda$ to a vertical shear lattice $\Gamma$.
    It also maps the hyperbola $\left\{xy = n\right\}$ to a hyperbola $\left\{xy = n'\right\}$ with
    $n' \coloneqq \tfrac{n}{\det \Lambda}$, and it sends ${\bf p}$ to a certain point ${\bf p}'$.

    It follows from Lemma~\ref{lemma:leftmost-cbrt-n-moon} that the leftmost
    $\floor{\sqrt[3]{n'}}$ vertical lines of ${\bf p}'+\Gamma$ in the first quadrant,
    which are the image by $f$ of the leftmost $\floor{\sqrt[3]{n'}}$ vertical lines
    of ${\bf p}+\Lambda$, each contain a vertex of $\conv{H_{n',{\bf p}'+\Gamma}}$, image
    of $\conv{H_{n,{\bf p}+\Lambda}}$.
    %
    With the same argument with a dilation in the $y$ axis, we conclude that
    the bottommost $\floor{\sqrt[3]{n'}}$ horizontal  lines of ${\bf p}+\Lambda$
    each contain a vertex of $\conv{H_{n,{\bf p}+\Lambda}}$.

    This gives a priori
    \[
        2\floor{\sqrt[3]{n'}} = 2\floor{\left(\frac{n}{\det \Lambda}\right)^{\frac13}} \ge 2\left(\frac{n}{\det \Lambda}\right)^{\frac13} - 2
    \]
    vertices, except we need to check that the ones obtained with horizontal and vertical lines are all different.
    If one vertex comes simultaneously from a vertical and horizontal line then $(\sqrt[3]{n'} \det \Lambda)^2 \ge n$, and we have that
    \[
        (\sqrt[3]{n'}\det \Lambda)^2 \ge n
        \quad\Leftrightarrow\quad
        n^{2/3}(\det \Lambda)^{4/3} \ge n
        \quad\Rightarrow\quad
        n \le (\det \Lambda)^4 \le \det \Lambda.
    \]
    Assuming that this does not happen is no loss of generality since $n \le \det \Lambda$ implies our lower bound to be zero.
\end{proof}
