\end{proof}

Our algorithms use a specific basis of any lattice $\Lambda\subset \QQ^2$ that we call standard:
\begin{definition}
    \label{def:standard_basis}
    Let $\Lambda \subset \QQ^2$ be a rational lattice.
    The \emph{standard basis} of $\Lambda$ is the unique basis ${\bf b}_1 = ({{\bf b}_1}_x, {{\bf b}_1}_y)$, ${\bf b}_2 = (0, {{\bf b}_2}_y)$ satisfying
    \begin{equation}
        \label{eq:basis}
        {{\bf b}_1}_x > 0, \quad {{\bf b}_2}_y > 0, \quad 0 \le {{\bf b}_1}_y < {{\bf b}_2}_y.
    \end{equation}
\end{definition}

The standard basis of a  reduced lattice $\Lambda$ has the form ${\bf b}_1 = (1, {{\bf b}_1}_y)$, ${\bf b}_2 = (0, \det \Lambda)$, with ${{\bf b}_1}_y \in \{0,\dots, \det \Lambda -1\}$. More generally:

\begin{proposition}
    \label{prop:standard_basis}
    The standard basis exists and is unique for every rational lattice $\Lambda\subset \QQ^2$.
    It can be computed from an arbitrary basis of $\Lambda$ in time linear on the bit size of that basis. If $\Lambda\subset \ZZ^2$, its coordinates are bounded by $\det(\Lambda)$.
\end{proposition}

\begin{proof}
    Existence and uniqueness follows from the following description:
    \begin{align*}
        {{\bf b}_1}_x &= \min\{x > 0: (x, y) \in \Lambda \text{ for some $y$}\}, \\
        {{\bf b}_2}_y &= \min\{y > 0: (0, y) \in \Lambda\}, \\
        {{\bf b}_1}_y &= {\bf b}_y \bmod {{\bf b}_2}_y,
    \end{align*}
    where ${\bf b}_y \in \QQ$ is any number such that $({{\bf b}_1}_x, {\bf b}_y) \in \Lambda$ and, for two rational numbers $p, q$ we denote
    \[
        p \bmod q \coloneqq \ceil{p/q}q - p.
    \]

    These three numbers can be computed from an arbitrary basis ${\bf w}_1, {\bf w}_2$ of $\Lambda$ as follows:
    \begin{align*}
        {{\bf b}_1}_x &= \gcd({{\bf w}_1}_x, {{\bf w}_2}_x), \\
        {{\bf b}_2}_y &= \det(\Lambda)/{{\bf b}_1}_x,\\
        {{\bf b}_1}_y &= (s\cdot{{\bf w}_1}_y + t\cdot{{\bf w}_2}_y) \bmod {{\bf b}_2}_y,\quad \text{ where }{{\bf b}_1}_x = s\cdot{{\bf w}_1}_x + t\cdot{{\bf w}_2}_x.
    \end{align*}
    (That is, $s$ and $t$ are the Bezout coefficients obtained from the extended Euclidean algorithm in the computation of $\gcd({{\bf w}_1}_x, {{\bf w}_2}_x)$).

    The complexity of this computation is dominated by the $\gcd$; hence, in the arithmetic model, it is linear in the bit size of the input basis. The size of the coordinates follows from the fact that $\det(\Lambda) = {{\bf b}_1}_x {{\bf b}_2}_y$ and ${{\bf b}_1}_y < {{\bf b}_2}_y$.
\end{proof}

\subsection{The algorithms}\label{subsec:putting-things-together}

Via the transformations from the previous section, in this section we assume without loss of generality that we are given an $n>0$, ${\bf p} \in H_n$ and the standard basis $({\bf b}_1, {\bf b}_2)$ of a rational lattice $\Lambda\subset \ZZ^2$.
We want to compute the vertices of $\conv{H_{n,{\bf p}+\Lambda}}$.
In some of the statements (typically those related to complexity bounds) we need to assume that $\Lambda$ is a reduced sublattice of $\ZZ^2$. 

\subsubsection{Finding the first vertex}

The following result tells us how to find the vertex with the smallest $x$-coordinate.

\begin{proposition}
\label{prop:first_vertex}
Let ${\bf p} \in H_n$ and let $\Lambda\subset \QQ^2$ be a rational lattice.
Having a standard basis of $\Lambda$, the first vertex of $\conv{H_{n,{\bf p} + \Lambda}}$ can be computed in $O(1)$ arithmetic operations.
\end{proposition}

\begin{proof}
    The first vertical line of ${\bf p}+\Lambda$ intersecting the positive open quadrant has
    $x$-coordinate congruent to ${\bf p}_x$ modulo ${{\bf b}_1}_x$. Hence, one of its lattice points is
    \[
        {\bf q} \coloneqq {\bf p} - \floor{\frac{{\bf p}_x - 1}{{{\bf b}_1}_x}} {\bf b}_1.
    \]
    The first vertex of $\conv{H_n,{\bf p} + \Lambda}$ is just the bottommost point of $H_{n,{\bf p}+\Lambda}$ along that line, which equals
    \[
        {\bf q} + \ceil{\frac{n/{\bf q}_x - {\bf q}_y}{{{\bf b}_2}_y}} {\bf b}_2. \qedhere
    \]
\end{proof}



\subsubsection{Finding the next vertex}

To find the next vertex of a given vertex we introduce the following concepts.

\begin{definition}
    Let ${\bf p} \in  H_n$ and let $\Lambda \subseteq \QQ^2$ be a
    rational lattice.
    We denote by $\Minsl({\bf p})$ the primitive non-zero vector
    with the smallest slope in
    \[
        (H_{n,{\bf p}+\Lambda} - {\bf p}) \cap \left\{(x, y): x \ge 0\right\} \subset \Lambda,
    \]
    and by
    $\Nextpt({\bf p})$ the furthest point of $H_{n,{\bf p}+\Lambda}$ along the ray from ${\bf p}$ in that direction; that is,
    \begin{align*}
        &\Nextpt({\bf p}) \coloneqq
            {\bf p} + k\cdot\Minsl({\bf p}),
            \qquad \text{ where}\\
        &\,k = \max{\{j \in \ZZ: {\bf p} + j\cdot\Minsl({\bf p}) \in H_n\}} \ge 1,
    \end{align*}
    If $ k = \infty$ we take $\Nextpt({\bf p}) ={\bf \infty}$.
\end{definition}


\begin{remark}
    Let ${\bf b}_1 = ({{\bf b}_1}_x, {{\bf b}_1}_y), {\bf b}_2 = (0, {{\bf b}_2}_y)$ be the standard basis of a rational lattice $\Lambda$, and  ${\bf p}= ({\bf p}_x, {\bf p}_y) \in H_n$.
    \begin{itemize}
        \item If ${\bf p} - {\bf b}_2 \in H_n$ (equivalently, if ${\bf p}_y \ge n/{\bf p}_x + {{\bf b}_2}_y$) then $\Minsl({\bf p}) = -{\bf b}_2$ and
        $\Nextpt({\bf p})$ is the bottommost lattice point of $H_{n,{\bf p}+\Lambda}$ in the vertical line containing ${\bf p}$.
        Put differently,
        \[
            \Nextpt({\bf p}) = {\bf p} + \ceil{\frac{n/{\bf p}_x- {\bf p}_y }{{{\bf b}_2}_y}} {\bf b}_2.
        \]
        Moreover, $\Nextpt({\bf p})$ is the first vertex of $\conv{H_{n,{\bf p}+\Lambda} \cap\{x \ge {\bf p}_x\}}$.

        \item If ${\bf p} - {\bf b}_2 \notin H_n$ (equivalently, if $n/{\bf p}_x \le {\bf p}_y < n/{\bf p}_x + {{\bf b}_2}_y$) then ${\bf p}$ is the first vertex of
        $
            \conv{H_{n,{\bf p}+\Lambda} \cap\{x \ge {\bf p}_x\}}
        $
        and
        $\Nextpt({\bf p})$ is the next one (or $\infty$, if there is no vertex after ${\bf p}$).
%        \item
%        \pacoS{We do not need this case anymore, do we?}
%        If ${\bf p}_y < n/{\bf p}_x$, that is, when ${\bf p} \notin H_n$, $\Minsl({\bf p})$ is still well-defined and it equals the vertex of
%        $\conv{H_{n,{\bf p}+\Lambda}}$ most to the right that is visible from ${\bf p}$.
%% In this case, computing $\Nextpt({\bf p})$ knowing $\Minsl({\bf p})$
%% may be done lattice ray casts.
    \end{itemize}
\end{remark}

Hence:

\begin{corollary}
\label{cor:nextpt_is_next_vertex}
    If ${\bf p}$ is a vertex of $\conv{H_{n,{\bf p}+\Lambda}}$ then $\Nextpt({\bf p})$ is the next one.
    \qed
\end{corollary}

To analyze the complexity of our main algorithm we need the following:

\begin{lemma}
\label{lemma:exception}
    Let $\Lambda\subset \ZZ^2$ be a reduced lattice and let
     ${\bf p} \in H_n$.
     \begin{enumerate}
     \item If ${\bf p}_y\in (1,2)$ then $\Nextpt({\bf p})$ can be computed from the standard basis of $\Lambda$ in $O(\log \det \Lambda)$ operations.
     \item If ${\bf p}_y\notin (1,2)$ then the $x$ coordinate of $\Minsl({\bf p})$ is bounded above by $2n+2\det(\Lambda)$.
     \end{enumerate}
\end{lemma}

\begin{proof}
    We assume $\Nextpt({\bf p})\ne \infty$ (equivalently, ${\bf p}_y > 1$), since otherwise $\Minsl({\bf p}) = (\det(\Lambda), 0)$. Let ${\bf q} = \Nextpt({\bf p}) $.
    Observe that ${\bf q}$ is the first lattice point in the horizontal half-line $\{y={\bf q}_y\} \cap \{x \ge \max({\bf p}_x, n/ {\bf q}_y)\}$.
    In particular, ${\bf q}_x$ is bounded above by $\max\{{\bf p}_x, n/ {\bf q}_y\} + \det \Lambda$ and the $x$-coordinate of $\Minsl({\bf p})$ is bounded by
    \begin{align}
    \label{eq:nextpt_x}
    {\bf q}_x - {\bf p}_x \le \max\{0, n/ {\bf q}_y-{\bf p}_x\} + \det \Lambda.
    \end{align}


    If $1 < {\bf p}_y < 2$ we clearly have ${\bf q}_y = {\bf p}_y - 1$ and the observation above allows us to compute ${\bf q}_x$ as follows:
    Let ${\bf q}'$ be the last vertex of $\conv{H_{n,{\bf p} +\Lambda}}$, which is the point in ${\bf p} + \Lambda$ with ${\bf q}'_y = {\bf p}_y -1$ with the minimum $x$-coordinate beyond $n/{\bf q}'_y$.
    Take:
    \begin{align*}
    \label{eq:last_vertex}
    {\bf q} = {\bf q}' + \ceil{ \frac{ \max({\bf p}_x - {\bf q}'_x, 0)}{\det \Lambda} }  (\det \Lambda,0).
    \end{align*}
    To find ${\bf q}'$ we first need to compute the standard basis of the reflected lattice $\Lambda'\coloneqq\{(y,x): (x,y)\in \Lambda\}$, which takes $O(\log \det \Lambda)$ operations.
    After that, we can apply Proposition~\ref{prop:first_vertex} with the $x$ and $y$ coordinates swapped, which takes $O(1)$ operations more.

    For the second part of the statement we assume ${\bf q}_x - {\bf p}_x > 2n+2\det \Lambda$. Let us denote $\fra( {\bf p}_y) \coloneqq  {\bf p}_y - \floor{{\bf p}_y}$ and let ${\bf p}' \in {\bf p} + \Lambda$ be the first lattice point with ${\bf p}'_y=  \fra({\bf p}_y)+1$ and
    $
    {\bf p}'_x \ge \max \{ {\bf p}_x, n/{\bf p}_y'\}.
    $
    Our claim is that in fact ${\bf p}' = {\bf p}$, which implies the statement since then
    \[
    {\bf p}_y =  {\bf p}'_y  = \fra({\bf p}_y)+1 <2.
    \]

    We prove the claim by contradiction, so suppose ${\bf p}' \ne {\bf p}$.
    By construction of ${\bf p}' $ we have that ${\bf p}' \in H_{n, {\bf p} + \Lambda} \cap \{x \ge {\bf p}_x\}$, so the slope of ${\bf q}- {\bf p}$ should be less than (or equal to) the slope of ${\bf p}'- {\bf p}$.
    Equivalently, since ${\bf q}_y < {\bf p}'_y < {\bf p}_y$, the slope of ${\bf q} - {\bf p}'$ is less than (or equal to) the slope of ${\bf p}' - {\bf p}$.
    The same argument that proved Eq.~\eqref{eq:nextpt_x}, applied to ${\bf p}'$ instead of ${\bf q}$, implies that 
    \[
        {\bf p}'_x - {\bf p}_x \le \det \Lambda + \max\{0, n/ {\bf p}'_y-{\bf p}_x\} \le  n + \det \Lambda,
    \]
    and from this we get
    \[
        {\bf q}_x - {\bf p}'_x  = ({\bf q}_x - {\bf p}_x) - ({\bf p}'_x - {\bf p}_x) > (2n+2\det\Lambda) - (n + \det \Lambda) = n + \det \Lambda.
    \]
    On the other hand, assuming ${\bf p}' \ne {\bf p}$ we have
    \begin{align*}
    {\bf p}_y - {\bf p}'_y \ge 1,
    \qquad \text{ and } \qquad
    {\bf p}'_y - {\bf q}_y =  1.
    \end{align*}
    These four equations imply
    \[
    \slope{{\bf q}- {\bf p}'} > \frac1{n+\det\Lambda} \ge \slope{{\bf p}'- {\bf p}},
    \]
    a contradiction.
\end{proof}

We can now state our main algorithmic result, computing $\Nextpt({\bf p})$ in logarithmic time.
Its (long) proof is deferred to Section~\ref{subsec:rsmin}.


\begin{theorem}
    \label{thm:exists_find_nextpt}
    \label{thm:exists_find_next_vertex}
    Let $\Lambda \subset \QQ^2$ be a rational lattice.
    Given an $n  > 0$, a point ${\bf p} \in  H_n$, and the standard basis  ${\bf b}_1, {\bf b}_2$ of $\Lambda$, Algorithm~\ref{alg:compute_nextpt} (described in the next section) computes $\textmono{nextpt}({\bf b}_1, {\bf b}_2, n, {\bf p})\coloneqq\Nextpt({\bf p})$.

    If $\Lambda$ is a reduced sublattice of $\ZZ^2$, the number of operations taken by the algorithm is in $O(\log (n+\det \Lambda))$  except (perhaps) if ${\bf p}_y \in (1,2)$.
\end{theorem}


We can now prove Theorem~\ref{thm:general_algorithm}.

\begin{proof}[Proof of Theorem~\ref{thm:general_algorithm}]
We first apply Lemma~\ref{lemma:transform_sublattice} to find an affine transformation sending our original hyperbola $h$ to the standard hyperbola $\{xy = \abs{n}\}$, the starting vertex to a point ${\bf p}\coloneq ({\bf p}_y,{\bf p}_x) \in \RR^2$ and the integer lattice to a reduced lattice $\Lambda\subset \QQ^2$, of determinant $\Delta$. This step takes $O(\log (\max\{\abs{a}, \abs{b}, \abs{c}\}))$ operations and provides a basis of $\Lambda$ with coordinates bounded by $\max\{\abs{a}, \abs{b}, \abs{c} \}$, so the standard basis of $\Lambda$ can also be computed in the same number of operations.

We then apply Theorem~\ref{thm:exists_find_nextpt}, which allows us to compute the next vertex in time $O(\log(\abs{n}+\Delta))$. This is in $O(\log (\max\{\abs{n}, \abs{a}, \abs{b}, \abs{c}\}))$ since
\[
\abs{n}+\Delta  \le \abs{n} + 3 \max\{\abs{a}, \abs{b}, \abs{c}\} \le 4 \max\{\abs{n}, \abs{a}, \abs{b}, \abs{c}\}.
\]

We have to deal with the exceptional case of Theorem~\ref{thm:exists_find_nextpt}, namely the case ${\bf p}_y \in (1,2)$. If this happens we apply Lemma~\ref{lemma:exception} instead, to find the next (and last) vertex in the slightly better number $O(\log (\Delta)) \le O(\log(\max\{\abs{a}, \abs{b}, \abs{c}\}))$ of operations .
\end{proof}





\subsubsection{Computing all vertices}


Let us now show  how to compute the convex hull
of $H_{n,{\bf p}+\Lambda}$ for any ${\bf p} \in \RR^2$ and reduced sublattice $\Lambda \subseteq \ZZ^2$, using the function $\textmono{nextpt}$.

\begin{corollary}
    \label{corollary:exists_hyperbola_convex_hull_alg}
    Given a standard basis $({\bf b}_1, {\bf b}_2)$ of a reduced lattice $\Lambda \subseteq \ZZ^2$, an $n >0$ and a ${\bf p} \in \RR^2$,
    Algorithm~\ref{alg:hyperbola_convex_hull} computes $\conv{H_{n,{\bf p}+\Lambda}}$ with time
    complexity in
    \[
        O\big( N\log(n+\det \Lambda)\big),
    \]
    where $N=\cardinal{\vertices{\conv{H_{n,{\bf p}+\Lambda}}}}$.
\end{corollary}

\begin{algorithm}
    \caption{Compute $\conv{H_{n,{\bf p}+\Lambda}}$.}
    \label{alg:hyperbola_convex_hull}

    \DontPrintSemicolon
    \SetKwInOut{Input}{Input}
    \SetKwInOut{Output}{Output}

    \Input{$n >0, {\bf p} \in \RR^2, \Lambda = \left\langle{\bf w}_1, {\bf w}_2\right\rangle \subseteq \QQ^2$, with~${\bf w}_1,~{\bf w}_2$~linearly~independent}
    \Output{$\textmono{hull} = \vertices{\conv{H_{n,{\bf p}+\Lambda}}}$}

    \SetKw{And}{and}

    \SetKwProg{Fn}{Function}{}{end}
    \Fn{\textmono{convex\_hull\_H\_n(}${\bf w}_1, {\bf w}_2\typeHint{\in \NonZero\Lambda}, n\typeHint{ >0}, {\bf p}\typeHint{\in \RR^2}$\textmono{)}} {
        ${\bf b}_1, {\bf b}_2\typeHint{\in \NonZero\Lambda} \gets \textmono{standard\_basis(}{\bf w}_1, {\bf w}_2\textmono{)}$\;
        ${\bf q}\typeHint{\in {\bf p}+\Lambda} \gets {\bf p} - \ceil{\frac{{\bf p}_x - 1}{{{\bf b}_1}_x}} {\bf b}_1$\;
%        \uIf {${\bf q} \in H_n$} {${\bf q} \gets {\bf q} - \raycast(H_n,\,{\bf q},\,-{\bf b}_2)\cdot{\bf b}_2$}
%        \lElse
        ${\bf q} \gets {\bf q} + \ceil{\frac{n/{\bf q}_x - {\bf q}_y}{{{\bf b}_2}_y}} {\bf b}_2$\;
%       {\bf q} + (\raycast(H_n,\,{\bf q},\,{\bf b}_2) + 1)\cdot{\bf b}_2$}
        $\textmono{hull} \typeHint{\subseteq {\bf p}+\Lambda} \gets \{{\bf q}\}$\;

        \While {${\bf q}_y \ge 2$ \And $\textmono{nextpt(}{\bf b}_1,\,{\bf b}_2,\,n,\,{\bf q}\textmono{)} \ne \infty$} {
            ${\bf q} \gets \textmono{nextpt(}{\bf b}_1,\,{\bf b}_2,\,n,\,{\bf q}\textmono{)}$\;\label{line:nextpt}
            $\textmono{hull} \gets \textmono{hull} \cup \left\{{\bf q}\right\}$\;
            \label{line:union}
        }
        \If {${\bf q}_y \in (1,2)$} {
            ${\bf q} \gets ({\bf q}_y, {\bf q}_x)$\;
            ${\bf b}_1', {\bf b}_2'\typeHint{\in \NonZero\Lambda} \gets \textmono{standard\_basis(}({{\bf w}_1}_y, {{\bf w}_1}_x),({{\bf w}_2}_y, {{\bf w}_2}_x)\textmono{)}$\;
            ${\bf q}'\typeHint{\in {\bf p}+\Lambda} \gets {\bf q} - {{\bf b}_1'}$\;
            ${\bf q}' \gets {\bf q}' + \ceil{\frac{n/{\bf q}'_x - {\bf q}'_y}{{{\bf b}_2'}_y}} {{\bf b}_2'}$\;
%            ${\bf q}' \gets {\bf q}' + \ceil{\frac{\max({\bf q}_y - {\bf q}'_y, 0)}{{{\bf b}_2'}_y}} {{\bf b}_2'}$\;\label{line:q'}
            ${\bf q} \gets ({\bf q}'_y, {\bf q}'_x)$\;
            $\textmono{hull} \gets \textmono{hull} \cup \left\{{\bf q}\right\}$\;
            \label{line:union_2}
        }
        \Return $\textmono{hull}$\;
    }
\end{algorithm}

\begin{proof}
    Algorithm~\ref{alg:hyperbola_convex_hull} first computes the leftmost vertex of $\conv{H_{n,{\bf p}+\Lambda}}$
    as described in Proposition~\ref{prop:first_vertex}, and inserts it in $\textmono{hull}$. This part has complexity $O(1)$,
    since we are given a standard basis.
    Then it iterates $\textmono{nextpt}({\bf b}_1,{\bf b}_2, n, {\bf q})$ which, by Corollary~\ref{cor:nextpt_is_next_vertex} and Theorem~\ref{thm:exists_find_nextpt}, returns the subsequent vertices each in time $O(\log(n+\det \Lambda))$.
    This goes on until the rightmost vertex, for which $\Nextpt$ equals $\infty$,  is reached, with one exception: if we arrive at a vertex ${\bf q}$ with ${\bf q}_y\in (1,2)$ then we apply Lemma~\ref{lemma:exception}: we directly compute the last vertex of $\conv{H_{n,{\bf p} + \Lambda}}$ exactly as the first vertex was computed, but swapping the coordinates $x$ and $y$.

    Although $\textmono{hull}$ in the algorithm is formally a set the elements
    added to it are always new, so the union is really an insertion, taking constant time.
\end{proof}

\subsubsection{Starting at an intermediate point}

If we are given a value $x_{start}\in \RR_{>0}$, we can easily find the first vertex ${\bf q}$ of $\conv{H_{n,{\bf p} + \Lambda} \cap \{x\ge x_{start}\}}$ in $O(1)$ time, by a slight modification of the proof of Proposition~\ref{prop:first_vertex}.
However, such ${\bf q}$ may not be a vertex of $\conv{H_{n,{\bf p} + \Lambda}}$.
We now show that the first vertex of $\conv{H_{n,{\bf p} + \Lambda}}$ lying in $\{x\ge x_{start}\}$ can be found with a logarithmic number of iterations of  the same function $\textmono{nextpt}$ used in Algorithm~\ref{alg:hyperbola_convex_hull}.




\begin{proposition}
    \label{prop:find_next_vertex_from_non_vertex}
    Let ${\bf p} \in H_n$ be a point in the interior of $\conv{H_{n,{\bf p}+\Lambda}}$.
    Let $e_{\bf p}$ be the edge of $\conv{H_{n,{\bf p}+\Lambda}}$ vertically below
    ${\bf p}$ and let ${\bf v}$ be the right end-point of $e_{\bf p}$ (we admit ${\bf v}=\infty$).

    If ${\bf q} \coloneqq \Nextpt({\bf p}) \ne \infty$ then
    $\operatorname{dist}({\bf q}, e_{\bf p}) < \tfrac12 \operatorname{dist}({\bf p}, e_{\bf p})$
    and ${\bf q}_x \le {\bf v}_x$.
\end{proposition}

\begin{proof}
    By definition of ${\bf q} \coloneqq \Nextpt({\bf p})$, the slope of ${\bf q} - {\bf p}$ is smaller or equal than the slope of $e_{\bf p}$, that is, the slope of ${\bf v} - {\bf p}$. (This holds even if ${\bf v}=\infty$, in which case we consider the slope of ${\bf v} - {\bf p}$ to be zero).
    Hence, the ray ${\bf p} + \RR_{\ge 0}({\bf q} - {\bf p})$ intersects $e_{\bf p}$;  it must do so after passing through ${\bf q}$ because ${\bf q} \in \conv{H_{n,{\bf p}+\Lambda}}$.
    Since ${\bf v}$ is the right end-point of $e_{\bf p}$, we have ${\bf p}_x \le {\bf q}_x \le {\bf v}_x$.

    Now assume, to seek a contradiction, that $\operatorname{dist}({\bf q}, e_{\bf p}) \ge \tfrac12 \operatorname{dist}({\bf p}, e_{\bf p})$.
    This implies that
    ${\bf q}' \coloneqq {\bf p} + 2({\bf q} - {\bf p})$ is also on or above $e_{\bf p}$ and thus is in
    $H_{n,{\bf p}+\Lambda}$, further from ${\bf p}$ in the same direction as ${\bf q}$, in contradiction
    with the definition of ${\bf q}$.
    This situation is illustrated in Figure~\ref{fig:prop:nextpt-from-non-vertex}.
\end{proof}

\begin{figure}[htb]
    \includegraphics[width=.7\textwidth]{figures/prop-rsmin-from-non-vertex}
    \caption{Case where $\nextpt_{\ZZ^2,H_n}$ is not the next vertex.}
    \label{fig:prop:nextpt-from-non-vertex}
\end{figure}

\begin{corollary}
    \label{cor:find_next_vertex_from_non_vertex_log}
Let $\Lambda\subset \ZZ^2$ be a reduced sublattice, let $n > 0$, and let ${\bf p} \in H_n$  a point with $\Nextpt({\bf p}) < \infty$.
    Let ${\bf v}$ be the leftmost vertex of
    \[
        \vertices{H_{n,{\bf p}+\Lambda}} \cap \{x > {\bf p}_x\},
    \]
    (possibly ${\bf v} = \infty$).
%
    Then, ${\bf v}$ is reached in at most $\log_2(n +\det \Lambda)$ iterative calls to $\textmono{nextpt}$ starting at ${\bf p}$.
\end{corollary}

\begin{proof}
    Let $e$ be the edge vertically
    below ${\bf p}$, so that ${\bf v}$ is its rightmost endpoint.
    If ${\bf p} - {\bf b}_2 \in H_n$ then ${\bf q} \coloneqq \Nextpt({\bf p})$ is in the same vertical line as ${\bf p}$ and has
    ${\bf q} - {\bf b}_2 \notin H_n$. Hence, we can assume without loss of generality that ${\bf p} - {\bf b}_2 \notin H_n$. That is, the vertical distance between ${\bf p}$ and $e$ is bounded by ${{\bf b}_2}_y \le \det(\Lambda)$.

    Let $x_e$ denote the $x$-coordinate of a primitive vector of $\Lambda$ parallel to $e$. Since $\Lambda$ is primitive, we have that $x_e =\det \Lambda$ if ${\bf v}=\infty$ and $0 < x_e \le {\bf v}_x < n+\det \Lambda$  if ${\bf v}$ is finite. The  vertical Euclidean distance between consecutive lattice lines parallel to $e$ equals $\det \Lambda/x_e$. As the distance between our point and $e$ is initially bounded by $\det \Lambda$ and is at least halved in each iteration, it will become smaller than the minimum possible vertical distance in
    \[
        \log_2 \frac{\det \Lambda}{\det \Lambda/x_e} = \log_2 (x_e) \le  \log_2(n+\det \Lambda)
    \]
    iterations. When this happens we must have reached a point ${\bf p}^* \in e$ and, if ${\bf p}^*\ne {\bf v}$, the next call to $\textmono{nextpt}$ finds ${\bf v}$. 
\end{proof}
