\subsection{Proof of Theorem~\ref{thm:exists_find_nextpt}}
\label{subsec:rsmin}

\subsubsection{Casting rays at the hyperbola}
\label{subsubsec:cast}

One primitive that our algorithm repeatedly uses is to
find the farthest lattice point along a ray before crossing $h_n$. Here we show that this takes constant time.

\begin{lemma}
    \label{lemma:quadratic_formula}
    Let $a, b, c \in \RR$.
    There exists an algorithm which performs only $O(1)$ basic integer arithmetic (including
    at most one integer square root) to decide whether the quadratic equation
    $ax^2 + bx + c$ has zero, one, or two real roots, and to compute their integer floors.
\end{lemma}

\begin{proof}
    If $a = 0$, there is one root and its floor is $\lfloor -c/b\rfloor$.
    %
    Otherwise, the exact roots are:
    \begin{equation*}
        r_1 = \frac{-b + \sqrt{b^2 - 4ac}}{2a}, \quad\quad r_2 = \frac{-b - \sqrt{b^2 - 4ac}}{2a}.
    \end{equation*}
    Since
    $\floor{\frac{p}{q}} = \floor{\frac{\lfloor p \rfloor}{q}}$
    whenever $q \in \ZZ_{>0}$, the floored roots can be rewritten as
    \begin{equation*}
        \floor{r_1} = \floor{\frac{-\sign{a}b + \floor{\sign{a}\sqrt{b^2 - 4ac}}}{2|a|}},
    \end{equation*}
    \begin{equation*}
        \floor{r_2} = \floor{\frac{-\sign{a}b - \ceil{\sign{a}\sqrt{b^2 - 4ac}}}{2|a|}}.
\qedhere
    \end{equation*}
\end{proof}


\begin{lemma}[Lattice ray cast at hyperbola]
    \label{lemma:exists_lattice_ray_cast_alg}
    Let $n > 0$, ${\bf p} \in \RR^2$ and ${\bf v} \in \RR^2 \setminus \left\{(0, 0)\right\}$.

    There exists an algorithm which performs only $O(1)$ basic integer arithmetic operations (including
    at most two integer square roots) to compute
    \begin{equation*}
        \raycast(H_n, {\bf p}, {\bf v}) \coloneqq
        \begin{cases}
            \min M & \text{ if } M \ne \emptyset, \\
                 \infty & \text{ otherwise,}
        \end{cases}
    \end{equation*}
    where
    \begin{equation*}
        M = \left\{m \in \ZZ_{\ge 0}: \cardinal{\left\{{\bf p} + m{\bf v}, {\bf p} + (m+1){\bf v}\right\} \cap H_n} = 1\right\}.
    \end{equation*}
\end{lemma}

\begin{proof}
    Consider the function $f: \RR \to \RR$ defined as
    \[
         f(m) \coloneqq ({\bf p}_x + m {\bf v}_x)({\bf p}_y + m {\bf v}_y) - n.
    \]
    Observe that  $f(m) = am^2 + bm + c$ with
    \[
        a = {\bf v}_x {\bf v}_y, \quad b = ({\bf v}_x {\bf p}_y + {\bf v}_y {\bf p}_x), \quad c = {\bf p}_x {\bf p}_y - n,
    \]


    Every number $m$ in the set $M$ satisfies that the segment $\{{\bf p} + (m+t){\bf v}: t \in [0, 1]\}$ crosses the
    hyperbola $\{xy = n\}$. Put differently, $M$ is contained in $\{r_1,r_1+1,r_2,r_2+1\}$ where $r_1$ and $r_2$ are the floors of the roots of $f$, computed by Lemma~\ref{lemma:quadratic_formula}. Hence, we only need to check which of these four (or less, if $f$ has less than two real roots, or if $r_2\in \{r_1,r_1+1\}$) points indeed lie in $M$, and compute the minimum of them.

    By definition, an $m\in \ZZ$ lies in $M$ if and only if $m\ge 0$ and the two points $\{{\bf p}+m{\bf v}, {\bf p}+(m+1){\bf v}\}$ satisfy that one of them has both coordinates positive and with product $\ge n$ while the other either has product of coordinates $<n$ or has both coordinates negative. This can be checked in constant time.
\end{proof}
