\subsubsection{Right search bases}\label{subsubsec:rsb}

The following geometric property of two-dimen\-sio\-nal lattices will be used repeatedly in what follows:

\begin{lemma}
\label{lemma:convex_line}
    Let $X \subset \RR^2$ be a convex set, $\Lambda \subset \RR^2$ a lattice, and $P$ a half-plane delimited by a lattice line $\ell$.
    Let $\ell'$ be the next lattice line parallel to $\ell$ in the direction opposite to $P$.
    If $X \cap \ell' = \emptyset$ and $\cardinal{X \cap \ell} \ge 2$ then $X \cap \Lambda \subset P$.
\end{lemma}

\begin{proof}
    Let ${\bf p}, {\bf q}$ be two of the points in $X \cap \ell$, and suppose a lattice point
    ${\bf r}$ exists in $X \cap \Lambda \setminus P$.
    As all three points belong in $X$, which is convex, the triangle ${\bf p}{\bf q}{\bf r} \subseteq X$.
    Denote by ${\bf p}' = \overline{{\bf p}{\bf r}} \cap \ell'$, ${\bf q}' = \overline{{\bf q}{\bf r}} \cap \ell'$, and let
    $d = \operatorname{dist}({\bf r},\ell) / \operatorname{dist}(\ell, \ell') \in \ZZ_{\ge 2}$, the
    lattice distance between ${\bf r}$ and $\ell$.

    With this notation we have that ${\bf p}',{\bf q}' \in \tfrac1d\Lambda$ and, by Thales's Theorem,
    the length of segment $\ell' \cap {\bf p}{\bf q}{\bf r}$ must be $\tfrac{d - 1}{d} \abs{\overline{{\bf p}{\bf q}}}$.
    Hence, $\ell' \cap {\bf p}{\bf q}{\bf r}$ contains at least one lattice point in $X \cap \Lambda \cap \ell' = \emptyset$,
    so ${\bf r}$ cannot exist.
\end{proof}

Our algorithm to compute $\Nextpt({\bf p})$  is based on maintaining a basis of ${\bf p}+\Lambda$ with special properties.

\begin{definition}
    \label{def:right_search_basis}
    Let ${\bf p} \in H_n$ with ${\bf p} - {\bf b}_2 \notin H_n$.
    A \emph{right search basis for ${\bf p}$ in $H_{n,{\bf p}+\Lambda}$} is a lattice basis $(\textmono{in}, \textmono{out})$ of $\Lambda$
    satisfying
    \begin{enumerate}
        \item $\textmono{in}_x>0$, $\textmono{out}_x \ge 0$ and $\det(\textmono{in}, \textmono{out}) < 0$,
        \item ${\bf p} + \textmono{in} \in H_n$, ${\bf p} + \textmono{out} \notin H_n$.
        \item $\Nextpt({\bf p})  - {\bf p}$ lies in the closed cone generated by $\left\{\textmono{in}, \textmono{out}\right\}$.
        Equivalently, the slopes of $\textmono{in}$ and $\textmono{out}$ are, respectively, an upper and a lower bound for the slope of $\Minsl({\bf p})$.
    \end{enumerate}
\end{definition}

It is obvious that:

\begin{proposition}
    \label{prop:nextpt_in_cone}
    \label{prop:standard_is_rsb}
    If ${\bf b}_1, {\bf b}_2$ is the standard basis of $\Lambda$ then $({\bf b}_1, -{\bf b}_2)$ is a right search basis for every ${\bf p}\in H_n$ with ${\bf p}- {\bf b}_2 \notin H_n$.
\end{proposition}

\begin{proof}
    Condition (i) holds by construction.
    Condition (ii) follows for $\textmono{in} = {\bf b}_1$ from ${\bf p}\in H_n$ and ${{\bf b}_1}_x, {{\bf b}_1}_y \ge 0$, and it follows for $\textmono{out} = -{\bf b}_2$ by the hypothesis ${\bf p} - {\bf b}_2 \notin H_n$.
    For condition (iii) observe that the slope of $\Minsl({\bf p})$ lies in $[-\infty,0]$ by definition, and the slopes of ${\bf b}_1$ and $-{\bf b}_2$ are $\ge 0$ and $=-\infty$, respectively.
\end{proof}

Our algorithm to find $\Minsl({\bf p})$ and $\Nextpt({\bf p})$ (Algorithm~\ref{alg:compute_nextpt} below) starts with the standard basis and keeps updating a right search basis $(\textmono{in}, \textmono{out})$ relying for this in the following two lemmas, illustrated in Figure~\ref{fig:alg-update-steps}.

In both lemmas we have the following setting:
Let ${\bf p} \in H_n$ with ${\bf p} - {\bf b}_2 \notin H_n$ and let $(\textmono{in}, \textmono{out})$ be a right search basis for ${\bf p}$ in $H_{n,{\bf p}+\Lambda}$.
Since $ \Minsl({\bf p}) \in \cone{\textmono{in}, \textmono{out}}\cap \Lambda$ and $(\textmono{in}, \textmono{out})$ is a basis for $\Lambda$, there are unique $a,b\in \ZZ_{\ge 0}$ such that
\[
    \Minsl({\bf p}) = a\  \textmono{in} + b\ \textmono{out}.
\]

