\begin{lemma}
    \label{lemma:o}
     Let $\textmono{o} = \raycast(H_n, {\bf p} + \textmono{in}, \textmono{out})$ and $\textmono{in}' = \textmono{in} + \textmono{o} \cdot \textmono{out}$. Then:
    \begin{enumerate}
        \item $\textmono{o}\ne \infty$.
        \item $\Minsl({\bf p})$ lies in $\cone{\textmono{in}', \textmono{out}}$ but not in $\cone{\textmono{in}'+\textmono{out}, \textmono{out}}$.
        \item $(\textmono{in}', \textmono{out})$ is still a right search basis for ${\bf p}$.
        \item $\Minsl({\bf p}) = a' \textmono{in}' + b\ \textmono{out}$, where $a' = a \bmod b$.
    \end{enumerate}
\end{lemma}

\begin{proof}
        $\textmono{o}$ is chosen as the maximum non-negative integer such that
        ${\bf p} + \textmono{in} + \textmono{o}\cdot\textmono{out} = {\bf p} + \textmono{in}'$ is in $H_n$ while
        ${\bf p} + \textmono{in} + (\textmono{o} + 1)\cdot\textmono{out} = {\bf p} + \textmono{in}' + \textmono{out}$ is not.
        If this maximum was $\infty$, convexity of $H_n$ and the fact that ${\bf p} + \textmono{in}\in H_n$ implies that the whole ray ${\bf p} + \textmono{in}+ \RR_{\ge 0} \cdot \textmono{out}$ is contained in $H_n$.
        Since $H_n$ is convex and closed, this, in turn implies that any ray in the direction of $\textmono{out}$ and starting at a point of $H_n$ is also contained in $H_n$.
        In particular, this would happen for the ray starting at ${\bf p}$, but this contradicts the fact that ${\bf p} + \textmono{out} \notin H_n$. Hence, $\textmono{o}$ is never $\infty$.

        Parts (3) and (4) follow easily from (2), so we only need to prove (2).
        The first part of (2) follows from the fact that ${\bf p} + \textmono{in}'$ is in $H_n$, so that $\textmono{in}'$ is still an upper bpund for the slope of $\Minsl({\bf p})$. For the second part we apply Lemma~\ref{lemma:convex_line} as follows: Let $\ell$ be the line containing $\bf p$ and ${\bf p} +\textmono{in}'$ and let $\ell'$ be the line parallel to it passing through ${\bf p} +\textmono{out}$. Let
        \[
            X= ({\bf p} + [0,1)\cdot \textmono{in}' + \cone{\textmono{in}'+\textmono{out}, \textmono{out}}) \cup \{{\bf p} + \textmono{in}'\}.
        \]
        $X$ is convex since it is the union of a sum of convex sets (which is convex) and a point in the boundary of that sum. It contains the points $\bf p$ and ${\bf p} +\textmono{in}'$ from $\ell$, but no lattice point from $\ell'$ (since the only lattice points in $\ell' \cap X$ are $\textmono{out}$ and $\textmono{in}'+\textmono{out}$). Hence, no lattice point other than ${\bf p}$ lies in ${\bf p} + \cone{\textmono{in}'+\textmono{out}, \textmono{out}}$, which finishes the proof of (2).
\end{proof}


\begin{lemma}
    \label{lemma:i}
    Let $\textmono{i} = \raycast(H_n, {\bf p} + \textmono{out}, \textmono{in})$ and $\textmono{out}' = \textmono{out} + \textmono{i} \cdot \textmono{in}$. Then:
    \begin{enumerate}
        \item $\textmono{i} = \infty$ if and only if $\textmono{in} = \Minsl({\bf p})$. If this is not the case:
        \item $\Minsl({\bf p})$ lies in $\cone{\textmono{in}, \textmono{out}'}$. It only lies in $\cone{\textmono{in}, \textmono{in}+\textmono{out}'}$ if $\textmono{in}+\textmono{out}' = \Minsl({\bf p})$.
        \item $(\textmono{in}, \textmono{out}')$ is still a right search basis for ${\bf p}$.
        \item $\Minsl({\bf p}) = a'\ \textmono{in} + b\ \textmono{out}'$, where $a' = [(a-1) \bmod b] + 1$. (That is, $a' = a \bmod b$ unless $a$ divides $b$, in which case $a'=b$).
    \end{enumerate}
\end{lemma}

\begin{proof}
        One direction of part (1) is obvious: if $\textmono{in}=\Minsl({\bf p})$ then no  point of $H_{n,\Lambda}\cap\{x \ge {\bf p}_x\}$ lies below the line starting at ${\bf p}$ and with direction $\textmono{in}$.
        In particular,  no  point of $H_{n,\Lambda}$ lies in the ray starting at ${\bf p} +\textmono{out}$ with direction $\textmono{in}$, which implies that $\textmono{i} = \infty$.

        For the converse, let us consider the closed half-plane $P$ with ${\bf p}$ and ${\bf p} +\textmono{out}$ on its boundary and ${\bf p} +\textmono{in}$ in its interior.
        Let $X = P \cap H_n$ and let us apply Lemma~\ref{lemma:convex_line} to it, with $\ell$ being the line containing ${\bf p}$ and  ${\bf p} +\textmono{in}$, and $\ell'$ the one containing ${\bf p} +\textmono{out}$ and  ${\bf p} +\textmono{in}+\textmono{out}$.
        The fact that $\textmono{in}=\infty$ implies that $\ell'$ contains no lattice point of $X$, so the Lemma says that no point of $X$ lies below the line $\ell$.
        Hence, $\textmono{in}=\Minsl({\bf p})$.

        Parts (3) and (4) again follow easily from (2), taking into account the exceptional case $\textmono{in}+\textmono{out}' = \Minsl({\bf p})$ in part (2). In this case, $a=\textmono{i}+1$, $b=1$ and $a'=b=1$, as claimed. Conversely, if $a$ divides $b$, the fact that $\Minsl({\bf p})$ is primitive implies that $a=1$. Hence,
    \[
    \Minsl({\bf p}) =   \textmono{in} + b\ \textmono{out}.
    \]
    The definition of $\Minsl({\bf p})$ then implies that $b$ is the smallest integer for which $\textmono{in} + b\ \textmono{out}$ is in $H_n$ or, equivalently, that $b= \textmono{i}+1$.

        So we only need to prove (2).
        The fact that $\Minsl({\bf p})$ only lies in $\cone{\textmono{in}, \textmono{in}+\textmono{out}'}$ if $\textmono{in}+\textmono{out}' = \Minsl({\bf p})$ is easy: $\Minsl({\bf p})$ certainly lies in $\cone{\textmono{in}+\textmono{out}', \textmono{out}}$ because $(textmono{in}, \textmono{out})$ was a right search basis and ${\bf p} +\textmono{in}+\textmono{out}' \in H_n$.
        To show that $\Minsl({\bf p})$ lies in $\cone{\textmono{in}, \textmono{out}'}$ we are going to apply Lemma~\ref{lemma:convex_line} to the convex set $X = H_n \cap \{x>{\bf p}_x\}$.
    Observe that the four points ${\bf p}$, ${\bf p}+ \textmono{in}$, ${\bf p} + \textmono{out} + \textmono{i} \cdot \textmono{in}$ and ${\bf p} + \textmono{out} + (\textmono{i} + 1)\cdot \textmono{in}$ form a parallelepiped with
    \begin{align*}
        &{\bf p}\in H_n\setminus X, \qquad\qquad {\bf p} + \textmono{out} + \textmono{i} \cdot \textmono{in} = {\bf p} + \textmono{out}' \notin H_n,
        \\
        &{\bf p}+ \textmono{in}\in X, \quad\qquad {\bf p} + \textmono{out} + (\textmono{i} +1) \cdot \textmono{in} = {\bf p} + \textmono{out}' + \textmono{in} \in X.
    \end{align*}

    The parallelepiped is unimodular since
    \[
        \det(\textmono{out} + \textmono{i} \cdot \textmono{in}, \textmono{in}) = \det(\textmono{out}, \textmono{in}) = \det(\Lambda).
    \]
    Hence, the lines $\ell$ and $\ell'$ containing respectively $\{{\bf p}+ \textmono{in}, \quad {\bf p} + \textmono{out}' +  \textmono{in}\}$ and $\{{\bf p}, {\bf p} + \textmono{out}' \}$ are consecutive parallel lines, with $\ell$ above $\ell'$.
    The first one contains at least the two lattice points of $X$ defining it, and the second one contains no lattice point of $X$ because of the following argument.
    If it did, such lattice points must be of the form
    \[
        {\bf p} + k(\textmono{out} + \textmono{i} \cdot \textmono{in})
    \]
    for some $k>1$ and convexity of $H_n$ would then imply that ${\bf p} + \textmono{out} + \textmono{i} \cdot \textmono{in} \in H_n$, a contradiction with the definition of $\textmono{i}$.
    Hence, Lemma~\ref{lemma:convex_line} implies that all lattice points of $X$ lie on or above $\ell$, which is equivalent to saying that $\textmono{out}'$ is a lower bound for the slope of $\Minsl({\bf p})$, hence $\Minsl({\bf p}) \in \cone{\textmono{in}, \textmono{out}'}$.
\end{proof}

\subsubsection{The algorithm}\label{subsubsec:rsmin}

Theorem~\ref{thm:exists_find_nextpt} is proven by Algorithm~\ref{alg:compute_nextpt}, summarized as follows:
After computing a standard basis and moving the point ${\bf p}$ vertically down as much as possible, the algorithm uses the standard basis as an initial right search basis and then updates it by iterating the procedures of Lemmas~\ref{lemma:o} and~\ref{lemma:i} in turns.

\begin{algorithm}
    \caption{Compute $\Nextpt({\bf p})$.}
    \label{alg:compute_nextpt}

    \DontPrintSemicolon
    \SetKwInOut{Input}{Input}
    \SetKwInOut{Output}{Output}

    \Input{$\Lambda = \left\langle{\bf b}_1, {\bf b}_2\right\rangle \subseteq \QQ^2$ with
        ${{\bf b}_1}_x > 0, {{\bf b}_2}_x = 0, 0 \le {{\bf b}_1}_y < {{\bf b}_2}_y$, $n >0 $, ${\bf p} \in H_n$.}
    \Output{$\Nextpt({\bf p})$}

    \SetKwProg{Fn}{Function}{}{end}
    \Fn{\textmono{nextpt(}${\bf b}_1$, ${\bf b}_2\typeHint{\in \NonZero\Lambda}$, $n\typeHint{ > 0}$, ${\bf p}\typeHint{\in H_n}$\textmono{)}$\typeHint{\to {\scriptstyle H_{n,{\bf p}+\Lambda}\,\cup\;\left\{\infty\right\}}}$} {
        \If {${\bf p} - {\bf b}_2 \in H_n$} {\Return ${\bf p} - \textmono{raycast(}H_n,\,{\bf p},\,-{\bf b}_2\textmono{)}\cdot{\bf b}_2$}
        $\textmono{in},\,\textmono{out}\typeHint{\in \NonZero\Lambda} \gets {\bf b}_1,\,-{\bf b}_2$\;
        $\textmono{minsl} \typeHint{\in \NonZero\Lambda \cup \left\{\square\right\}} \gets \square$\;
        \While {$\textmono{minsl} = \square$} {
            $\textmono{o} \typeHint{\in \ZZ_{\ge 0}} \gets \textmono{raycast(}H_n,\,{\bf p} + \textmono{in},\,\textmono{out}\textmono{)}$\;
            \label{line:m_in}
            $\textmono{in} \gets \textmono{in} + \textmono{o}\cdot\textmono{out}$\;
            \label{line:update_in}
            $\textmono{i} \typeHint{\in \ZZ_{>0} \cup \left\{\infty\right\}} \gets \textmono{raycast(}H_n,\,{\bf p} + \textmono{out},\,\textmono{in}\textmono{)}$\;
            \label{line:m_out}
            \uIf {$\textmono{i} < \infty$} {
                $\textmono{out} \gets \textmono{out} + \textmono{i}\cdot\textmono{in}$
                \label{line:update_out}
            } \lElse {$\textmono{minsl} \gets \textmono{in}$}
        }
        $\textmono{m} \typeHint{\in \ZZ_{>0} \cup \left\{\infty\right\}} \gets \textmono{raycast(}H_n,\,{\bf p},\,\textmono{minsl}\textmono{)}$\;
        \uIf {$\textmono{m} = \infty$} {\Return $\infty$}
        \lElse {\Return ${\bf p} + \textmono{raycast(}H_n,\,{\bf p},\,\textmono{minsl}\textmono{)}\cdot\textmono{minsl}$}
    }
\end{algorithm}

The correctness and running time of the algorithm follows from the fact that at every iteration the search cone is narrowed, as illustrated in Figure~\ref{fig:alg-update-steps}, performing an agile binary search within the Stern-Brocot tree~\cite{Yan2013Number} until the slope of $\Minsl({\bf p})$. In other words, the algorithm is essentially following the same steps as the Euclidean algorithm would follow to compute a $\gcd$.



\begin{proof}[Proof of Theorem~\ref{thm:exists_find_next_vertex}]
    In the first lines of Algorithm~\ref{alg:compute_nextpt} we compute a standard basis and use it to output the bottommost lattice point of $H_n$ in the line $\{x={\bf p}_x\}$ if ${\bf p} \setminus {\bf b}_2 \in H_n$.
    If this is not the case then the algorithm uses the standard basis as an initial right search basis (Proposition~\ref{prop:standard_is_rsb}).
    After that the algorithm enters a loop in which the right search basis is modified as in Lemmas~\ref{lemma:o} and~\ref{lemma:i} (hence it remains a right search basis) and it only exits the loop when $\textmono{i}=\infty$ which, by Lemma~\ref{lemma:i}, implies that we have indeed found $\Minsl({\bf p}) = \textmono{in}$.
    The lines after the loop compute $\Nextpt({\bf p})$ from $\Minsl({\bf p})$.

    Each iteration of the ``while'' loop takes $O(1)$ operations by Lemma~\ref{lemma:exists_lattice_ray_cast_alg}. The only thing left to be proven is that, assuming $\Lambda$ reduced and ${\bf p}_y\notin (1,2)$, the algorithm terminates in $O(\log(n+\det \Lambda))$ iterations of the loop. To show this, let $a$ and $b$ be the coefficients from Lemmas~\ref{lemma:o} and~\ref{lemma:i} for our initial situation $\textmono{in}={\bf b}_1, \textmono{out}=-{\bf b}_2$. That is, $a, b\in \ZZ_{> 0}$ and
    \begin{align}
    \label{eq:a_and_b}
        \Minsl({\bf p}) = a\ {\bf b}_1 - b\ {\bf b}_2.
    \end{align}
    Consider the following algorithm to compute $\gcd(a,b)$:

    \begin{algorithm*}[H]
        \caption{Greatest common divisor.}
        \label{alg:gcd}

        \DontPrintSemicolon
%    \SetKwInOut{Input}{Input}
%    \SetKwInOut{Output}{Output}
%
%    \Input{$a,b \in \ZZ_{> 0}$}
%    \Output{$\gcd(a,b)$}
%
        \SetKwProg{Fn}{Function}{}{end}
        \Fn{\textmono{gcd(}$\textmono{a},\textmono{b}\typeHint{\in \ZZ_{>0}}$\textmono{)}$\typeHint{\to {\scriptstyle \ZZ_{>0}}}$} {
            \While {$\textmono{a}  \bmod\textmono{b} \ne 0$} {
                $\textmono{a} \gets \textmono{a}  \bmod\textmono{b}$\;
                $\textmono{b} \gets ((\textmono{b}-1) \bmod \textmono{a}) + 1$\;
            }
            \Return $\textmono{b}$\;
        }
    \end{algorithm*}
    This is the usual Euclidean algorithm, except we break the symmetry between $a$ and $b$ and take the representatives for $\textmono{b} \bmod \textmono{a}$ in $\{1,\dots, \textmono{a}\}$ instead of $\{0, \dots, \textmono{a}-1\}$.
    Thus, when the standard algorithm would get $\textmono{b}=0$ (and return $\textmono{a}$) ours gets $\textmono{b} = \textmono{a}$, which makes it exit the loop and return $\textmono{b}$.
    (When the standard algorithm would make $\textmono{a}=0$ and return $\textmono{b}$, ours does the same).

    Now, part (4) of Lemmas~\ref{lemma:o} and~\ref{lemma:i} implies that if we perform simultaneously each iteration of Algorithms~\ref{alg:compute_nextpt} and~\ref{alg:gcd}, the equation
    \[
        \Minsl({\bf p}) = \textmono{a}\ \textmono{in} + \textmono{b}\ \textmono{out}
    \]
    remains always true.
    Hence, both algorithms do the same number of iterations and this number is well-known to lie in $O(\log(\min\{a,b\}))$ for Algorithm~\ref{alg:gcd}. Hence, this is what to need to bound.

    For this, the fact that $\Lambda$ is reduced implies that ${{\bf b}_1}_x =1$ and ${{\bf b}_2}_x =0$, so Eq.~\ref{eq:a_and_b} implies that $a$ equals the $x$ coordinate of $\Minsl({\bf p})$.
    By Lemma~\ref{lemma:exception}, this is bounded by $2n+2\Delta$.
%RESCATE 6
\end{proof}

\begin{remark}
    \label{remark:generalized_algorithm_condition}
    The correctness of Algorithm~\ref{alg:compute_nextpt} follows from Lemmas~\ref{lemma:o} and~\ref{lemma:i}, which rely solely on the convexity of the hyperbola.
    Hence, if $H$ is the region above the graph of a convex function $f: \RR^2 \to \RR^2$, our algorithms can easily be adapted to compute $\conv{H \cap ({\bf p} + \Lambda)}$ as long as there is a lattice ray intersection algorithm $\raycast(H, {\bf p}, {\bf v})$ analogous to the one of Lemma~\ref{lemma:exists_lattice_ray_cast_alg}.

    Indeed, let ${\bf p} \in H$ be such that ${\bf p} - {\bf b}_2 \notin X$, where ${\bf b}_1, {\bf b}_2$ is the standard basis of $\Lambda$.
    The standard basis ${\bf b}_1, {\bf b}_2$ may no longer be a right search basis, but one right search basis for  ${\bf p}$ can be obtained using $\textmono{out}=-{\bf b}_2$ and computing $\textmono{in}$ via a single lattice ray cast from ${\bf p} + {\bf b}_1$ in the direction of $\pm {\bf b}_2$, depending on whether ${\bf p} + {\bf b}_1$ is in $X$ or not. The rest of our algorithms work with no change (although their complexity will depend on the particular $f$).
